import { useState, useEffect, useCallback, useTransition } from 'react';
import { format, subDays, startOfDay, endOfDay, startOfMonth, endOfMonth } from 'date-fns';
import { AlertTriangle, DollarSign, Package, ShoppingCart, TrendingUp } from 'lucide-react';
import { dashboardMetricsService, type ExecutiveDashboardData } from '../../../services/domains/dashboard/DashboardMetricsService';
import {
  type DateRange, type DailySale, type DebtCustomer, type KPI,
  type LowStockItem, type RecentInvoice, type TopProduct, formatCurrency,
} from '../../../types/dashboard/executive';

export function useExecutiveDashboard() {
  const [range, setRange] = useState<DateRange>('month');
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [kpis, setKpis] = useState<KPI[]>([]);
  const [dailySales, setDailySales] = useState<DailySale[]>([]);
  const [topProducts, setTopProducts] = useState<TopProduct[]>([]);
  const [recentInvoices, setRecentInvoices] = useState<RecentInvoice[]>([]);
  const [debtCustomers, setDebtCustomers] = useState<DebtCustomer[]>([]);
  const [branchData, setBranchData] = useState<{ name: string; value: number }[]>([]);
  const [lowStock, setLowStock] = useState<LowStockItem[]>([]);
  const [lastRefresh, setLastRefresh] = useState(new Date());
  const [isPending, startTransition] = useTransition();

  const getRangeDates = useCallback(() => {
    const now = new Date();
    switch (range) {
      case 'today': return { from: startOfDay(now), to: endOfDay(now) };
      case 'week': return { from: startOfDay(subDays(now, 6)), to: endOfDay(now) };
      case 'month': return { from: startOfMonth(now), to: endOfMonth(now) };
      case 'year': return { from: new Date(now.getFullYear(), 0, 1), to: new Date(now.getFullYear(), 11, 31, 23, 59, 59) };
    }
  }, [range]);

  const loadData = useCallback(async () => {
    // Allow spinner to render first by yielding to main thread
    await new Promise(resolve => setTimeout(resolve, 0));

    startTransition(() => {
      setLoading(true);
      setLoadError(null);
    });

    try {
      const { from, to } = getRangeDates();
      const res = await dashboardMetricsService.getExecutiveDashboardData(format(from, 'yyyy-MM-dd'), format(to, 'yyyy-MM-dd'));
      if (!res) return;

      startTransition(() => {
        setKpis([
          {
            label: 'إجمالي المبيعات',
            value: formatCurrency(res.total),
            sub: `${res.invoiceCount} فاتورة`,
            trend: parseFloat(res.salesTrend) >= 0 ? 'up' : 'down',
            trendValue: `${res.salesTrend}% مقارنة بالأمس`,
            icon: ShoppingCart,
            color: 'text-sky-600',
            bg: 'bg-sky-500/10 border-sky-500/20',
          },
          {
            label: 'صافي الربح',
            value: formatCurrency(res.profit),
            sub: `هامش ${res.margin}%`,
            trend: res.profit >= 0 ? 'up' : 'down',
            icon: TrendingUp,
            color: 'text-emerald-600',
            bg: 'bg-emerald-500/10 border-emerald-500/20',
          },
          {
            label: 'المقبوضات',
            value: formatCurrency(res.totalReceived),
            sub: 'نقدي وشبكة',
            trend: 'neutral',
            icon: DollarSign,
            color: 'text-violet-600',
            bg: 'bg-violet-500/10 border-violet-500/20',
          },
          {
            label: 'المشتريات',
            value: formatCurrency(res.totalPurchases),
            sub: 'بضاعة واردة',
            trend: 'neutral',
            icon: Package,
            color: 'text-amber-600',
            bg: 'bg-amber-500/10 border-amber-500/20',
          },
          {
            label: 'الديون المستحقة',
            value: formatCurrency(res.totalDebt),
            sub: 'ذمم العملاء',
            trend: res.totalDebt > 50000 ? 'down' : 'neutral',
            icon: AlertTriangle,
            color: 'text-rose-600',
            bg: 'bg-rose-500/10 border-rose-500/20',
          },
        ]);

        setDailySales(res.dailySalesData);
        setTopProducts(res.topProductsData);
        setRecentInvoices(res.recentInvoicesData);
        setDebtCustomers(res.debtCustomersData);
        setBranchData(res.branchDataList);
        setLowStock(res.lowStockData);
        setLastRefresh(new Date());
      });
    } catch (e) {
      console.error('Executive Dashboard error:', e);
      startTransition(() => {
        setLoadError(e instanceof Error ? e.message : 'تعذر تحميل بيانات لوحة المؤشرات.');
      });
    } finally {
      startTransition(() => {
        setLoading(false);
      });
    }
  }, [getRangeDates]);

  useEffect(() => { loadData(); }, [loadData]);

  return {
    range, setRange, loading: loading || isPending, loadError, kpis, dailySales, topProducts,
    recentInvoices, debtCustomers, branchData, lowStock, lastRefresh, refresh: loadData,
  };
}

import { useCallback, useEffect, useMemo, useState, useTransition } from 'react';
import { dashboardMetricsService, type OverviewDashboardData as ServiceOverviewData } from '../../../services/domains/dashboard/DashboardMetricsService';
import { AccountingService, type DashboardMetrics, type MonthlyComparison } from '../../../services/domains/finance/AccountingService';
import { getProductUnitLabel } from '../../../utils/products/productUnits';
import type {
  CategoryDistributionItem, PaymentDistributionItem, PurchaseHourlyBucket,
  PurchasePaymentMixItem, PurchaseTopItem, PurchaseTopSupplier, RecentActivityItem, SalesTrendPoint,
  TopCustomerItem, TopSellingProduct,
} from '../../../types/dashboard/components';
import type { DailyPurchaseResult } from '../../../services/domains/operations/DailyOperationsService';

// Translate payment method to Arabic
const translatePaymentMethod = (method: string): string => {
  const translations: Record<string, string> = {
    'CASH': 'نقدي',
    'CARD': 'بطاقة',
    'BANK_TRANSFER': 'تحويل بنكي',
    'CHECK': 'شيك',
    'VOUCHER': 'قسيمة',
  };
  return translations[method] ?? method;
};

export interface OverviewDashboardData {
  metrics: DashboardMetrics | null;
  chartData: SalesTrendPoint[];
  topProducts: TopSellingProduct[];
  loading: boolean;
  refreshing: boolean;
  dashboardError: string | null;
  monthlyComparison: MonthlyComparison | null;
  topCustomers: TopCustomerItem[];
  categorySales: CategoryDistributionItem[];
  gradeSales: { grade: string; quantityM2: number; totalRevenue: number }[];
  paymentDistribution: PaymentDistributionItem[];
  recentActivities: RecentActivityItem[];
  todayPurchases: ServiceOverviewData['todayPurchases'] | null;
  purchasesLoading: boolean;
  purchasesError: string | null;
  loadData: () => void;
  purchaseHourly: PurchaseHourlyBucket[];
  purchasePeakHour: number;
  purchasePaymentMix: PurchasePaymentMixItem[];
  purchaseTopSuppliers: PurchaseTopSupplier[];
  purchaseTopItems: PurchaseTopItem[];
  purchaseQuantitiesByUnit: [string, number][];
}

export const useOverviewDashboardData = (): OverviewDashboardData => {
  const [metrics, setMetrics] = useState<DashboardMetrics | null>(null);
  const [chartData, setChartData] = useState<SalesTrendPoint[]>([]);
  const [topProducts, setTopProducts] = useState<TopSellingProduct[]>([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [dashboardError, setDashboardError] = useState<string | null>(null);
  const [isPending, startTransition] = useTransition();

  const [monthlyComparison, setMonthlyComparison] = useState<MonthlyComparison | null>(null);
  const [topCustomers, setTopCustomers] = useState<TopCustomerItem[]>([]);
  const [categorySales, setCategorySales] = useState<CategoryDistributionItem[]>([]);
  const [gradeSales, setGradeSales] = useState<{ grade: string; quantityM2: number; totalRevenue: number }[]>([]);
  const [paymentDistribution, setPaymentDistribution] = useState<PaymentDistributionItem[]>([]);
  const [recentActivities, setRecentActivities] = useState<RecentActivityItem[]>([]);
  const [todayPurchases, setTodayPurchases] = useState<ServiceOverviewData['todayPurchases'] | null>(null);
  const [purchasesLoading, setPurchasesLoading] = useState(true);
  const [purchasesError, setPurchasesError] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    const dashboardStartedAt = performance.now();
    // Allow spinner to render first
    await new Promise(resolve => setTimeout(resolve, 0));

    startTransition(() => {
      setRefreshing(true);
      setPurchasesLoading(true);
    });

    try {
      const data = await dashboardMetricsService.getOverviewDashboardData();

      // Check for partial errors
      const errors = dashboardMetricsService.getErrors();
      if (errors.length > 0) {
        const errorMessages = errors.map(e => `${e.section}: ${e.message}`).join('; ');
        startTransition(() => {
          setDashboardError(`تحميل جزئي: ${errorMessages}`);
        });
      } else {
        startTransition(() => {
          setDashboardError(null);
        });
      }

      startTransition(() => {
        setMetrics(data.metrics);
        setChartData(data.chartData);
        setTopProducts(data.topProducts);
        setMonthlyComparison(data.monthlyComparison);
        setTopCustomers(data.topCustomers);
        setCategorySales(data.categorySales);
        setGradeSales(data.gradeSales);
        setPaymentDistribution(data.paymentDistribution);
        setRecentActivities(data.recentActivities);
        setTodayPurchases(data.todayPurchases);
        setPurchasesError(data.purchasesError);
      });
    } catch (e) {
      console.error(e);
      startTransition(() => {
        setDashboardError((e as Error)?.message || 'تعذر تحميل بيانات لوحة المعلومات');
      });
    } finally {
      console.info('[performance] Dashboard data ready', JSON.stringify({
        durationMs: Math.round((performance.now() - dashboardStartedAt) * 100) / 100,
      }));
      startTransition(() => {
        setLoading(false);
        setPurchasesLoading(false);
        setRefreshing(false);
      });
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const purchaseHourly = useMemo(() => {
    const buckets = Array.from({ length: 24 }, () => ({ total: 0, count: 0 }));
    todayPurchases?.rows.forEach((row) => {
      const date = new Date(row.createdAt);
      if (Number.isNaN(date.getTime())) return;
      buckets[date.getHours()].total += Number(row.total) || 0;
      buckets[date.getHours()].count += 1;
    });
    return buckets;
  }, [todayPurchases]);

  const purchasePeakHour = Math.max(...purchaseHourly.map((bucket) => bucket.total), 0);

  const purchasePaymentMix = useMemo(() => {
    const mix = new Map<string, { total: number; count: number }>();
    todayPurchases?.rows.forEach((row) => {
      const key = row.paymentType || 'CASH';
      const entry = mix.get(key) || { total: 0, count: 0 };
      entry.total += Number(row.total) || 0;
      entry.count += 1;
      mix.set(key, entry);
    });
    return [...mix.entries()]
      .map(([method, values]) => ({ method: translatePaymentMethod(method), ...values }))
      .sort((a, b) => b.total - a.total);
  }, [todayPurchases]);

  const purchaseTopSuppliers = useMemo(() => {
    const suppliers = new Map<string, { name: string; total: number; paid: number; count: number }>();
    todayPurchases?.rows.forEach((row) => {
      const key = row.supplierId || row.supplierName || 'unknown';
      const supplier = suppliers.get(key) || { name: row.supplierName || '—', total: 0, paid: 0, count: 0 };
      supplier.total += Number(row.total) || 0;
      supplier.paid += Number(row.paid) || 0;
      supplier.count += 1;
      suppliers.set(key, supplier);
    });
    return [...suppliers.values()].sort((a, b) => b.total - a.total).slice(0, 4);
  }, [todayPurchases]);

  const purchaseTopItems = useMemo(() => {
    const products = new Map<string, { name: string; quantity: number; total: number; invoices: Set<string>; productType?: 'CERAMIC' | 'GENERAL'; baseUnit?: string; customUnit?: string }>();
    todayPurchases?.items.forEach((item) => {
      const key = item.productId || item.productName;
      const product = products.get(key) || { name: item.productName || '—', quantity: 0, total: 0, invoices: new Set<string>(), productType: item.productType, baseUnit: item.baseUnit, customUnit: item.customUnit };
      product.quantity += Number(item.quantityM2) || 0;
      product.total += Number(item.totalCost) || 0;
      product.invoices.add(item.purchaseId);
      products.set(key, product);
    });
    return [...products.values()].sort((a, b) => b.total - a.total).slice(0, 4);
  }, [todayPurchases]);

  const purchaseQuantitiesByUnit = useMemo(() => {
    const quantities = new Map<string, number>();
    todayPurchases?.items.forEach((item) => {
      const unit = getProductUnitLabel(item);
      quantities.set(unit, (quantities.get(unit) || 0) + (Number(item.quantityM2) || 0));
    });
    return [...quantities.entries()];
  }, [todayPurchases]);

  return {
    metrics,
    chartData,
    topProducts,
    loading: loading || isPending,
    refreshing,
    dashboardError,
    monthlyComparison,
    topCustomers,
    categorySales,
    gradeSales,
    paymentDistribution,
    recentActivities,
    todayPurchases,
    purchasesLoading,
    purchasesError,
    loadData,
    purchaseHourly,
    purchasePeakHour,
    purchasePaymentMix,
    purchaseTopSuppliers,
    purchaseTopItems,
    purchaseQuantitiesByUnit,
  };
};

import { useCallback, useRef, useState } from 'react';
import { DatabaseManager } from '../../../database/repositories/databaseManager';
import { initDatabaseAsync, isDatabaseReady } from '../../../database/databaseAsyncService';

export type UseDatabaseAsyncResult<T> = {
  data: T | null;
  loading: boolean;
  error: Error | null;
  isReady: boolean;
  runQuery: (sql: string, params?: unknown[]) => Promise<T[]>;
  runCommand: (sql: string, params?: unknown[]) => Promise<void>;
  runExec: (sql: string) => Promise<void>;
  exportDb: () => Promise<Uint8Array>;
  importDb: (bytes: Uint8Array) => Promise<void>;
  reset: () => void;
};

/**
 * هووك React لتنفيذ عمليات قاعدة البيانات بشكل غير متزامن عبر Web Worker.
 * يمنع تجميد واجهة المستخدم عند الضغط على أي زر (تحديث، حفظ، حذف، إلخ).
 *
 * الاستخدام:
 *   const { runQuery, runCommand, loading, error } = useDatabaseAsync();
 *   await runQuery('SELECT * FROM products WHERE is_active = 1');
 *   await runCommand('UPDATE customers SET name = ? WHERE id = ?', ['أحمد', 'cust_123']);
 */
export function useDatabaseAsync<T = unknown>(): UseDatabaseAsyncResult<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const db = DatabaseManager.getInstance();

  const runQuery = useCallback(async (sql: string, params: unknown[] = []): Promise<T[]> => {
    setLoading(true);
    setError(null);
    try {
      const result = await db.queryAsync<T>(sql, params);
      setData(result as unknown as T);
      return result;
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setLoading(false);
    }
  }, [db]);

  const runCommand = useCallback(async (sql: string, params: unknown[] = []): Promise<void> => {
    setLoading(true);
    setError(null);
    try {
      await db.runAsync(sql, params);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setLoading(false);
    }
  }, [db]);

  const runExec = useCallback(async (sql: string): Promise<void> => {
    setLoading(true);
    setError(null);
    try {
      await db.execAsync(sql);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setLoading(false);
    }
  }, [db]);

  const exportDb = useCallback(async (): Promise<Uint8Array> => {
    setLoading(true);
    setError(null);
    try {
      return await db.exportDatabaseAsync();
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setLoading(false);
    }
  }, [db]);

  const importDb = useCallback(async (bytes: Uint8Array): Promise<void> => {
    setLoading(true);
    setError(null);
    try {
      await db.importDatabaseAsync(bytes);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      setError(e);
      throw e;
    } finally {
      setLoading(false);
    }
  }, [db]);

  const reset = useCallback(() => {
    setData(null);
    setError(null);
    setLoading(false);
  }, []);

  return {
    data,
    loading,
    error,
    isReady: isDatabaseReady(),
    runQuery,
    runCommand,
    runExec,
    exportDb,
    importDb,
    reset,
  };
}

/**
 * تهيئة Web Worker لقاعدة البيانات (يُستدعى مرة واحدة عند بدء التطبيق).
 */
export async function initializeDatabaseAsync(): Promise<void> {
  if (isDatabaseReady()) return;
  await initDatabaseAsync();
}

import React, { useEffect, useMemo, useState } from 'react';
import { ArrowUp, ArrowDown, Eye, EyeOff, Save, RotateCcw, GripVertical, Plus, X } from 'lucide-react';
import { NavigationService, type NavOverrides } from '../../../services/domains/config/NavigationService';
import { AuthService } from '../../../services/domains/auth/AuthService';
import { usePermission } from '../../../hooks/domains/auth/usePermission';
import { useToast } from '../../../components/ui/Toast';

export const AdminNavigationTab: React.FC = () => {
  const toast = useToast();
  const can = usePermission();
  const readOnly = !can('admin.navigation');
  const [overrides, setOverrides] = useState<NavOverrides>(() => NavigationService.getOverrides());
  const [dirty, setDirty] = useState(false);

  const [newGroupName, setNewGroupName] = useState('');
  const [newGroupPages, setNewGroupPages] = useState<string[]>([]);
  const [showCreate, setShowCreate] = useState(false);

  const groups = useMemo(
    () => NavigationService.merge(overrides, { includeHidden: true }),
    [overrides]
  );

  useEffect(() => {
    setOverrides(NavigationService.getOverrides());
  }, []);

  const update = (patch: Partial<NavOverrides>) => {
    setOverrides((prev) => ({ ...prev, ...patch }));
    setDirty(true);
  };

  const isHidden = (path: string) => overrides.hidden.includes(path);
  const isGroupHidden = (groupId: string) => overrides.hiddenGroups.includes(groupId);
  const toggleHidden = (path: string) => {
    const hidden = isHidden(path)
      ? overrides.hidden.filter((p) => p !== path)
      : [...overrides.hidden, path];
    update({ hidden });
  };
  const toggleGroupHidden = (groupId: string) => {
    const hiddenGroups = isGroupHidden(groupId)
      ? overrides.hiddenGroups.filter((g) => g !== groupId)
      : [...overrides.hiddenGroups, groupId];
    update({ hiddenGroups });
  };

  const rename = (path: string, label: string) => {
    update({ labels: { ...overrides.labels, [path]: label } });
  };

  const moveItem = (groupId: string, path: string, direction: -1 | 1) => {
    const group = groups.find((g) => g.id === groupId);
    if (!group) return;
    const paths = group.items.map((item) => item.to);
    const index = paths.indexOf(path);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= paths.length) return;
    paths.splice(index, 1);
    paths.splice(target, 0, path);
    update({ itemsOrder: { ...overrides.itemsOrder, [groupId]: paths } });
  };

  const moveItemToGroup = (sourceGroupId: string, path: string, targetGroupId: string) => {
    if (sourceGroupId === targetGroupId || !groups.some((group) => group.id === targetGroupId)) return;
    const itemsOrder = Object.fromEntries(
      Object.entries(overrides.itemsOrder).map(([groupId, paths]) => [
        groupId,
        paths.filter((itemPath) => itemPath !== path),
      ])
    );
    const targetPaths = groups.find((group) => group.id === targetGroupId)?.items
      .map((item) => item.to)
      .filter((itemPath) => itemPath !== path) ?? [];
    itemsOrder[targetGroupId] = [...targetPaths, path];
    update({
      groupAssignments: { ...overrides.groupAssignments, [path]: targetGroupId },
      itemsOrder,
    });
  };

  const moveGroup = (groupId: string, direction: -1 | 1) => {
    const order = groups.map((g) => g.id);
    const index = order.indexOf(groupId);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= order.length) return;
    order.splice(index, 1);
    order.splice(target, 0, groupId);
    update({ groupsOrder: order });
  };

  const duplicateName = useMemo(() => {
    const name = newGroupName.trim();
    if (!name) return false;
    return groups.some((g) => (overrides.labels[`group:${g.id}`] ?? g.label).trim() === name);
  }, [newGroupName, groups, overrides.labels]);

  const createGroup = () => {
    if (readOnly) return;
    const name = newGroupName.trim();
    if (!name) {
      toast.error('أدخل اسم القائمة');
      return;
    }
    if (duplicateName) {
      toast.error('اسم القائمة مكرر، اختر اسمًا آخر');
      return;
    }
    const id = `custom-${Date.now()}`;
    const customGroups = [...(overrides.customGroups ?? []), { id, label: name }];
    const groupAssignments = { ...overrides.groupAssignments };
    const itemsOrder = { ...overrides.itemsOrder };
    newGroupPages.forEach((path) => {
      groupAssignments[path] = id;
      const targetPaths = groups.find((g) => g.id === id)?.items.map((i) => i.to) ?? [];
      itemsOrder[id] = [...(itemsOrder[id] ?? []), path];
    });
    update({ customGroups, groupAssignments, itemsOrder, labels: { ...overrides.labels, [`group:${id}`]: name } });
    setNewGroupName('');
    setNewGroupPages([]);
    setShowCreate(false);
    toast.success('تم إنشاء القائمة');
  };

  const save = () => {
    try {
      NavigationService.saveOverrides(overrides, AuthService.getCurrentUser());
      setDirty(false);
      toast.success('تم حفظ تخصيص القوائم.');
    } catch (error: any) {
      toast.error('تعذر الحفظ', error?.message);
    }
  };

  const reset = () => {
    if (!window.confirm('إرجاع القوائم إلى الوضع الافتراضي، بما يشمل ترتيب الصفحات ونقلها وتسمياتها؟')) return;
    setOverrides({
      hidden: [],
      hiddenGroups: [],
      labels: {},
      groupsOrder: [],
      itemsOrder: {},
      groupAssignments: {},
      customGroups: [],
    });
    setDirty(true);
  };

  const hiddenItems = groups.flatMap((g) => g.items.filter((it) => isHidden(it.to)).map((it) => ({ group: g, item: it })));
  const hiddenGroups = groups.filter((g) => isGroupHidden(g.id));

  const allPages = groups.flatMap((g) => g.items.map((it) => ({ group: g, item: it })));

  return (
    <div className="space-y-4">
      <div className="flex flex-wrap items-center justify-between gap-2 rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4">
        <div>
          <h3 className="text-sm font-extrabold text-slate-900 dark:text-slate-100">محرر قوائم التنقّل</h3>
          <p className="text-[11px] text-slate-500 dark:text-slate-400">
            انقل الصفحات بين القوائم، أو أعد ترتيبها وتسميتها أو إخفاءها. الإخفاء هنا يطبق على كل المستخدمين.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => setShowCreate(true)} disabled={readOnly} className="flex items-center gap-1.5 rounded-xl border border-slate-200 dark:border-slate-700 px-3 py-2 text-xs font-bold text-slate-600 hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-40">
            <Plus className="h-3.5 w-3.5" /> قائمة جديدة
          </button>
          <button onClick={reset} className="flex items-center gap-1.5 rounded-xl border border-slate-200 dark:border-slate-700 px-3 py-2 text-xs font-bold text-slate-500 hover:bg-slate-100 dark:hover:bg-slate-800">
            <RotateCcw className="h-3.5 w-3.5" /> افتراضي
          </button>
          <button onClick={save} disabled={readOnly || !dirty} className="flex items-center gap-1.5 rounded-xl bg-emerald-600 px-4 py-2 text-xs font-bold text-white hover:bg-emerald-700 disabled:opacity-40">
            <Save className="h-4 w-4" /> حفظ القوائم
          </button>
        </div>
      </div>

      {showCreate && (
        <div className="rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4 space-y-3">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-extrabold">إنشاء قائمة جديدة</h4>
            <button onClick={() => setShowCreate(false)} className="rounded p-1 text-slate-400 hover:text-slate-600"><X className="h-4 w-4" /></button>
          </div>
          <input
            value={newGroupName}
            onChange={(e) => setNewGroupName(e.target.value)}
            placeholder="اسم القائمة"
            className="w-full rounded-lg border border-slate-200 px-3 py-2 text-sm dark:border-slate-700 dark:bg-slate-800"
          />
          {duplicateName && <p className="text-xs text-red-500">اسم القائمة مكرر</p>}
          <div className="max-h-48 overflow-y-auto space-y-1">
            <p className="text-xs font-bold text-slate-500">نقل صفحات من قوائم أخرى (اختياري):</p>
            {allPages.map(({ group, item }) => (
              <label key={item.to} className="flex items-center gap-2 text-xs">
                <input
                  type="checkbox"
                  checked={newGroupPages.includes(item.to)}
                  onChange={(e) => {
                    setNewGroupPages((prev) =>
                      e.target.checked ? [...prev, item.to] : prev.filter((p) => p !== item.to)
                    );
                  }}
                />
                {overrides.labels[item.to] ?? item.label} <span className="text-slate-400">({group.label})</span>
              </label>
            ))}
          </div>
          <button onClick={createGroup} disabled={readOnly || duplicateName || !newGroupName.trim()} className="rounded-xl bg-sky-600 px-4 py-2 text-xs font-bold text-white hover:bg-sky-700 disabled:opacity-40">
            إنشاء
          </button>
        </div>
      )}

      <div className="grid grid-cols-1 gap-3 lg:grid-cols-2">
        {groups.map((group, groupIndex) => (
          <div key={group.id} className={`rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 ${isGroupHidden(group.id) ? 'opacity-60' : ''}`}>
            <div className="flex items-center gap-2 border-b border-slate-200 dark:border-slate-700 px-4 py-3">
              <GripVertical className="h-4 w-4 text-slate-400" />
              <input
                value={overrides.labels[`group:${group.id}`] ?? group.label}
                onChange={(e) => update({ labels: { ...overrides.labels, [`group:${group.id}`]: e.target.value } })}
                disabled={readOnly}
                className="min-w-0 flex-1 rounded-lg bg-transparent px-1 py-0.5 text-sm font-extrabold text-slate-900 dark:text-slate-100 focus:bg-slate-50 dark:focus:bg-slate-800 focus:outline-none"
              />
              <button disabled={readOnly || groupIndex === 0} onClick={() => moveGroup(group.id, -1)} className="rounded p-1 text-slate-400 hover:text-sky-600 disabled:opacity-30" title="أعلى">
                <ArrowUp className="h-3.5 w-3.5" />
              </button>
              <button disabled={readOnly || groupIndex === groups.length - 1} onClick={() => moveGroup(group.id, 1)} className="rounded p-1 text-slate-400 hover:text-sky-600 disabled:opacity-30" title="أسفل">
                <ArrowDown className="h-3.5 w-3.5" />
              </button>
              <button disabled={readOnly} onClick={() => toggleGroupHidden(group.id)} className={`rounded-lg p-1.5 ${isGroupHidden(group.id) ? 'text-slate-400' : 'text-emerald-600'} hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-40`} title={isGroupHidden(group.id) ? 'إظهار القائمة' : 'إخفاء القائمة'}>
                {isGroupHidden(group.id) ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
              </button>
            </div>
            <div className="divide-y divide-slate-100 dark:divide-slate-800">
              {group.items.map((item, itemIndex) => {
                const hidden = isHidden(item.to);
                return (
                  <div key={item.to + item.label} className={`flex items-center gap-2 px-3 py-2 ${hidden ? 'opacity-50' : ''}`}>
                    <button
                      disabled={readOnly}
                      onClick={() => toggleHidden(item.to)}
                      className={`rounded-lg p-1.5 ${hidden ? 'text-slate-400' : 'text-emerald-600'} hover:bg-slate-100 dark:hover:bg-slate-800 disabled:opacity-40`}
                      title={hidden ? 'إظهار' : 'إخفاء'}
                    >
                      {hidden ? <EyeOff className="h-4 w-4" /> : <Eye className="h-4 w-4" />}
                    </button>
                    <div className="min-w-0 flex-1">
                      <input
                        value={overrides.labels[item.to] ?? item.label}
                        onChange={(e) => rename(item.to, e.target.value)}
                        disabled={readOnly}
                        className="w-full rounded-lg bg-transparent px-1 py-0.5 text-xs font-bold text-slate-800 dark:text-slate-200 focus:bg-slate-50 dark:focus:bg-slate-800 focus:outline-none"
                      />
                      <div className="px-1 font-mono text-[10px] text-slate-400">{item.to} · {item.perm || 'بدون صلاحية'}</div>
                    </div>
                    <select
                      value={group.id}
                      onChange={(event) => moveItemToGroup(group.id, item.to, event.target.value)}
                      disabled={readOnly}
                      aria-label={`نقل ${item.label} إلى قائمة أخرى`}
                      title="نقل الصفحة إلى قائمة أخرى"
                      className="max-w-28 rounded-lg border border-slate-200 bg-white px-1.5 py-1 text-[10px] font-bold text-slate-600 disabled:opacity-40 dark:border-slate-700 dark:bg-slate-800 dark:text-slate-300"
                    >
                      {groups.map((targetGroup) => (
                        <option key={targetGroup.id} value={targetGroup.id}>{targetGroup.label}</option>
                      ))}
                    </select>
                    <button disabled={readOnly || itemIndex === 0} onClick={() => moveItem(group.id, item.to, -1)} className="rounded p-1 text-slate-400 hover:text-sky-600 disabled:opacity-30">
                      <ArrowUp className="h-3.5 w-3.5" />
                    </button>
                    <button disabled={readOnly || itemIndex === group.items.length - 1} onClick={() => moveItem(group.id, item.to, 1)} className="rounded p-1 text-slate-400 hover:text-sky-600 disabled:opacity-30">
                      <ArrowDown className="h-3.5 w-3.5" />
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        ))}
      </div>

      {hiddenGroups.length > 0 && (
        <div className="rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4">
          <h4 className="mb-2 text-sm font-extrabold text-slate-900 dark:text-slate-100">القوائم المخفية</h4>
          <div className="space-y-2">
            {hiddenGroups.map((group) => (
              <div key={group.id} className="flex items-center gap-2 rounded-lg bg-slate-50 dark:bg-slate-800 px-3 py-2">
                <EyeOff className="h-4 w-4 text-slate-400" />
                <span className="flex-1 text-xs font-bold text-slate-700 dark:text-slate-200">{overrides.labels[`group:${group.id}`] ?? group.label}</span>
                <button disabled={readOnly} onClick={() => toggleGroupHidden(group.id)} className="rounded-lg p-1.5 text-emerald-600 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-40" title="إظهار">
                  <Eye className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {hiddenItems.length > 0 && (
        <div className="rounded-2xl border border-slate-200 dark:border-slate-700 bg-white dark:bg-slate-900 p-4">
          <h4 className="mb-2 text-sm font-extrabold text-slate-900 dark:text-slate-100">الصفحات المخفية</h4>
          <div className="space-y-2">
            {hiddenItems.map(({ group, item }) => (
              <div key={item.to} className="flex items-center gap-2 rounded-lg bg-slate-50 dark:bg-slate-800 px-3 py-2">
                <EyeOff className="h-4 w-4 text-slate-400" />
                <span className="flex-1 text-xs font-bold text-slate-700 dark:text-slate-200">{overrides.labels[item.to] ?? item.label}</span>
                <span className="font-mono text-[10px] text-slate-400">{item.to}</span>
                <button disabled={readOnly} onClick={() => toggleHidden(item.to)} className="rounded-lg p-1.5 text-emerald-600 hover:bg-slate-100 dark:hover:bg-slate-700 disabled:opacity-40" title="إظهار">
                  <Eye className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

import React from 'react';
import { AlertTriangle, Clock } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { useTheme } from '../../../contexts/useTheme';
import { type DebtCustomer, type RecentInvoice, type TopProduct, formatCurrency, paymentStatusLabel } from '../../../types/dashboard/executive';

interface Props {
  topProducts: TopProduct[];
  recentInvoices: RecentInvoice[];
  debtCustomers: DebtCustomer[];
}

export const ExecutiveBottomGrid: React.FC<Props> = ({
  topProducts,
  recentInvoices,
  debtCustomers,
}) => {
  const { isDark } = useTheme();
  const cardBg = isDark ? 'bg-slate-800' : 'bg-white';
  const cardBorder = isDark ? 'border-slate-700' : 'border-slate-200';
  const textPrimary = isDark ? 'text-white' : 'text-slate-900';
  const textSecondary = isDark ? 'text-slate-400' : 'text-slate-500';
  const textMuted = isDark ? 'text-slate-500' : 'text-slate-600';
  const borderColor = isDark ? 'border-slate-700' : 'border-slate-200';

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
