                    <td className="px-4 py-3 text-slate-700 font-mono">{fmt(adjustment.totalValue)}</td>
                    <td className="px-4 py-3">
                      <span className={`text-[10px] px-2 py-1 rounded-full font-bold ${adjustment.status === 'POSTED' ? 'bg-emerald-100 text-emerald-700' : adjustment.approvalStatus === 'APPROVED' ? 'bg-sky-100 text-sky-700' : 'bg-amber-100 text-amber-700'}`}>
                        {adjustment.status === 'POSTED' ? 'مرحّلة' : adjustment.approvalStatus === 'APPROVED' ? 'معتمدة - بانتظار الترحيل' : 'بانتظار الاعتماد'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-[10px] text-slate-600 leading-5">
                      <div>الإنشاء: {adjustment.adjustedBy}</div>
                      <div>الاعتماد: {adjustment.approvedByName || '—'}</div>
                      <div>الترحيل: {adjustment.postedByName || '—'}</div>
                    </td>
                    <td className="px-4 py-3 min-w-40">
                      <button
                        onClick={() => handleViewDetails(adjustment)}
                        className="flex items-center gap-1 text-xs text-sky-600 hover:text-sky-700 font-bold transition"
                      >
                        <FileText className="w-3.5 h-3.5" />
                        <span>عرض البنود</span>
                        <ChevronRight className="w-3 h-3" />
                      </button>
                      {canApprove && adjustment.status === 'PENDING_APPROVAL'
                        && adjustment.approvalStatus !== 'APPROVED'
                        && adjustment.createdBy !== actor?.id && (
                          <button
                            onClick={() => runWorkflowAction('approve', adjustment)}
                            className="mt-2 flex items-center gap-1 text-xs text-emerald-700 hover:text-emerald-800 font-bold"
                          >
                            <CheckCircle2 className="w-3.5 h-3.5" />
                            اعتماد
                          </button>
                      )}
                      {canPost && adjustment.status === 'PENDING_APPROVAL' && adjustment.approvalStatus === 'APPROVED' && (
                        <button
                          onClick={() => runWorkflowAction('post', adjustment)}
                          className="mt-2 flex items-center gap-1 text-xs text-orange-700 hover:text-orange-800 font-bold"
                        >
                          <CheckCircle2 className="w-3.5 h-3.5" />
                          ترحيل
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <AdjustmentModals
        showDetailModal={showDetailModal}
        setShowDetailModal={setShowDetailModal}
        selectedAdjustment={selectedAdjustment}
        selectedItems={selectedItems}
        fmt={fmt}
        showCreateModal={showCreateModal}
        setShowCreateModal={setShowCreateModal}
        errorMsg={errorMsg}
        warehouses={warehouses}
        selectedWarehouseId={selectedWarehouseId}
        setSelectedWarehouseId={setSelectedWarehouseId}
        adjType={adjType}
        setAdjType={setAdjType}
        products={products}
        selectedProductId={selectedProductId}
        setSelectedProductId={setSelectedProductId}
        selectedProduct={selectedProduct}
        selectedUnit={selectedUnit}
        qtyM2={qtyM2}
        setQtyM2={setQtyM2}
        reason={reason}
        setReason={setReason}
        notes={notes}
        setNotes={setNotes}
        handleCreateAdjustment={handleCreateAdjustment}
      />
    </div>
  );
};

import React from 'react';
import {
  Layers,
  Save,
  RotateCcw,
  Search,
  Building,
  CheckCircle2,
  Sliders,
  History,
  Eye,
  FileText,
  Tag,
  Shield,
  ArrowRight,
  Info,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformTenant,
  PlatformTenantActivityConfig,
  PlatformTenantActivityVersion,
} from '../../services/domains/platform/platformTypes';
import {
  BUSINESS_ACTIVITY_FAMILIES,
  getActivityRows,
  type ActivityDefinition,
} from '../../config/activityCatalog';
import {
  getBusinessProfile,
} from '../../config/businessProfiles';
import {
  MODULE_REGISTRY,
  type ModuleDefinition,
} from '../../config/moduleRegistry';
import { Button } from '../../components/ui/Button';
import { PageHeader } from '../../components/ui/PageHeader';
import { useToast } from '../../components/ui/Toast';
import { EmptyState, inputClass, formatDateTime } from './components/PlatformUI';

export const PlatformActivitySettingsPage: React.FC = () => {
  const toast = useToast();
  const canManageActivity = canPlatform('activity', 'platform.activity.update');
  const [tenants, setTenants] = React.useState<PlatformTenant[]>([]);
  const [selectedTenantId, setSelectedTenantId] = React.useState<string>('');
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);

  // Tenant Activity State
  const [activityConfig, setActivityConfig] = React.useState<PlatformTenantActivityConfig | null>(null);
  const [versions, setVersions] = React.useState<PlatformTenantActivityVersion[]>([]);
  const [activeTab, setActiveTab] = React.useState<'catalog' | 'modules' | 'terminology' | 'history'>('catalog');

  // Activity Catalog State
  const [catalogSearch, setCatalogSearch] = React.useState('');
  const [selectedFamilyId, setSelectedFamilyId] = React.useState<string>('all');
  const allActivities = React.useMemo(() => getActivityRows(), []);

  // Form State for editing
  const [selectedActivityId, setSelectedActivityId] = React.useState<string>('');
  const [enabledModules, setEnabledModules] = React.useState<string[]>([]);
  const [customTerminology, setCustomTerminology] = React.useState<Record<string, string>>({});
  const [changeSummary, setChangeSummary] = React.useState('');

  const loadTenants = React.useCallback(() => {
    try {
      const list = platformAdminService.listTenants();
      setTenants(list);
      if (list.length > 0 && !selectedTenantId) {
        setSelectedTenantId(list[0].id);
      }
    } catch (err) {
      toast.error('تعذر استرجاع قائمة العملاء');
    } finally {
      setLoading(false);
    }
  }, [selectedTenantId, toast]);

  React.useEffect(() => {
    loadTenants();
  }, [loadTenants]);

  // Load activity config when selected tenant changes
  const loadTenantActivity = React.useCallback((tenantId: string) => {
    if (!tenantId) return;
    try {
      const config = platformAdminService.getTenantActivity(tenantId);
      setActivityConfig(config);
      if (config) {
        setSelectedActivityId(config.activityId);
        setEnabledModules([...config.enabledModules]);
        setCustomTerminology({ ...config.customTerminology });
      }
      const vList = platformAdminService.listTenantActivityVersions(tenantId);
      setVersions(vList);
    } catch (err) {
      toast.error('تعذر استرجاع نشاط العميل');
    }
  }, [toast]);

  React.useEffect(() => {
    if (selectedTenantId) {
      loadTenantActivity(selectedTenantId);
    }
  }, [selectedTenantId, loadTenantActivity]);

  const handleApplyTemplate = (act: ActivityDefinition) => {
    const profile = getBusinessProfile(act.profileId || act.id);
    setSelectedActivityId(act.id);
    setEnabledModules([...profile.modules.enabledByDefault]);
    setChangeSummary(`تطبيق قالب النشاط: ${act.label}`);
    toast.info(`تم تحميل قالب [${act.label}]. اضغط "حفظ النشاط" لتطبيقه على هذا العميل.`);
  };

  const handleSaveActivity = () => {
    if (!canManageActivity) { toast.error('لا تملك صلاحية إدارة الأنشطة'); return; }
    if (!selectedTenantId || !selectedActivityId) return;
    setSaving(true);
    try {
      const act = allActivities.find((a) => a.id === selectedActivityId);
      const updated = platformAdminService.saveTenantActivity({
        tenantId: selectedTenantId,
        activityId: selectedActivityId,
        profileId: act?.profileId || selectedActivityId,
        enabledModules,
        customTerminology,
        changeSummary: changeSummary.trim() || undefined,
      });
      setActivityConfig(updated);
      setChangeSummary('');
      toast.success(`تم حفظ وتحديث إعدادات النشاط بنجاح (إصدار #${updated.version})`);
      loadTenantActivity(selectedTenantId);
    } catch (err) {
      toast.error('تعذر حفظ النشاط', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const handleRollback = (ver: number) => {
    if (!canManageActivity) { toast.error('لا تملك صلاحية إدارة الأنشطة'); return; }
    if (!window.confirm(`هل أنت متأكد من استرجاع إعدادات النشاط إلى الإصدار #${ver}؟`)) {
      return;
    }
    setSaving(true);
    try {
      const restored = platformAdminService.rollbackTenantActivity(selectedTenantId, ver);
      setActivityConfig(restored);
      toast.success(`تم استرجاع إعدادات النشاط بنجاح إلى النسخة #${ver}`);
      loadTenantActivity(selectedTenantId);
    } catch (err) {
      toast.error('فشل الاسترجاع', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const toggleModule = (modId: string) => {
    if (enabledModules.includes(modId)) {
      setEnabledModules(enabledModules.filter((m) => m !== modId));
    } else {
      setEnabledModules([...enabledModules, modId]);
    }
  };

  const filteredActivities = React.useMemo(() => {
    return allActivities.filter((act) => {
      const matchSearch =
        !catalogSearch.trim() ||
        act.label.toLowerCase().includes(catalogSearch.toLowerCase()) ||
        act.id.toLowerCase().includes(catalogSearch.toLowerCase());
      const matchFamily = selectedFamilyId === 'all' || act.familyId === selectedFamilyId;
      return matchSearch && matchFamily;
    });
  }, [allActivities, catalogSearch, selectedFamilyId]);

  const selectedTenant = tenants.find((t) => t.id === selectedTenantId);
  const currentProfile = selectedActivityId ? getBusinessProfile(selectedActivityId) : null;

  return (
    <div className="space-y-5">
      <PageHeader
        title="إدارة الأنشطة والقوالب التجارية للعملاء"
        description="تخصيص نشاط كل عميل بمعزل تام: قوالب الأنشطة، الوحدات، المصطلحات، وسجل استرجاع الإصدارات السابقة."
        icon={<Layers className="h-5 w-5 text-indigo-600" />}
        actions={
          <div className="flex items-center gap-2">
            <Button
              variant="primary"
              size="sm"
              leadingIcon={<Save className="h-3.5 w-3.5" />}
              onClick={handleSaveActivity}
              disabled={saving || !selectedTenantId || !canManageActivity}
            >
              {saving ? 'جارٍ الحفظ...' : 'حفظ نشاط العميل'}
            </Button>
          </div>
        }
      />

      {/* Tenant Selection Bar */}
      <div className="flex flex-wrap items-center justify-between gap-4 rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
        <div className="flex items-center gap-3">
          <Building className="h-5 w-5 text-slate-400" />
          <div>
            <label className="text-xs font-bold text-slate-700 block">حدد العميل المستهدف:</label>
            <select
              value={selectedTenantId}
              onChange={(e) => setSelectedTenantId(e.target.value)}
              className={`${inputClass} !py-1 text-xs min-w-[260px] font-semibold text-slate-800`}
            >
              {tenants.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name} ({t.code}) — {t.businessType || 'عام'}
                </option>
              ))}
            </select>
          </div>
        </div>

        {activityConfig && selectedTenant && (
          <div className="flex items-center gap-4 text-xs bg-slate-50 border border-slate-200 rounded-lg px-4 py-2">
            <div>
              النشاط الحالي:{' '}
              <strong className="text-indigo-700">
                {allActivities.find((a) => a.id === activityConfig.activityId)?.label || activityConfig.activityId}
              </strong>
            </div>
            <div>
              الإصدار المطبق: <strong className="text-slate-800">#{activityConfig.version}</strong>
            </div>
            <div>
              الوحدات النشطة: <strong className="text-emerald-700">{activityConfig.enabledModules.length}</strong>
            </div>
          </div>
        )}
      </div>

      {/* Tabs */}
      <div className="flex overflow-x-auto border-b border-slate-200 bg-white px-2 pt-2 rounded-t-xl gap-1">
        <button
          onClick={() => setActiveTab('catalog')}
          className={`flex items-center gap-2 border-b-2 px-4 py-3 text-xs font-semibold whitespace-nowrap transition-colors ${
            activeTab === 'catalog'
              ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
              : 'border-transparent text-slate-600 hover:text-slate-900'
          }`}
        >
          <Layers className="h-4 w-4" /> كتالوج وقوالب الأنشطة الجاهزة
        </button>
        <button
          onClick={() => setActiveTab('modules')}
          className={`flex items-center gap-2 border-b-2 px-4 py-3 text-xs font-semibold whitespace-nowrap transition-colors ${
            activeTab === 'modules'
              ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
              : 'border-transparent text-slate-600 hover:text-slate-900'
          }`}
        >
          <Sliders className="h-4 w-4" /> الوحدات المطلوبة ({enabledModules.length})
        </button>
        <button
          onClick={() => setActiveTab('terminology')}
          className={`flex items-center gap-2 border-b-2 px-4 py-3 text-xs font-semibold whitespace-nowrap transition-colors ${
            activeTab === 'terminology'
              ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
              : 'border-transparent text-slate-600 hover:text-slate-900'
          }`}
        >
          <Tag className="h-4 w-4" /> المصطلحات والشاشات
        </button>
        <button
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 border-b-2 px-4 py-3 text-xs font-semibold whitespace-nowrap transition-colors ${
            activeTab === 'history'
              ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
              : 'border-transparent text-slate-600 hover:text-slate-900'
          }`}
        >
          <History className="h-4 w-4" /> سجل الإصدارات والاسترجاع ({versions.length})
        </button>
      </div>

      {/* Main Tab Content Card */}
      <div className="rounded-b-xl rounded-tr-xl border border-slate-200 bg-white p-6 shadow-sm">
        {/* 1. Catalog Tab */}
        {activeTab === 'catalog' && (
          <div className="space-y-4">
            <div className="flex flex-wrap items-center gap-3">
              <div className="relative min-w-[260px] flex-1">
                <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <input
                  value={catalogSearch}
                  onChange={(e) => setCatalogSearch(e.target.value)}
                  placeholder="ابحث في أكثر من 80 نشاطاً تجارياً..."
                  className={`${inputClass} pr-9`}
                />
              </div>

              <select
                value={selectedFamilyId}
                onChange={(e) => setSelectedFamilyId(e.target.value)}
                className={`${inputClass} max-w-[220px]`}
              >
                <option value="all">كل القطاعات التجارية</option>
                {BUSINESS_ACTIVITY_FAMILIES.map((f) => (
                  <option key={f.id} value={f.id}>
                    {f.label}
                  </option>
                ))}
              </select>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 pt-2">
              {filteredActivities.map((act) => {
                const isCurrent = selectedActivityId === act.id;
                const profile = getBusinessProfile(act.profileId || act.id);
                return (
                  <div
                    key={act.id}
                    className={`rounded-xl border p-4 transition-all flex flex-col justify-between ${
                      isCurrent
                        ? 'border-indigo-600 bg-indigo-50/40 ring-1 ring-indigo-600 shadow-sm'
                        : 'border-slate-200 bg-white hover:border-slate-300'
                    }`}
                  >
                    <div>
                      <div className="flex items-start justify-between gap-2">
                        <h4 className="text-xs font-bold text-slate-900">{act.label}</h4>
                        {isCurrent && (
                          <span className="shrink-0 inline-flex items-center gap-1 rounded-full bg-indigo-600 text-white text-[9.5px] px-2 py-0.5 font-bold">
                            <CheckCircle2 className="h-3 w-3" /> النشاط المحدد
                          </span>
                        )}
                      </div>
                      <p className="text-[11px] text-slate-500 mt-1 line-clamp-2">
                        {profile.description.ar}
                      </p>
                      <div className="mt-3 flex flex-wrap gap-1">
                        {profile.modules.enabledByDefault.slice(0, 4).map((mod) => (
                          <span key={mod} className="rounded bg-slate-100 text-slate-600 px-1.5 py-0.5 text-[9.5px]">
                            {mod}
                          </span>
                        ))}
                        {profile.modules.enabledByDefault.length > 4 && (
                          <span className="text-[9.5px] text-slate-400">
                            +{profile.modules.enabledByDefault.length - 4} وحدات
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="pt-4 mt-3 border-t border-slate-100 flex items-center justify-between">
                      <span className="text-[10px] font-mono text-slate-400">{act.id}</span>
                      <Button
                        variant={isCurrent ? 'secondary' : 'ghost'}
                        size="sm"
                        onClick={() => handleApplyTemplate(act)}
                        className="text-xs"
                      >
                        {isCurrent ? 'إعادة تعيين القالب' : 'تطبيق القالب'}
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* 2. Modules Tab */}
        {activeTab === 'modules' && (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h3 className="text-sm font-bold text-slate-900">الوحدات المفعلة لنشاط هذا العميل</h3>
                <p className="text-xs text-slate-500">
                  تحديد الوحدات المتاحة لهذا العميل دون التأثير على أي عميل آخر على المنصة.
                </p>
              </div>
              <span className="text-xs font-semibold text-slate-600 bg-slate-100 px-3 py-1 rounded-full">
                {enabledModules.length} وحدة مفعلة
              </span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3 pt-2">
              {MODULE_REGISTRY.map((mod: ModuleDefinition) => {
                const isEnabled = enabledModules.includes(mod.id);
                return (
                  <label
                    key={mod.id}
                    className={`flex items-start gap-3 p-3 rounded-xl border cursor-pointer transition-colors ${
                      isEnabled ? 'border-indigo-300 bg-indigo-50/30' : 'border-slate-200 bg-white hover:bg-slate-50'
                    }`}
                  >
                    <input
                      type="checkbox"
                      checked={isEnabled}
                      onChange={() => toggleModule(mod.id)}
                      disabled={!canManageActivity}
                      className="mt-1 h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                    />
                    <div className="min-w-0 flex-1">
                      <div className="flex items-center justify-between">
                        <span className="text-xs font-bold text-slate-900">{mod.label}</span>
                        <span className="text-[9.5px] font-mono text-slate-400">{mod.id}</span>
                      </div>
                      <p className="text-[11px] text-slate-500 mt-0.5 line-clamp-1">{mod.description}</p>
                    </div>
                  </label>
                );
              })}
            </div>
          </div>
        )}

        {/* 3. Terminology Tab */}
        {activeTab === 'terminology' && (
          <div className="space-y-4">
            <div>
              <h3 className="text-sm font-bold text-slate-900">تخصيص المصطلحات والشاشات القطاعية</h3>
              <p className="text-xs text-slate-500">
                مواءمة مسميات النظام لتناسب طبيعة نشاط العميل (مثال: "صنف" مقابل "طبق" أو "خدمة" أو "عقار").
              </p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-w-2xl pt-2">
              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">مسمى المنتج / الصنف الأساسي</label>
                <input
                  type="text"
                  value={customTerminology['product_name'] || ''}
                  onChange={(e) => setCustomTerminology({ ...customTerminology, product_name: e.target.value })}
                  className={inputClass}
                  placeholder="مثال: بلاطة، صنف، وجبة، قطعة، خدمة"
                />
              </div>

              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">مسمى الطرف المقابل (العميل)</label>
                <input
                  type="text"
                  value={customTerminology['customer_name'] || ''}
                  onChange={(e) => setCustomTerminology({ ...customTerminology, customer_name: e.target.value })}
                  className={inputClass}
                  placeholder="مثال: عميل، زبون، ضيف، مريض، موكل"
                />
              </div>

              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">مسمى المخزن / المستودع</label>
                <input
                  type="text"
                  value={customTerminology['warehouse_name'] || ''}
                  onChange={(e) => setCustomTerminology({ ...customTerminology, warehouse_name: e.target.value })}
                  className={inputClass}
                  placeholder="مثال: معرض، مستودع، فرع، صالة، مخزن"
                />
              </div>

              <div>
                <label className="text-xs font-bold text-slate-700 block mb-1">مسمى الفاتورة / أمر البيع</label>
                <input
                  type="text"
                  value={customTerminology['invoice_name'] || ''}
                  onChange={(e) => setCustomTerminology({ ...customTerminology, invoice_name: e.target.value })}
                  className={inputClass}
                  placeholder="مثال: فاتورة ضريبية، شيك طاولة، إيصال، تذكرة"
                />
              </div>
            </div>
          </div>
        )}

        {/* 4. History & Rollback Tab */}
        {activeTab === 'history' && (
          <div className="space-y-4">
            <div>
              <h3 className="text-sm font-bold text-slate-900">سجل إصدارات النشاط والاسترجاع (Snapshots)</h3>
              <p className="text-xs text-slate-500">
                يتم حفظ نسخة تلقائية مع كل تعديل على نشاط العميل مع إمكانية استرجاع أي إصدار سابق فوراً.
              </p>
            </div>

            {versions.length === 0 ? (
              <EmptyState
                icon={<History className="h-5 w-5 text-slate-400" />}
                title="لا توجد إصدارات سابقة"
                description="سيتم إنشاء لقطات تاريخية عند إجراء أول عملية حفظ لنشاط العميل."
              />
            ) : (
              <div className="overflow-x-auto rounded-xl border border-slate-200">
                <table className="w-full text-right text-xs">
                  <thead className="bg-slate-50 text-slate-600 font-semibold border-b border-slate-200">
                    <tr>
                      <th className="py-3 px-4">رقم الإصدار</th>
                      <th className="py-3 px-4">النشاط التجاري</th>
                      <th className="py-3 px-4">سبب التحديث</th>
                      <th className="py-3 px-4">المنفذ</th>
                      <th className="py-3 px-4">تاريخ الإصدار</th>
                      <th className="py-3 px-4 text-center">الإجراء</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100">
                    {versions.map((ver) => (
                      <tr key={ver.id} className="hover:bg-slate-50/70">
                        <td className="py-3 px-4 font-bold text-indigo-700">#{ver.version}</td>
                        <td className="py-3 px-4 font-semibold text-slate-800">
                          {allActivities.find((a) => a.id === ver.activityId)?.label || ver.activityId}
                        </td>
                        <td className="py-3 px-4 text-slate-600">{ver.changeSummary || '—'}</td>
                        <td className="py-3 px-4 text-slate-600">{ver.createdBy || 'النظام'}</td>
                        <td className="py-3 px-4 text-slate-400 font-mono" dir="ltr">
                          {formatDateTime(ver.createdAt)}
                        </td>
                        <td className="py-3 px-4 text-center">
                          {canManageActivity && (
                            <Button
                              variant="secondary"
                              size="sm"
                              leadingIcon={<RotateCcw className="h-3 w-3 text-amber-600" />}
                              onClick={() => handleRollback(ver.version)}
                              className="text-xs"
                            >
                              استرجاع
                            </Button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default PlatformActivitySettingsPage;

﻿import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  ShieldCheck,
  Users,
  Building2,
  UserPlus,
  Shield,
  Key,
  Lock,
  Unlock,
  Trash2,
  Pencil,
  Search,
  Filter,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  UserCheck,
  RefreshCw,
  Plus,
  Layers,
  ChevronRight,
  Sliders,
  BadgeCheck,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformStaff,
  PlatformStaffInput,
  PlatformStaffRole,
  PlatformStaffRoleDefinition,
  PlatformTenant,
  PlatformTenantUser,
  PlatformTenantUserInput,
} from '../../services/domains/platform/platformTypes';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import {
  EmptyState,
  StatusBadge,
  formatDateTime,
  inputClass,
} from './components/PlatformUI';

type ActiveTab = 'STAFF' | 'TENANTS';

const ROLE_BADGE_STYLE: Record<PlatformStaffRole, { bg: string; text: string; label: string }> = {
  SUPER_ADMIN: { bg: 'bg-purple-500/20 border-purple-500/40', text: 'text-purple-300', label: 'مالك المنصة' },
  PLATFORM_ADMIN: { bg: 'bg-indigo-500/20 border-indigo-500/40', text: 'text-indigo-300', label: 'مدير منصة عام' },
  SUPPORT_AGENT: { bg: 'bg-emerald-500/20 border-emerald-500/40', text: 'text-emerald-300', label: 'دعم فني' },
  OPERATIONS_ENGINEER: { bg: 'bg-sky-500/20 border-sky-500/40', text: 'text-sky-300', label: 'عمليات وبنية تحتية' },
  BILLING_SPECIALIST: { bg: 'bg-amber-500/20 border-amber-500/40', text: 'text-amber-300', label: 'فواتير واشتراكات' },
  LICENSE_MANAGER: { bg: 'bg-pink-500/20 border-pink-500/40', text: 'text-pink-300', label: 'إدارة التراخيص' },
};

export const PlatformAdminControlPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ActiveTab>('STAFF');

  // Staff State
  const [staffList, setStaffList] = useState<PlatformStaff[]>([]);
  const [staffRoles, setStaffRoles] = useState<PlatformStaffRoleDefinition[]>([]);
  const [staffSearch, setStaffSearch] = useState('');
  const [staffRoleFilter, setStaffRoleFilter] = useState('');
  const [staffLoading, setStaffLoading] = useState(true);

  // Tenant Users State
  const [tenants, setTenants] = useState<PlatformTenant[]>([]);
  const [selectedTenantId, setSelectedTenantId] = useState<string>('');
  const [tenantUsers, setTenantUsers] = useState<PlatformTenantUser[]>([]);
  const [tenantUsersLoading, setTenantUsersLoading] = useState(false);
  const [tenantSearch, setTenantSearch] = useState('');

  // Modals & Forms
  const [isStaffModalOpen, setIsStaffModalOpen] = useState(false);
  const [editingStaff, setEditingStaff] = useState<PlatformStaff | null>(null);
  const [staffForm, setStaffForm] = useState<PlatformStaffInput>({
    fullName: '',
    email: '',
    phone: '',
    role: 'SUPPORT_AGENT',
    password: '',
    isActive: true,
  });

  const [isTenantUserModalOpen, setIsTenantUserModalOpen] = useState(false);
  const [editingTenantUser, setEditingTenantUser] = useState<PlatformTenantUser | null>(null);
  const [tenantUserForm, setTenantUserForm] = useState<PlatformTenantUserInput>({
    fullName: '',
    username: '',
    email: '',
    phone: '',
    role: 'ADMIN',
    status: 'ACTIVE',
  });

  const [error, setError] = useState<string | null>(null);

  // Load staff
  const loadStaff = useCallback(() => {
    setStaffLoading(true);
    try {
      setStaffList(platformAdminService.listPlatformStaff(staffSearch, staffRoleFilter));
      setStaffRoles(platformAdminService.listPlatformStaffRoles());
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل موظفي المنصة.');
    } finally {
      setStaffLoading(false);
    }
  }, [staffSearch, staffRoleFilter]);

  // Load tenants
  const loadTenants = useCallback(() => {
    try {
      const list = platformAdminService.listTenants();
      setTenants(list);
      if (list.length > 0 && !selectedTenantId) {
        setSelectedTenantId(list[0].id);
      }
    } catch (err) {
      console.error(err);
    }
  }, [selectedTenantId]);

  // Load tenant users
  const loadTenantUsers = useCallback((tenantId: string) => {
    if (!tenantId) return;
    setTenantUsersLoading(true);
    try {
      setTenantUsers(platformAdminService.listTenantUsers(tenantId));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل مستخدمي العميل.');
    } finally {
      setTenantUsersLoading(false);
    }
  }, []);

  useEffect(() => {
    loadStaff();
    loadTenants();
  }, [loadStaff, loadTenants]);

  useEffect(() => {
    if (selectedTenantId) {
      loadTenantUsers(selectedTenantId);
    }
  }, [selectedTenantId, loadTenantUsers]);

  // Open Staff Modal
  const openStaffModal = (staff?: PlatformStaff) => {
    if (staff) {
      setEditingStaff(staff);
      setStaffForm({
        fullName: staff.fullName,
        email: staff.email,
        phone: staff.phone || '',
        role: staff.role,
        password: '',
        isActive: staff.isActive,
      });
    } else {
      setEditingStaff(null);
      setStaffForm({
        fullName: '',
        email: '',
        phone: '',
        role: 'SUPPORT_AGENT',
        password: '',
        isActive: true,
      });
    }
    setIsStaffModalOpen(true);
  };

  const canManageStaff = canPlatform('staff');
  const canDeleteStaff = canPlatform('staff', 'staff.delete_owner');
  const canManageTenantUsers = canPlatform('admin-control');

  // Save Staff
  const handleSaveStaff = () => {
    if (!canManageStaff) {
      alert('لا تملك صلاحية إدارة موظفي المنصة.');
      return;
    }
    if (!editingStaff && (!staffForm.password || staffForm.password.length < 8)) {
      alert('كلمة مرور موظف المنصة مطلوبة ويجب أن تكون 8 أحرف على الأقل.');
      return;
    }
    if (editingStaff && staffForm.password && staffForm.password.length > 0 && staffForm.password.length < 8) {
      alert('كلمة المرور الجديدة يجب أن تكون 8 أحرف على الأقل.');
      return;
    }
    try {
      const payload = { ...staffForm };
      if (editingStaff && !payload.password) {
        delete payload.password;
      }
      if (editingStaff) {
        platformAdminService.updatePlatformStaff(editingStaff.id, payload);
      } else {
        platformAdminService.createPlatformStaff(payload);
      }
      setIsStaffModalOpen(false);
      loadStaff();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشلت العملية.');
    }
  };

  // Toggle Staff Active
  const handleToggleStaffActive = (staff: PlatformStaff) => {
    if (!canManageStaff) {
      alert('لا تملك صلاحية إدارة موظفي المنصة.');
      return;
    }
    try {
      platformAdminService.setPlatformStaffActive(staff.id, !staff.isActive);
      loadStaff();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تغيير حالة الموظف.');
    }
  };

  // Delete Staff
  const handleDeleteStaff = (staff: PlatformStaff) => {
    if (!canDeleteStaff) {
      alert('لا تملك صلاحية حذف موظفي المنصة.');
      return;
    }
    if (!confirm(`هل أنت متأكد من حذف موظف المنصة (${staff.fullName})؟`)) return;
    try {
      platformAdminService.deletePlatformStaff(staff.id);
      loadStaff();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر حذف الموظف.');
    }
  };

  // Open Tenant User Modal
  const openTenantUserModal = (user?: PlatformTenantUser) => {
    if (user) {
      setEditingTenantUser(user);
      setTenantUserForm({
        fullName: user.fullName,
        username: user.username || '',
        email: user.email || '',
        phone: user.phone || '',
        role: user.role,
        status: user.status,
      });
    } else {
      setEditingTenantUser(null);
      setTenantUserForm({
        fullName: '',
        username: '',
        email: '',
        phone: '',
        role: 'ADMIN',
        status: 'ACTIVE',
      });
    }
    setIsTenantUserModalOpen(true);
  };

  // Save Tenant User
  const handleSaveTenantUser = () => {
    if (!selectedTenantId) return;
    if (!canManageTenantUsers) {
      alert('لا تملك صلاحية إدارة مستخدمي العملاء.');
      return;
    }
    try {
      if (editingTenantUser) {
        platformAdminService.updateTenantUser(editingTenantUser.id, tenantUserForm);
      } else {
        const result = platformAdminService.createTenantUser(selectedTenantId, {
          ...tenantUserForm,
          provisionIdentity: true,
          provisioningMode: 'INVITE',
        });
        const parts = [result.message];
        if (result.inviteCode) parts.push(`كود الدعوة: ${result.inviteCode}`);
        if (result.temporaryPassword) parts.push(`كلمة المرور المؤقتة: ${result.temporaryPassword}`);
        if (result.user.identityUserId) parts.push(`معرّف الهوية: ${result.user.identityUserId}`);
        alert(parts.join('\n'));
      }
      setIsTenantUserModalOpen(false);
      loadTenantUsers(selectedTenantId);
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشلت العملية.');
    }
  };

  // Toggle Tenant User Active
  const handleToggleTenantUserActive = (user: PlatformTenantUser) => {
    if (!canManageTenantUsers) {
      alert('لا تملك صلاحية إدارة مستخدمي العملاء.');
      return;
    }
    try {
      platformAdminService.setTenantUserActive(user.id, user.status !== 'ACTIVE');
      if (selectedTenantId) loadTenantUsers(selectedTenantId);
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تغيير حالة المستخدم.');
    }
  };

  // Delete Tenant User
  const handleDeleteTenantUser = (user: PlatformTenantUser) => {
    if (!canManageTenantUsers) {
      alert('لا تملك صلاحية إدارة مستخدمي العملاء.');
      return;
    }
    if (!confirm(`هل أنت متأكد من حذف مستخدم العميل (${user.fullName})؟`)) return;
    try {
      platformAdminService.deleteTenantUser(user.id);
      if (selectedTenantId) loadTenantUsers(selectedTenantId);
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر حذف المستخدم.');
    }
  };

  return (
    <div className="space-y-5">
      {/* Page Header */}
      <PageHeader
        title="مركز التحكم الإداري (RBAC & Staff Console)"
        description="فصل كامل بين إدارة موظفي الشركة المالكة للمنصة (Platform Staff) وإدارة مستخدمي الشركات العميلة (Tenant Users)."
        icon={<ShieldCheck className="h-6 w-6 text-emerald-400" />}
      />

      {error && (
        <div role="alert" className="rounded-xl border border-rose-800 bg-rose-950/40 p-4 text-rose-200">
          <div className="flex items-center gap-2">
            <AlertTriangle className="h-5 w-5 text-rose-400" />
            <span className="font-bold">{error}</span>
          </div>
        </div>
      )}

      {/* Main Mode Tabs Switcher */}
      <div className="flex border-b border-slate-800 pb-0">
        <button
          onClick={() => setActiveTab('STAFF')}
          className={`flex items-center gap-2 px-6 py-3 text-sm font-bold border-b-2 transition-all ${
            activeTab === 'STAFF'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Shield className="h-4 w-4" />
          <span>إدارة موظفي المنصة (Platform Staff Management)</span>
        </button>

        <button
          onClick={() => setActiveTab('TENANTS')}
          className={`flex items-center gap-2 px-6 py-3 text-sm font-bold border-b-2 transition-all ${
            activeTab === 'TENANTS'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Building2 className="h-4 w-4" />
          <span>إدارة مستخدمي الشركات العميلة (Tenant Admin & Users)</span>
        </button>
      </div>

      {/* TAB 1: PLATFORM STAFF MANAGEMENT */}
      {activeTab === 'STAFF' && (
        <div className="space-y-5">
          {/* Top Bar: Search, Role Filter, Add Staff Button */}
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-800 bg-slate-900/80 p-3.5 shadow-sm">
            <div className="flex flex-wrap items-center gap-2.5 flex-1 min-w-[280px]">
              <div className="relative min-w-[220px]">
                <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
                <input
                  type="text"
                  value={staffSearch}
                  onChange={(e) => setStaffSearch(e.target.value)}
                  placeholder="ابحث بالاسم أو البريد أو الهاتف..."
                  className={`${inputClass} pr-9 text-xs`}
                />
              </div>

              <select
                value={staffRoleFilter}
                onChange={(e) => setStaffRoleFilter(e.target.value)}
                className={`${inputClass} text-xs max-w-[190px]`}
              >
                <option value="">جميع الأدوار الوظيفية</option>
                <option value="SUPER_ADMIN">مالك المنصة (Super Admin)</option>
                <option value="PLATFORM_ADMIN">مدير منصة (Platform Admin)</option>
                <option value="SUPPORT_AGENT">دعم فني (Support Specialist)</option>
                <option value="OPERATIONS_ENGINEER">مهندس عمليات (Operations)</option>
                <option value="BILLING_SPECIALIST">أخصائي فواتير (Billing)</option>
                <option value="LICENSE_MANAGER">إدارة التراخيص (Licensing)</option>
              </select>
            </div>

            {canManageStaff && (
              <Button
                size="sm"
                onClick={() => openStaffModal()}
                leadingIcon={<UserPlus className="h-4 w-4" />}
              >
                إضافة موظف منصة جديد
              </Button>
            )}
          </div>

          {/* Platform Staff Table */}
          <section className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
            {staffLoading ? (
              <div className="py-16 text-center text-sm font-semibold text-slate-500">
                <RefreshCw className="inline-block h-5 w-5 animate-spin mb-2" />
                <p>جارٍ تحميل موظفي المنصة...</p>
              </div>
            ) : staffList.length === 0 ? (
              <EmptyState
                icon={<Users className="h-6 w-6 text-slate-500" />}
                title="لا يوجد موظفون مسجلون"
                description="قم بإضافة موظفين للمنصة وتعيين أدوارهم وصلاحياتهم."
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[850px] text-right">
                  <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                    <tr>
                      <th className="px-4 py-3">الموظف والبريد الإلكتروني</th>
                      <th className="px-4 py-3">الدور الوظيفي بالمنصة</th>
                      <th className="px-4 py-3">الصلاحيات المتاحة والمقيدة</th>
                      <th className="px-4 py-3">الحالة</th>
                      <th className="px-4 py-3">تاريخ الإضافة</th>
                      <th className="px-4 py-3 text-center">الإجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/80">
                    {staffList.map((staff) => {
                      const badge = ROLE_BADGE_STYLE[staff.role] || {
                        bg: 'bg-slate-800',
                        text: 'text-slate-300',
                        label: staff.role,
                      };
                      const isOwner = staff.role === 'SUPER_ADMIN';

                      return (
                        <tr key={staff.id} className="hover:bg-slate-800/30 transition-colors">
                          <td className="px-4 py-3.5">
                            <div className="flex items-center gap-2.5">
                              <div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-800 text-slate-300 font-bold text-xs">
                                {staff.fullName.charAt(0)}
                              </div>
                              <div>
                                <p className="text-xs font-bold text-slate-100 flex items-center gap-1.5">
                                  {staff.fullName}
                                  {isOwner && (
                                    <span title="مالك المنصة" className="inline-flex items-center"><BadgeCheck className="h-3.5 w-3.5 text-purple-400" /></span>
                                  )}
                                </p>
                                <p className="text-[11px] text-slate-400">{staff.email}</p>
                              </div>
                            </div>
                          </td>

                          <td className="px-4 py-3.5">
                            <span
                              className={`inline-flex items-center rounded-md border px-2.5 py-1 text-[11px] font-bold ${badge.bg} ${badge.text}`}
                            >
                              {badge.label}
                            </span>
                          </td>

                          <td className="px-4 py-3.5 text-xs text-slate-400">
                            {isOwner ? (
                              <span className="text-purple-300 font-semibold">وصول كامل لكافة الأنظمة (*)</span>
                            ) : staff.role === 'SUPPORT_AGENT' ? (
                              <span>تذاكر الدعم · جلسات Remote · التشخيص (مقيد الفواتير والأسعار)</span>
                            ) : staff.role === 'OPERATIONS_ENGINEER' ? (
                              <span>العمليات · النسخ الاحتياطي · المزامنة (مقيد الفواتير والتراخيص)</span>
                            ) : staff.role === 'BILLING_SPECIALIST' ? (
                              <span>الفوترة والمدفوعات · الاشتراكات (مقيد البنية والتراخيص)</span>
                            ) : staff.role === 'LICENSE_MANAGER' ? (
                              <span>إصدار التراخيص · الأجهزة والربط (مقيد الفواتير والعمليات)</span>
                            ) : (
                              <span>إدارة منصة عامة</span>
                            )}
                          </td>

                          <td className="px-4 py-3.5">
                            <span
                              className={`inline-flex items-center gap-1 text-[11px] font-bold ${
                                staff.isActive ? 'text-emerald-400' : 'text-rose-400'
                              }`}
                            >
                              {staff.isActive ? (
                                <CheckCircle2 className="h-3.5 w-3.5" />
                              ) : (
                                <XCircle className="h-3.5 w-3.5" />
                              )}
                              {staff.isActive ? 'نشط' : 'معطل'}
                            </span>
                          </td>

                          <td className="px-4 py-3.5 text-xs text-slate-400">
                            {formatDateTime(staff.createdAt)}
                          </td>

                          <td className="px-4 py-3.5">
                            <div className="flex items-center justify-center gap-1.5">
                              {canManageStaff && (
                                <button
                                  onClick={() => openStaffModal(staff)}
                                  title="تعديل الموظف"
                                  className="rounded p-1 text-slate-400 hover:bg-slate-800 hover:text-slate-200 transition-colors"
                                >
                                  <Pencil className="h-3.5 w-3.5" />
                                </button>
                              )}

                              {!isOwner && canManageStaff && (
                                <>
                                  <button
                                    onClick={() => handleToggleStaffActive(staff)}
                                    title={staff.isActive ? 'تعطيل الحساب' : 'تنشيط الحساب'}
                                    className={`rounded p-1 transition-colors ${
                                      staff.isActive
                                        ? 'text-amber-400 hover:bg-amber-950/40'
                                        : 'text-emerald-400 hover:bg-emerald-950/40'
                                    }`}
                                  >
                                    {staff.isActive ? (
                                      <Lock className="h-3.5 w-3.5" />
                                    ) : (
                                      <Unlock className="h-3.5 w-3.5" />
                                    )}
                                  </button>

                                  {canDeleteStaff && (
                                    <button
                                      onClick={() => handleDeleteStaff(staff)}
                                      title="حذف الموظف"
                                      className="rounded p-1 text-rose-400 hover:bg-rose-950/40 transition-colors"
                                    >
                                      <Trash2 className="h-3.5 w-3.5" />
                                    </button>
                                  )}
                                </>
                              )}
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </section>

          {/* Staff Roles & Permissions Matrix Overview */}
          <section className="rounded-xl border border-slate-800 bg-slate-900/60 p-4 shadow-sm">
            <h3 className="text-xs font-bold text-slate-200 mb-3 flex items-center gap-2">
              <Shield className="h-4 w-4 text-emerald-400" />
              مصفوفة الأدوار الوظيفية وعزل الصلاحيات في المنصة (Platform RBAC Rules)
            </h3>
            <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
              {staffRoles.map((roleDef) => (
                <div key={roleDef.role} className="rounded-lg border border-slate-800 bg-slate-950/50 p-3">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-xs font-bold text-slate-200">{roleDef.title}</span>
                    <span className="text-[10px] text-slate-500 font-mono">{roleDef.role}</span>
                  </div>
                  <p className="text-[11px] text-slate-400 leading-relaxed">{roleDef.description}</p>
                </div>
              ))}
            </div>
          </section>
        </div>
      )}

      {/* TAB 2: TENANT ADMIN MANAGEMENT */}
      {activeTab === 'TENANTS' && (
        <div className="space-y-5">
          {/* Tenant Selector & Actions Bar */}
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-800 bg-slate-900/80 p-3.5 shadow-sm">
            <div className="flex items-center gap-3 flex-1 min-w-[280px]">
              <Building2 className="h-5 w-5 text-emerald-400 shrink-0" />
              <div className="flex-1 max-w-md">
                <label className="block text-[11px] font-bold text-slate-400 mb-1">اختر الشركة العميلة:</label>
                <select
                  value={selectedTenantId}
                  onChange={(e) => setSelectedTenantId(e.target.value)}
                  className={`${inputClass} text-xs font-bold`}
                >
                  {tenants.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name} ({t.id}) — {t.status}
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {canManageTenantUsers && (
              <Button
                size="sm"
                disabled={!selectedTenantId}
                onClick={() => openTenantUserModal()}
                leadingIcon={<UserPlus className="h-4 w-4" />}
              >
                إضافة مستخدم للعميل
              </Button>
            )}
          </div>

          {/* Tenant Users Table */}
          <section className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
            <header className="border-b border-slate-800 px-4 py-3 bg-slate-950/40 flex items-center justify-between">
              <div>
                <h3 className="text-xs font-bold text-slate-200">
                  مستخدمو نظام ERP للشركة المحددة ({tenantUsers.length} مستخدمين)
                </h3>
                <p className="text-[10.5px] text-slate-400">
                  إدارة أدوار وحسابات موظفي المتجر أو المصنع التابع للعميل.
                </p>
              </div>
            </header>

            {tenantUsersLoading ? (
              <div className="py-16 text-center text-sm font-semibold text-slate-500">
                <RefreshCw className="inline-block h-5 w-5 animate-spin mb-2" />
                <p>جارٍ تحميل مستخدمي العميل...</p>
              </div>
            ) : tenantUsers.length === 0 ? (
              <EmptyState
                icon={<Users className="h-6 w-6 text-slate-500" />}
                title="لا يوجد مستخدمون مسجلون لهذا العميل"
                description="يمكنك إنشاء مستخدم جديد وتعيين دوره (مدير، محاسب، مبيعات، كاشير، إلخ)."
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[800px] text-right">
                  <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                    <tr>
                      <th className="px-4 py-3">اسم المستخدم</th>
                      <th className="px-4 py-3">اسم الدخول / البريد</th>
                      <th className="px-4 py-3">رقم الهاتف</th>
                      <th className="px-4 py-3">الدور في ERP</th>
                      <th className="px-4 py-3">الحالة</th>
                      <th className="px-4 py-3 text-center">الإجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/80">
                    {tenantUsers.map((user) => (
                      <tr key={user.id} className="hover:bg-slate-800/30 transition-colors">
                        <td className="px-4 py-3.5 text-xs font-bold text-slate-100">{user.fullName}</td>
                        <td className="px-4 py-3.5 text-xs text-slate-300">
                          {user.email || user.username || '—'}
                        </td>
                        <td className="px-4 py-3.5 text-xs text-slate-400">{user.phone || '—'}</td>
                        <td className="px-4 py-3.5">
                          <span className="inline-flex rounded-md bg-slate-800 border border-slate-700 px-2.5 py-0.5 text-xs font-bold text-slate-200">
                            {user.role}
                          </span>
                        </td>
                        <td className="px-4 py-3.5">
                          <span
                            className={`inline-flex items-center gap-1 text-[11px] font-bold ${
                              user.status === 'ACTIVE'
                                ? 'text-emerald-400'
                                : user.status === 'INVITED'
                                ? 'text-amber-400'
                                : 'text-rose-400'
                            }`}
                          >
                            {user.status === 'ACTIVE'
                              ? 'نشط'
                              : user.status === 'INVITED'
                              ? 'في انتظار التفعيل'
                              : 'معطل'}
                          </span>
                        </td>
                        <td className="px-4 py-3.5">
                          <div className="flex items-center justify-center gap-1.5">
                            {canManageTenantUsers && (
                              <>
                                <button
                                  onClick={() => openTenantUserModal(user)}
                                  title="تعديل المستخدم"
                                  className="rounded p-1 text-slate-400 hover:bg-slate-800 hover:text-slate-200"
                                >
                                  <Pencil className="h-3.5 w-3.5" />
                                </button>

                                <button
                                  onClick={() => handleToggleTenantUserActive(user)}
                                  title={user.status === 'ACTIVE' ? 'تعطيل الحساب' : 'تنشيط الحساب'}
                                  className={`rounded p-1 ${
                                    user.status === 'ACTIVE'
                                      ? 'text-amber-400 hover:bg-amber-950/40'
                                      : 'text-emerald-400 hover:bg-emerald-950/40'
                                  }`}
                                >
                                  {user.status === 'ACTIVE' ? (
                                    <Lock className="h-3.5 w-3.5" />
                                  ) : (
                                    <Unlock className="h-3.5 w-3.5" />
                                  )}
                                </button>

                                <button
                                  onClick={() => handleDeleteTenantUser(user)}
                                  title="حذف المستخدم"
                                  className="rounded p-1 text-rose-400 hover:bg-rose-950/40"
                                >
                                  <Trash2 className="h-3.5 w-3.5" />
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </div>
      )}

      {/* Modal: Add/Edit Staff */}
      <Modal
        open={isStaffModalOpen}
        onClose={() => setIsStaffModalOpen(false)}
        title={editingStaff ? 'تعديل موظف المنصة' : 'إضافة موظف جديد للمنصة'}
      >
        <div className="space-y-3.5 text-right">
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">الاسم الكامل *</label>
            <input
              type="text"
              value={staffForm.fullName}
              onChange={(e) => setStaffForm({ ...staffForm, fullName: e.target.value })}
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">البريد الإلكتروني للعمل *</label>
            <input
              type="email"
              value={staffForm.email}
              onChange={(e) => setStaffForm({ ...staffForm, email: e.target.value })}
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">رقم الهاتف</label>
            <input
              type="text"
              value={staffForm.phone}
              onChange={(e) => setStaffForm({ ...staffForm, phone: e.target.value })}
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">الدور الوظيفي بالمنصة *</label>
            <select
              value={staffForm.role}
              disabled={editingStaff?.role === 'SUPER_ADMIN'}
              onChange={(e) => setStaffForm({ ...staffForm, role: e.target.value as any })}
              className={inputClass}
            >
              <option value="SUPPORT_AGENT">موظف دعم فني (Support Specialist)</option>
              <option value="OPERATIONS_ENGINEER">مهندس عمليات وبنية تحتية (Operations Engineer)</option>
              <option value="BILLING_SPECIALIST">أخصائي فواتير واشتراكات (Billing Specialist)</option>
              <option value="LICENSE_MANAGER">مسؤول تراخيص وأجهزة (License Administrator)</option>
              <option value="PLATFORM_ADMIN">مدير منصة عام (Platform Administrator)</option>
              {editingStaff?.role === 'SUPER_ADMIN' && (
                <option value="SUPER_ADMIN">مالك المنصة (Super Admin)</option>
              )}
            </select>
            <p className="text-[10.5px] text-slate-400 mt-1">
              ملاحظة: موظف الدعم أو العمليات لن يحصل على صلاحيات مالك المنصة أو تغيير الأسعار والتراخيص.
            </p>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">
              {editingStaff ? 'كلمة مرور جديدة (اختياري)' : 'كلمة المرور الأولية *'}
            </label>
            <input
              type="password"
              value={staffForm.password || ''}
              onChange={(e) => setStaffForm({ ...staffForm, password: e.target.value })}
              placeholder={editingStaff ? 'اتركها فارغة للإبقاء على الحالية' : '8 أحرف على الأقل'}
              className={inputClass}
            />
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsStaffModalOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleSaveStaff} disabled={!canManageStaff}>
              حفظ الموظف
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal: Add/Edit Tenant User */}
      <Modal
        open={isTenantUserModalOpen}
        onClose={() => setIsTenantUserModalOpen(false)}
        title={editingTenantUser ? 'تعديل مستخدم العميل' : 'إضافة مستخدم جديد لشركة العميل'}
      >
        <div className="space-y-3.5 text-right">
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">اسم الموظف الكامل *</label>
            <input
              type="text"
              value={tenantUserForm.fullName}
              onChange={(e) => setTenantUserForm({ ...tenantUserForm, fullName: e.target.value })}
              className={inputClass}
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">اسم الدخول (Username)</label>
              <input
                type="text"
                value={tenantUserForm.username || ''}
                onChange={(e) => setTenantUserForm({ ...tenantUserForm, username: e.target.value })}
                className={inputClass}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">البريد الإلكتروني</label>
              <input
                type="email"
                value={tenantUserForm.email || ''}
                onChange={(e) => setTenantUserForm({ ...tenantUserForm, email: e.target.value })}
                className={inputClass}
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">الدور في ERP</label>
              <select
                value={tenantUserForm.role}
                onChange={(e) => setTenantUserForm({ ...tenantUserForm, role: e.target.value })}
                className={inputClass}
              >
                <option value="ADMIN">مدير النظام (Admin)</option>
                <option value="MANAGER">مدير فرع (Manager)</option>
                <option value="ACCOUNTANT">محاسب (Accountant)</option>
                <option value="SALES">مبيعات (Sales)</option>
                <option value="CASHIER">كاشير (Cashier)</option>
                <option value="WAREHOUSE">مسؤول مستودع (Warehouse)</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">رقم الهاتف</label>
              <input
                type="text"
                value={tenantUserForm.phone || ''}
                onChange={(e) => setTenantUserForm({ ...tenantUserForm, phone: e.target.value })}
                className={inputClass}
              />
            </div>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsTenantUserModalOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleSaveTenantUser} disabled={!canManageTenantUsers}>
              حفظ المستخدم
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformAdminControlPage;

import React, { useState, useEffect, useCallback } from 'react';
import {
  BarChart3,
  Users,
  CalendarClock,
  ShieldCheck,
  RefreshCw,
  Download,
  ArrowUpRight,
  ArrowDownRight,
  Filter,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import type {
  PlatformBusinessPerformance,
  PlatformCustomerMetrics,
  PlatformSubscriptionMetrics,
  PlatformLicenseMetrics,
  PlatformOperationsMetrics,
  PlatformPeriod,
  PlatformPlan,
} from '../../services/domains/platform/platformTypes';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import {
  formatMoney,
  formatNumber,
  formatDateTime,
  inputClass,
  downloadCsv,
} from './components/PlatformUI';

export const PlatformAnalyticsPage: React.FC = () => {
  const [period, setPeriod] = useState<PlatformPeriod>('30d');
  const [planId, setPlanId] = useState<string>('');
  const [plans, setPlans] = useState<PlatformPlan[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Analytics states
  const [businessPerf, setBusinessPerf] = useState<PlatformBusinessPerformance | null>(null);
  const [customerMetrics, setCustomerMetrics] = useState<PlatformCustomerMetrics | null>(null);
  const [subMetrics, setSubMetrics] = useState<PlatformSubscriptionMetrics | null>(null);
  const [licenseMetrics, setLicenseMetrics] = useState<PlatformLicenseMetrics | null>(null);
  const [opsMetrics, setOpsMetrics] = useState<PlatformOperationsMetrics | null>(null);

  const loadData = useCallback(() => {
    setLoading(true);
    try {
      const plns = platformAdminService.listPlans();
      setPlans(plns);

      const bp = platformAdminService.getBusinessPerformance(period, planId || undefined);
      const cm = platformAdminService.getCustomerMetrics(period, planId || undefined);
      const sm = platformAdminService.getSubscriptionMetrics(period, planId || undefined);
      const lm = platformAdminService.getLicenseMetrics(period, planId || undefined);
      const om = platformAdminService.getOperationsMetrics(period);

      setBusinessPerf(bp);
      setCustomerMetrics(cm);
      setSubMetrics(sm);
      setLicenseMetrics(lm);
      setOpsMetrics(om);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل التحليلات والتقارير.');
    } finally {
      setLoading(false);
    }
  }, [period, planId]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const renderDelta = (percent?: number) => {
    if (percent === undefined || percent === null) return null;
    const isPositive = percent >= 0;
    return (
      <span
        className={`inline-flex items-center gap-0.5 text-[11px] font-bold ${
          isPositive ? 'text-emerald-400' : 'text-rose-400'
        }`}
        dir="ltr"
      >
        {isPositive ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}
        {Math.abs(percent)}%
      </span>
    );
  };

  const exportReport = () => {
    if (!businessPerf || !customerMetrics || !subMetrics) return;
    downloadCsv(`platform-analytics-${period}.csv`, [
      ['المؤشر', 'القيمة الحالية', 'الفترة السابقة', 'نسبة التغير %'],
      ['الإيرادات المحصلة', businessPerf.revenue.total.current, businessPerf.revenue.total.previous, businessPerf.revenue.total.changePercent],
      ['MRR الإيراد الشهري المتكرر', businessPerf.revenue.mrr.current, businessPerf.revenue.mrr.previous, businessPerf.revenue.mrr.changePercent],
      ['ARR الإيراد السنوي المتوقع', businessPerf.revenue.arr.current, businessPerf.revenue.arr.previous, businessPerf.revenue.arr.changePercent],
      ['العملاء النشطون', customerMetrics.activeCustomers.current, customerMetrics.activeCustomers.previous, customerMetrics.activeCustomers.changePercent],
      ['عملاء جدد', customerMetrics.newCustomers.current, customerMetrics.newCustomers.previous, customerMetrics.newCustomers.changePercent],
      ['متوسط قيمة العميل ARPU', customerMetrics.averageRevenuePerCustomer.current, customerMetrics.averageRevenuePerCustomer.previous, customerMetrics.averageRevenuePerCustomer.changePercent],
      ['تجديدات قادمة', subMetrics.upcomingRenewals.current, subMetrics.upcomingRenewals.previous, subMetrics.upcomingRenewals.changePercent],
      ['معدل فقدان العملاء Churn Rate', `${customerMetrics.churnRate.current}%`, `${customerMetrics.churnRate.previous}%`, customerMetrics.churnRate.changePercent],
    ]);
  };

  return (
    <div className="space-y-4 text-right">
      <PageHeader
        title="التقارير والتحليلات المركزية (Platform Analytics & BI)"
        description="تحليلات الإيرادات (MRR/ARR)، معدلات النمو، سلوك العملاء، التراخيص، ومؤشرات الأداء التشغيلي."
        icon={<BarChart3 className="h-5 w-5" />}
        actions={
          <div className="flex gap-2">
            <Button
              size="sm"
              variant="secondary"
              onClick={exportReport}
              leadingIcon={<Download className="h-4 w-4" />}
            >
              تصدير التقرير CSV
            </Button>
            <Button
              size="sm"
              onClick={loadData}
              leadingIcon={<RefreshCw className="h-4 w-4" />}
            >
              تحديث الأرقام
            </Button>
          </div>
        }
      />

      {/* Filter Header */}
      <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-800 bg-slate-900/60 p-3 shadow-sm">
        <div className="flex items-center gap-2">
          <Filter className="h-4 w-4 text-slate-400" />
          <span className="text-xs font-bold text-slate-200">الفترة الزمنية:</span>
          <div className="flex rounded-lg bg-slate-950 p-1 border border-slate-800 text-xs">
            {(
              [
                { id: '7d', label: '7 أيام' },
                { id: '30d', label: '30 يوماً' },
                { id: '90d', label: 'ربع سنوي' },
                { id: '365d', label: 'سنة كاملة' },
              ] as const
            ).map((p) => (
              <button
                key={p.id}
                onClick={() => setPeriod(p.id)}
                className={`px-3 py-1 rounded font-bold transition-colors ${
                  period === p.id
                    ? 'bg-sky-500 text-white shadow'
                    : 'text-slate-400 hover:text-slate-200'
                }`}
              >
                {p.label}
              </button>
            ))}
          </div>
        </div>

        <div className="flex items-center gap-2">
          <span className="text-xs font-semibold text-slate-300">فلترة حسب الباقة:</span>
          <select
            value={planId}
            onChange={(e) => setPlanId(e.target.value)}
            className={`${inputClass} max-w-[200px]`}
          >
            <option value="">جميع الباقات</option>
            {plans.map((p) => (
              <option key={p.id} value={p.id}>
                {p.name}
              </option>
            ))}
          </select>
        </div>
      </div>

      {error && (
        <div className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-lg text-xs font-bold text-rose-300">
          {error}
        </div>
      )}

      {loading ? (
        <div className="py-20 text-center text-sm font-semibold text-slate-500">جارٍ تجميع بيانات التحليلات...</div>
      ) : (
        <>
          {/* Revenue & Financial KPIs */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-3">
            <div className="p-4 bg-slate-900/80 border border-slate-800 rounded-xl">
              <div className="flex justify-between items-start">
                <p className="text-xs font-semibold text-slate-400">الإيراد المحصل بالفترة</p>
                {renderDelta(businessPerf?.revenue.total.changePercent)}
              </div>
              <p className="text-2xl font-black text-slate-100 mt-2">
                {formatMoney(businessPerf?.revenue.total.current || 0)}
              </p>
              <p className="text-[10px] text-slate-500 mt-1">
                الفترة السابقة: {formatMoney(businessPerf?.revenue.total.previous || 0)}
              </p>
            </div>

            <div className="p-4 bg-emerald-950/20 border border-emerald-500/20 rounded-xl">
              <div className="flex justify-between items-start">
                <p className="text-xs font-semibold text-emerald-400">MRR (الإيراد المتكرر شهرياً)</p>
                {renderDelta(businessPerf?.revenue.mrr.changePercent)}
              </div>
              <p className="text-2xl font-black text-emerald-300 mt-2">
                {formatMoney(businessPerf?.revenue.mrr.current || 0)}
              </p>
              <p className="text-[10px] text-emerald-500/70 mt-1">
                الفترة السابقة: {formatMoney(businessPerf?.revenue.mrr.previous || 0)}
              </p>
            </div>

            <div className="p-4 bg-sky-950/20 border border-sky-500/20 rounded-xl">
              <div className="flex justify-between items-start">
                <p className="text-xs font-semibold text-sky-400">ARR (الإيراد السنوي المتوقع)</p>
                {renderDelta(businessPerf?.revenue.arr.changePercent)}
              </div>
              <p className="text-2xl font-black text-sky-300 mt-2">
                {formatMoney(businessPerf?.revenue.arr.current || 0)}
              </p>
              <p className="text-[10px] text-sky-500/70 mt-1">
                الفترة السابقة: {formatMoney(businessPerf?.revenue.arr.previous || 0)}
              </p>
            </div>

            <div className="p-4 bg-purple-950/20 border border-purple-500/20 rounded-xl">
              <div className="flex justify-between items-start">
                <p className="text-xs font-semibold text-purple-400">متوسط قيمة العميل (ARPU)</p>
                {renderDelta(customerMetrics?.averageRevenuePerCustomer.changePercent)}
              </div>
              <p className="text-2xl font-black text-purple-300 mt-2">
                {formatMoney(customerMetrics?.averageRevenuePerCustomer.current || 0)}
              </p>
              <p className="text-[10px] text-purple-500/70 mt-1">
                الفترة السابقة: {formatMoney(customerMetrics?.averageRevenuePerCustomer.previous || 0)}
              </p>
            </div>
          </div>

          {/* Customer & Subscription Insights */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-slate-900/70 border border-slate-800 rounded-xl space-y-3">
              <h3 className="text-xs font-bold text-slate-200 flex items-center gap-2">
                <Users className="h-4 w-4 text-sky-400" />
                ديناميكية العملاء ومعدلات التسرب
              </h3>

              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">العملاء النشطون</p>
                  <p className="text-lg font-black text-slate-100 mt-0.5">
                    {formatNumber(customerMetrics?.activeCustomers.current || 0)}
                  </p>
                  {renderDelta(customerMetrics?.activeCustomers.changePercent)}
                </div>

                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">عملاء جدد</p>
                  <p className="text-lg font-black text-emerald-400 mt-0.5">
                    +{formatNumber(customerMetrics?.newCustomers.current || 0)}
                  </p>
                  {renderDelta(customerMetrics?.newCustomers.changePercent)}
                </div>

                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">معدل الفقد (Churn)</p>
                  <p className="text-lg font-black text-rose-400 mt-0.5">
                    {customerMetrics?.churnRate.current || 0}%
                  </p>
                  {renderDelta(customerMetrics?.churnRate.changePercent)}
                </div>
              </div>
            </div>

            <div className="p-4 bg-slate-900/70 border border-slate-800 rounded-xl space-y-3">
              <h3 className="text-xs font-bold text-slate-200 flex items-center gap-2">
                <CalendarClock className="h-4 w-4 text-emerald-400" />
                حركة الاشتراكات والتجديدات
              </h3>

              <div className="grid grid-cols-3 gap-2 text-center">
                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">تجديدات قادمة</p>
                  <p className="text-lg font-black text-slate-100 mt-0.5">
                    {formatNumber(subMetrics?.upcomingRenewals.current || 0)}
                  </p>
                  {renderDelta(subMetrics?.upcomingRenewals.changePercent)}
                </div>

                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">فترات تجريبية منتهية</p>
                  <p className="text-lg font-black text-amber-400 mt-0.5">
                    {formatNumber(subMetrics?.expiredTrials.current || 0)}
                  </p>
                  {renderDelta(subMetrics?.expiredTrials.changePercent)}
                </div>

                <div className="p-2.5 bg-slate-950/60 rounded-lg border border-slate-800">
                  <p className="text-[11px] text-slate-400">نسبة التحويل التجريبي</p>
                  <p className="text-lg font-black text-sky-400 mt-0.5">
                    {subMetrics?.trialConversionRate.current || 0}%
                  </p>
                  {renderDelta(subMetrics?.trialConversionRate.changePercent)}
                </div>
              </div>
            </div>
          </div>

          {/* Operational Health & Sync Overview */}
          <div className="p-4 bg-slate-900/70 border border-slate-800 rounded-xl space-y-3">
            <h3 className="text-xs font-bold text-slate-200 flex items-center gap-2">
              <ShieldCheck className="h-4 w-4 text-purple-400" />
              مؤشرات الأداء التشغيلي والمزامنة
            </h3>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-center">
              <div className="p-3 bg-slate-950/60 rounded-lg border border-slate-800">
                <p className="text-[11px] text-slate-400">الأجهزة المنشطة</p>
                <p className="text-lg font-black text-slate-100 mt-1">
                  {formatNumber(licenseMetrics?.activatedDevices.current || 0)}
                </p>
                {renderDelta(licenseMetrics?.activatedDevices.changePercent)}
              </div>

              <div className="p-3 bg-slate-950/60 rounded-lg border border-slate-800">
                <p className="text-[11px] text-slate-400">نسبة استخدام التراخيص</p>
                <p className="text-lg font-black text-sky-400 mt-1">
                  {licenseMetrics?.utilizationRate.current || 0}%
                </p>
                {renderDelta(licenseMetrics?.utilizationRate.changePercent)}
              </div>

              <div className="p-3 bg-slate-950/60 rounded-lg border border-slate-800">
                <p className="text-[11px] text-slate-400">أخطاء المزامنة المسجلة</p>
                <p className="text-lg font-black text-amber-400 mt-1">
                  {formatNumber(opsMetrics?.syncErrors.current || 0)}
                </p>
                {renderDelta(opsMetrics?.syncErrors.changePercent)}
              </div>

              <div className="p-3 bg-slate-950/60 rounded-lg border border-slate-800">
                <p className="text-[11px] text-slate-400">صحة واجهات API</p>
                <p className="text-lg font-black text-emerald-400 mt-1">
                  {opsMetrics?.apiHealth.current || 0}%
                </p>
                {renderDelta(opsMetrics?.apiHealth.changePercent)}
              </div>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default PlatformAnalyticsPage;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Cpu,
  Key,
  ShieldCheck,
  Send,
  Layers,
  FileCode,
  RotateCcw,
  CheckCircle2,
  AlertTriangle,
  History,
  Activity,
  Play,
  Save,
  Check,
  X,
  FileDiff,
  Download,
  Upload,
  RefreshCw,
  Search,
  Filter,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformTenant,
  PlatformConfigTemplate,
  PlatformTenantConfig,
  PlatformTenantConfigVersion,
  PlatformConfigRollout,
  PlatformConfigAck,
  RolloutTargetType,
} from '../../services/domains/platform/platformTypes';
import { Button } from '../../components/ui/Button';
import { PageHeader } from '../../components/ui/PageHeader';
import { EmptyState, formatDateTime, inputClass } from './components/PlatformUI';

type ConfigTab = 'editor' | 'templates' | 'rollout' | 'diff' | 'history' | 'telemetry';

export const PlatformAppConfigurationPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<ConfigTab>('editor');
  const canManageAppConfig = canPlatform('app-configuration');
  const [tenants, setTenants] = useState<PlatformTenant[]>([]);
  const [selectedTenantId, setSelectedTenantId] = useState<string>('');
  const [templates, setTemplates] = useState<PlatformConfigTemplate[]>([]);
  const [rollouts, setRollouts] = useState<PlatformConfigRollout[]>([]);
  const [acks, setAcks] = useState<PlatformConfigAck[]>([]);
  const [versions, setVersions] = useState<PlatformTenantConfigVersion[]>([]);

  const [loading, setLoading] = useState<boolean>(true);
  const [saving, setSaving] = useState<boolean>(false);
  const [savedSuccess, setSavedSuccess] = useState<boolean>(false);

  // Active Tenant Config State
  const [currentConfig, setCurrentConfig] = useState<PlatformTenantConfig | null>(null);
  const [jsonText, setJsonText] = useState<string>('{}');
  const [jsonError, setJsonError] = useState<string | null>(null);

  // Rollout modal / creation state
  const [rolloutTitle, setRolloutTitle] = useState<string>('');
  const [rolloutTargetType, setRolloutTargetType] = useState<RolloutTargetType>('ALL');
  const [rolloutCanaryPercent, setRolloutCanaryPercent] = useState<number>(20);
  const [rolloutTemplateId, setRolloutTemplateId] = useState<string>('');
  const [rolloutSuccess, setRolloutSuccess] = useState<boolean>(false);

  // Diff comparison state
  const [diffVersionA, setDiffVersionA] = useState<number>(1);
  const [diffVersionB, setDiffVersionB] = useState<number>(1);

  // Bootstrap data
  const loadBootstrap = useCallback(() => {
    try {
      const tList = platformAdminService.listTenants();
      setTenants(tList);
      if (tList.length > 0 && !selectedTenantId) {
        setSelectedTenantId(tList[0].id);
      }
      const tmplList = platformAdminService.listConfigTemplates();
      setTemplates(tmplList);
      setRolloutTemplateId((prev) => (tmplList.some((t) => t.id === prev) ? prev : tmplList[0]?.id ?? ''));
      const rList = platformAdminService.listConfigRollouts();
      setRollouts(rList);
    } catch (e) {
      console.error('Failed to load bootstrap config:', e);
    }
  }, [selectedTenantId]);

  // Load tenant configuration
  const loadTenantConfig = useCallback((tenantId: string) => {
    if (!tenantId) return;
    setLoading(true);
    setJsonError(null);
    try {
      const cfg = platformAdminService.getTenantConfig(tenantId);
      setCurrentConfig(cfg);
      setJsonText(JSON.stringify(cfg.configPayload, null, 2));

      const vList = platformAdminService.listTenantConfigVersions(tenantId);
      setVersions(vList);
      if (vList.length >= 2) {
        setDiffVersionA(vList[0].version);
        setDiffVersionB(vList[1].version);
      } else if (vList.length === 1) {
        setDiffVersionA(vList[0].version);
        setDiffVersionB(vList[0].version);
      }

      const ackList = platformAdminService.listConfigAcks(tenantId);
      setAcks(ackList);
    } catch (e) {
      console.error('Failed to load tenant config:', e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadBootstrap();
  }, [loadBootstrap]);

  useEffect(() => {
    if (selectedTenantId) {
      loadTenantConfig(selectedTenantId);
    }
  }, [selectedTenantId, loadTenantConfig]);

  // Handle Save & Sign
  const handleSaveConfig = () => {
    if (!canManageAppConfig) { alert('لا تملك صلاحية إدارة إعدادات التطبيق'); return; }
    if (!selectedTenantId) return;
    setSaving(true);
    setSavedSuccess(false);
    setJsonError(null);
    try {
      let parsedPayload: Record<string, unknown>;
      try {
        parsedPayload = JSON.parse(jsonText);
      } catch (pe) {
        setJsonError(`خطأ في صياغة JSON: ${(pe as Error).message}`);
        setSaving(false);
        return;
      }

      const updated = platformAdminService.saveTenantConfig({
        tenantId: selectedTenantId,
        values: parsedPayload,
        changeSummary: 'تعديل وتوقيع يدوي عبر محرر التكوين المركزي',
      });

      setCurrentConfig(updated);
      setSavedSuccess(true);
      setTimeout(() => setSavedSuccess(false), 3000);
      loadTenantConfig(selectedTenantId);
    } catch (err) {
      alert((err as Error).message);
    } finally {
      setSaving(false);
    }
  };

  // Handle Apply Template
  const handleApplyTemplate = (tmpl: PlatformConfigTemplate) => {
    if (!canManageAppConfig) { alert('لا تملك صلاحية إدارة إعدادات التطبيق'); return; }
    if (!confirm(`هل تريد تطبيق قالب "${tmpl.name}" على هذا العميل؟ سيتم استبدال التكوين الحالي وإعادة توقيعه.`)) return;
    setJsonText(JSON.stringify(tmpl.configPayload, null, 2));
    setJsonError(null);
  };

  // Handle Rollback
  const handleRollback = (ver: number) => {
    if (!canManageAppConfig) { alert('لا تملك صلاحية إدارة إعدادات التطبيق'); return; }
    if (!confirm(`هل أنت متأكد من استرجاع التكوين للإصدار #${ver} وتطبيقه فورياً؟`)) return;
    try {
      platformAdminService.rollbackTenantConfig(selectedTenantId, ver);
      loadTenantConfig(selectedTenantId);
      alert(`تم استرجاع الإصدار #${ver} وتوقيعه بنجاح.`);
    } catch (err) {
      alert((err as Error).message);
    }
  };

  // Handle Create Rollout
  const handleCreateRollout = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManageAppConfig) { alert('لا تملك صلاحية إدارة إعدادات التطبيق'); return; }
    if (!rolloutTitle || !rolloutTemplateId) return;
    try {
      const created = platformAdminService.createConfigRollout({
        templateId: rolloutTemplateId,
        name: rolloutTitle,
        targetType: rolloutTargetType,
        rolloutPercentage: rolloutTargetType === 'CANARY_PERCENT' ? rolloutCanaryPercent : undefined,
      });
      platformAdminService.startConfigRollout(created.id);

      setRolloutSuccess(true);
      setTimeout(() => setRolloutSuccess(false), 4000);
      setRolloutTitle('');
      loadBootstrap();
      if (selectedTenantId) loadTenantConfig(selectedTenantId);
    } catch (err) {
      alert((err as Error).message);
    }
  };

  // Diff Calculations
  const diffDisplay = useMemo(() => {
    const vA = versions.find((v) => v.version === diffVersionA);
    const vB = versions.find((v) => v.version === diffVersionB);
    if (!vA || !vB) return null;

    const keysA = Object.keys(vA.configPayload);
    const keysB = Object.keys(vB.configPayload);
    const allKeys = Array.from(new Set([...keysA, ...keysB]));

    return allKeys.map((key) => {
      const valA = vA.configPayload[key];
      const valB = vB.configPayload[key];
      const changed = JSON.stringify(valA) !== JSON.stringify(valB);
      return {
        key,
        valA: valA !== undefined ? JSON.stringify(valA) : '(غير موجود)',
        valB: valB !== undefined ? JSON.stringify(valB) : '(غير موجود)',
        changed,
      };
    });
  }, [versions, diffVersionA, diffVersionB]);

  return (
    <div className="space-y-6" dir="rtl">
      {/* Page Header */}
      <PageHeader
        title="محرك التكوين الديناميكي والنشر المركزي (App Configuration)"
        description="إدارة قوالب التكوين، التوقيع الرقمي المشفر (Ed25519)، النشر التدريجي على العملاء، ومراقبة استلام الأجهزة"
        actions={
          <div className="flex items-center gap-2">
            <Button
              variant="primary"
              onClick={handleSaveConfig}
              disabled={saving || loading || !selectedTenantId || !canManageAppConfig}
            >
              <Save className="w-4 h-4 ml-2" />
              {saving ? 'جاري التوقيع والحفظ...' : 'توقيع التكوين وحفظه'}
            </Button>
          </div>
        }
      />

      {/* Tenant Selector & Cryptographic Signature Status */}
      <div className="bg-zinc-900/60 p-4 rounded-xl border border-zinc-800 flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-3">
          <Cpu className="w-5 h-5 text-emerald-400" />
          <div>
            <label className="text-xs font-semibold text-zinc-300 block mb-1">العميل المستهدف:</label>
            <select
              value={selectedTenantId}
              onChange={(e) => setSelectedTenantId(e.target.value)}
              className={`${inputClass} min-w-[280px]`}
            >
              {tenants.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name} ({t.code}) - {t.businessType || 'عام'}
                </option>
              ))}
            </select>
          </div>
        </div>

        <div className="flex items-center gap-4 text-xs">
          {savedSuccess && (
            <span className="flex items-center gap-1.5 text-emerald-400 font-semibold bg-emerald-950/40 px-3 py-1.5 rounded-lg border border-emerald-800/40">
              <CheckCircle2 className="w-4 h-4" />
              تم توقيع وحفظ التكوين
            </span>
          )}

          <div className="flex items-center gap-2 bg-zinc-950 px-3 py-1.5 rounded-lg border border-zinc-800">
            <ShieldCheck className="w-4 h-4 text-emerald-400" />
            <span className="text-zinc-300">
              التوقيع الرقمي: <code className="text-emerald-400 font-mono text-[11px]">{currentConfig?.signature?.substring(0, 16)}...</code>
            </span>
          </div>

          <span className="text-zinc-400">
            الإصدار: <strong className="text-zinc-200">#{currentConfig?.version || 1}</strong>
          </span>
        </div>
      </div>

      {/* Tabs Navigation */}
      <div className="flex border-b border-zinc-800 space-x-1 space-x-reverse overflow-x-auto">
        <button
          onClick={() => setActiveTab('editor')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'editor' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <FileCode className="w-4 h-4" />
          محرر التكوين المركزي (JSON)
        </button>
        <button
          onClick={() => setActiveTab('templates')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'templates' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Layers className="w-4 h-4" />
          قوالب الأنشطة والخطط
        </button>
        <button
          onClick={() => setActiveTab('rollout')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'rollout' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Send className="w-4 h-4" />
          النشر التدريجي والحملات
        </button>
        <button
          onClick={() => setActiveTab('diff')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'diff' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <FileDiff className="w-4 h-4" />
          مقارنة النسخ (Diff)
        </button>
        <button
          onClick={() => setActiveTab('history')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'history' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <History className="w-4 h-4" />
          سجل الإصدارات والاسترجاع
        </button>
        <button
          onClick={() => setActiveTab('telemetry')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'telemetry' ? 'border-emerald-500 text-emerald-400' : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Activity className="w-4 h-4" />
          تأكيد استلام الأجهزة (ACK)
        </button>
      </div>

      {/* ─── TAB 1: Visual & JSON Editor ──────────────────────────────────────────── */}
      {activeTab === 'editor' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between text-xs text-zinc-400">
            <span>محرر كود التكوين الديناميكي بصيغة JSON الموقعة مشفراً:</span>
            <span className="text-zinc-500">يتوافق تلقائياً مع محرك التحقق المركزي في CentralLicenseService</span>
          </div>

          {jsonError && (
            <div className="p-3 bg-rose-950/30 border border-rose-800/40 rounded-lg text-rose-300 text-xs flex items-center gap-2">
              <AlertTriangle className="w-4 h-4 flex-shrink-0" />
              <span>{jsonError}</span>
            </div>
          )}

          <div className="relative">
            <textarea
              rows={18}
              value={jsonText}
              onChange={(e) => {
                setJsonText(e.target.value);
                setJsonError(null);
              }}
              dir="ltr"
              className="w-full bg-zinc-950 text-zinc-100 font-mono text-xs p-4 rounded-xl border border-zinc-800 focus:border-emerald-500 focus:ring-1 focus:ring-emerald-500 outline-none leading-relaxed"
              placeholder="{ ... }"
            />
          </div>
        </div>
      )}

      {/* ─── TAB 2: Activity & Plan Templates ─────────────────────────────────────── */}
      {activeTab === 'templates' && (
        <div className="space-y-4">
          <div className="text-xs text-zinc-400">
            اختر قالباً لتطبيق حزمة إعدادات كاملة وموحدة لنوع نشاط العميل:
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {templates.map((tmpl) => (
              <div
                key={tmpl.id}
                className="bg-zinc-900/60 p-4 rounded-xl border border-zinc-800 space-y-3 flex flex-col justify-between"
              >
                <div>
                  <div className="flex items-center justify-between">
                    <h4 className="font-semibold text-zinc-100 text-sm">{tmpl.name}</h4>
                    {tmpl.isDefault && (
                      <span className="text-[10px] bg-emerald-500/10 text-emerald-400 border border-emerald-500/20 px-2 py-0.5 rounded">
                        افتراضي
                      </span>
                    )}
                  </div>
                  <div className="text-xs text-zinc-500 font-mono mt-1">الرمز: {tmpl.code}</div>
                  <pre
                    dir="ltr"
                    className="mt-3 p-2 bg-zinc-950 rounded text-[11px] font-mono text-zinc-400 max-h-32 overflow-y-auto"
                  >
                    {JSON.stringify(tmpl.configPayload, null, 2)}
                  </pre>
                </div>

                <Button
                  variant="secondary"
                  size="sm"
                  className="w-full mt-3"
                  disabled={!canManageAppConfig}
                  onClick={() => handleApplyTemplate(tmpl)}
                >
                  استيراد هذا القالب إلى المحرر
                </Button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ─── TAB 3: Phased Rollouts ───────────────────────────────────────────────── */}
      {activeTab === 'rollout' && (
        <div className="space-y-6">
          {/* Create Rollout Card */}
          <div className="bg-zinc-900/50 p-5 rounded-xl border border-zinc-800 space-y-4">
            <h3 className="text-sm font-semibold text-zinc-100 flex items-center gap-2">
              <Send className="w-4 h-4 text-emerald-400" />
              إطلاق حملة نشر تكوين تدريجي جديدة (Canary / Phased Rollout)
            </h3>

            {rolloutSuccess && (
              <div className="p-3 bg-emerald-950/40 border border-emerald-800/40 rounded-lg text-emerald-300 text-xs flex items-center gap-2">
                <CheckCircle2 className="w-4 h-4" />
                <span>تم إطلاق حملة النشر وتحديث أجهزة العملاء المستهدفين بنجاح.</span>
              </div>
            )}

            <form onSubmit={handleCreateRollout} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">عنوان الحملة / ملاحظات الإصدار</label>
                <input
                  type="text"
                  required
                  placeholder="مثال: ترقية إعدادات الفاتورة الإلكترونية - دفعة 1"
                  value={rolloutTitle}
                  onChange={(e) => setRolloutTitle(e.target.value)}
                  className={`w-full ${inputClass}`}
                />
              </div>

              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">قالب التكوين المراد نشره</label>
                <select
                  value={rolloutTemplateId}
                  onChange={(e) => setRolloutTemplateId(e.target.value)}
                  className={`w-full ${inputClass}`}
                  required
                >
                  {templates.map((tmpl) => (
                    <option key={tmpl.id} value={tmpl.id}>
                      {tmpl.name} ({tmpl.code})
                    </option>
                  ))}
                </select>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-zinc-400 mb-1">شريحة النشر المستهدفة</label>
                  <select
                    value={rolloutTargetType}
                    onChange={(e) => setRolloutTargetType(e.target.value as RolloutTargetType)}
                    className={`w-full ${inputClass}`}
                  >
                    <option value="ALL">كافة عملاء المنصة (100% Rollout)</option>
                    <option value="CANARY_PERCENT">نسبة تدريجية (Canary Testing %)</option>
                    <option value="ACTIVITY">بحسب نوع النشاط التجاري</option>
                    <option value="PLAN">بحسب باقة الاشتراك</option>
                  </select>
                </div>

                {rolloutTargetType === 'CANARY_PERCENT' && (
                  <div>
                    <label className="block text-xs font-medium text-zinc-400 mb-1">النسبة المئوية التجريبية (%)</label>
                    <input
                      type="number"
                      min={1}
                      max={100}
                      value={rolloutCanaryPercent}
                      onChange={(e) => setRolloutCanaryPercent(Number(e.target.value))}
                      className={`w-full ${inputClass}`}
                    />
                  </div>
                )}
              </div>

              <div className="flex justify-end pt-2">
                <Button variant="primary" type="submit" disabled={!canManageAppConfig || !rolloutTemplateId}>
                  <Play className="w-3.5 h-3.5 ml-1.5" />
                  بدء النشر الآن
                </Button>
              </div>
            </form>
          </div>

          {/* Past Rollouts Table */}
          <div className="space-y-3">
            <h4 className="text-xs font-semibold text-zinc-300">سجل حملات النشر التدريجي:</h4>
            <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
              <table className="w-full text-right text-sm">
                <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800">
                  <tr>
                    <th className="py-3 px-4">عنوان الحملة</th>
                    <th className="py-3 px-4">النوع</th>
                    <th className="py-3 px-4">الحالة</th>
                    <th className="py-3 px-4">العملاء المستهدفين</th>
                    <th className="py-3 px-4">تاريخ الإطلاق</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-zinc-800/60">
                  {rollouts.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-8 text-center">
                        <EmptyState title="لا توجد حملات نشر سابقة" />
                      </td>
                    </tr>
                  ) : (
                    rollouts.map((ro) => (
                      <tr key={ro.id} className="hover:bg-zinc-800/20 transition-colors">
                        <td className="py-3 px-4 font-medium text-zinc-200">{ro.title}</td>
                        <td className="py-3 px-4 text-xs font-mono text-zinc-400">{ro.targetType}</td>
                        <td className="py-3 px-4">
                          <span className="px-2.5 py-0.5 rounded text-xs bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                            {ro.status}
                          </span>
                        </td>
                        <td className="py-3 px-4 text-zinc-200 font-semibold">{ro.totalTenants} عميل</td>
                        <td className="py-3 px-4 text-xs text-zinc-400">{formatDateTime(ro.createdAt)}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ─── TAB 4: Version Diff Viewer ───────────────────────────────────────────── */}
      {activeTab === 'diff' && (
        <div className="space-y-4">
          <div className="bg-zinc-900/50 p-4 rounded-xl border border-zinc-800 flex flex-wrap items-center gap-4">
            <div className="flex items-center gap-2">
              <span className="text-xs text-zinc-400">مقارنة الإصدار:</span>
              <select
                value={diffVersionA}
                onChange={(e) => setDiffVersionA(Number(e.target.value))}
                className={inputClass}
              >
                {versions.map((v) => (
                  <option key={v.version} value={v.version}>
                    إصدار #{v.version}
                  </option>
                ))}
              </select>
            </div>

            <span className="text-zinc-500 font-bold">مقابل</span>

            <div className="flex items-center gap-2">
              <span className="text-xs text-zinc-400">الإصدار:</span>
              <select
                value={diffVersionB}
                onChange={(e) => setDiffVersionB(Number(e.target.value))}
                className={inputClass}
              >
                {versions.map((v) => (
                  <option key={v.version} value={v.version}>
                    إصدار #{v.version}
                  </option>
                ))}
              </select>
            </div>
          </div>

          <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
            <table className="w-full text-right text-xs">
              <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800 font-mono">
                <tr>
                  <th className="py-3 px-4">مفتاح التكوين (Key)</th>
                  <th className="py-3 px-4">إصدار #{diffVersionA}</th>
                  <th className="py-3 px-4">إصدار #{diffVersionB}</th>
                  <th className="py-3 px-4 text-center">الحالة</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/60 font-mono">
                {diffDisplay?.map((row) => (
                  <tr
                    key={row.key}
                    className={row.changed ? 'bg-amber-950/20 text-amber-200' : 'text-zinc-300'}
                  >
                    <td className="py-2.5 px-4 font-semibold">{row.key}</td>
                    <td className="py-2.5 px-4 max-w-xs truncate">{row.valA}</td>
                    <td className="py-2.5 px-4 max-w-xs truncate">{row.valB}</td>
                    <td className="py-2.5 px-4 text-center">
                      {row.changed ? (
                        <span className="px-2 py-0.5 rounded text-[10px] bg-amber-500/20 text-amber-300 border border-amber-500/30">
                          مُعدل
                        </span>
                      ) : (
                        <span className="text-zinc-600 text-[10px]">متطابق</span>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ─── TAB 5: Version History & Rollback ─────────────────────────────────────── */}
      {activeTab === 'history' && (
        <div className="space-y-3">
          <div className="text-xs text-zinc-400">
            سجل الإصدارات السابقة مع إمكانية الاسترجاع السريع وإعادة التوقيع بضغطة زر:
          </div>

          {versions.length === 0 ? (
            <EmptyState title="لا توجد إصدارات سابقة مسجلة لتكوين هذا العميل" />
          ) : (
            <div className="space-y-2">
              {versions.map((ver) => (
                <div
                  key={ver.id}
                  className="bg-zinc-950 p-3.5 rounded-lg border border-zinc-800 flex items-center justify-between text-xs"
                >
                  <div>
                    <div className="font-semibold text-zinc-200 flex items-center gap-2">
                      <span>إصدار #{ver.version}</span>
                      {ver.version === currentConfig?.version && (
                        <span className="text-emerald-400 font-normal">(النشط حالياً)</span>
                      )}
                      <span className="text-[10px] text-zinc-500 font-mono">توقيع: {ver.signature?.substring(0, 12)}...</span>
                    </div>
                    <div className="text-zinc-400 text-[11px] mt-0.5">{ver.changeSummary}</div>
                    <div className="text-zinc-500 text-[10px]">{formatDateTime(ver.createdAt)}</div>
                  </div>

                  {ver.version !== currentConfig?.version && (
                    <Button
                      variant="secondary"
                      size="sm"
                      onClick={() => handleRollback(ver.version)}
                      disabled={!canManageAppConfig}
                    >
                      <RotateCcw className="w-3.5 h-3.5 ml-1" />
                      استرجاع وتطبيق
                    </Button>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* ─── TAB 6: Client & Device Telemetry (ACK) ───────────────────────────────── */}
      {activeTab === 'telemetry' && (
        <div className="space-y-4">
          <div className="text-xs text-zinc-400">
            تأكيدات الاستلام والتطبيق الحية الواردة من أجهزة هذا العميل:
          </div>

          <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
            <table className="w-full text-right text-sm">
              <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800">
                <tr>
                  <th className="py-3 px-4">معرف الجهاز</th>
                  <th className="py-3 px-4">رقم الإصدار</th>
                  <th className="py-3 px-4">الحالة</th>
                  <th className="py-3 px-4">توقيت الاستلام</th>
                  <th className="py-3 px-4">ملاحظات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/60">
                {acks.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="py-8 text-center">
                      <EmptyState title="لا توجد تأكيدات استلام مسجلة حتى الآن" />
                    </td>
                  </tr>
                ) : (
                  acks.map((ack) => (
                    <tr key={ack.id} className="hover:bg-zinc-800/20 transition-colors">
                      <td className="py-3 px-4 font-mono text-xs text-zinc-300">
                        {ack.deviceId ? ack.deviceId.substring(0, 16) + '...' : 'الجهاز الرئيسي'}
                      </td>
                      <td className="py-3 px-4 font-semibold text-zinc-200">#{ack.version}</td>
                      <td className="py-3 px-4">
                        {ack.status === 'APPLIED' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                            تم التطبيق
                          </span>
                        )}
                        {ack.status === 'RECEIVED' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-blue-500/10 text-blue-400 border border-blue-500/20">
                            تم الاستلام
                          </span>
                        )}
                        {ack.status === 'FAILED' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-rose-500/10 text-rose-400 border border-rose-500/20">
                            فشل
                          </span>
                        )}
                      </td>
                      <td className="py-3 px-4 text-xs text-zinc-400">{formatDateTime(ack.acknowledgedAt)}</td>
                      <td className="py-3 px-4 text-xs text-zinc-400">{ack.errorMessage || '—'}</td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
};

