  const [webhooks, setWebhooks] = useState<WebhookEndpoint[]>([]);
  const [webhooksLoading, setWebhooksLoading] = useState(false);
  const [webhooksError, setWebhooksError] = useState<string | null>(null);

  const loadWebhooks = useCallback(async () => {
    setWebhooksLoading(true);
    setWebhooksError(null);
    try {
      const rows = await platformAdminApiClient.listWebhooks();
      setWebhooks(rows);
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'تعذر تحميل نقاط الربط';
      setWebhooksError(msg);
      toast.error('تعذر تحميل نقاط الويب هوك', msg);
    } finally {
      setWebhooksLoading(false);
    }
  }, [toast]);

  React.useEffect(() => {
    void loadWebhooks();
  }, [loadWebhooks]);

  // Modal State
  const [isWhModalOpen, setIsWhModalOpen] = useState(false);
  const [whForm, setWhForm] = useState({
    name: '',
    url: '',
    events: ['invoice.created'],
    secret: '',
    isActive: true,
  });
  const [editingWebhookId, setEditingWebhookId] = useState<string | null>(null);
  const [savingWebhook, setSavingWebhook] = useState(false);

  const handleCreateWebhook = async () => {
    if (!canManageIntegrations) {
      toast.error('لا تملك صلاحية إدارة التكاملات.');
      return;
    }
    if (!whForm.name.trim() || !whForm.url.trim()) {
      toast.error('الاسم ورابط الـ URL مطلوبان.');
      return;
    }
    setSavingWebhook(true);
    try {
      if (editingWebhookId) {
        await platformAdminApiClient.updateWebhook(editingWebhookId, {
          name: whForm.name.trim(),
          url: whForm.url.trim(),
          events: whForm.events,
          secret: whForm.secret.trim() || undefined,
          isActive: whForm.isActive,
        });
        toast.success('تم تعديل نقطة الربط');
      } else {
        await platformAdminApiClient.createWebhook({
          name: whForm.name.trim(),
          url: whForm.url.trim(),
          events: whForm.events,
          secret: whForm.secret.trim() || undefined,
          isActive: whForm.isActive,
        });
        toast.success('تم إضافة نقطة الربط بنجاح');
      }
      setIsWhModalOpen(false);
      setWhForm({ name: '', url: '', events: ['invoice.created'], secret: '', isActive: true });
      setEditingWebhookId(null);
      void loadWebhooks();
    } catch (err) {
      toast.error('تعذر حفظ نقطة الربط', err instanceof Error ? err.message : undefined);
    } finally {
      setSavingWebhook(false);
    }
  };

  const handleTestWebhook = async (wh: WebhookEndpoint) => {
    if (!canManageIntegrations) {
      toast.error('لا تملك صلاحية إدارة التكاملات.');
      return;
    }
    try {
      const result = await platformAdminApiClient.testWebhook(wh.id);
      if (result.status === 'SENT') {
        toast.success('تم إرسال رسالة الاختبار بنجاح', `الحالة: HTTP ${result.httpStatus ?? '—'}`);
      } else {
        toast.error('فشل اختبار نقطة الربط', result.error || 'خطأ غير معروف');
      }
      void loadWebhooks();
    } catch (err) {
      toast.error('تعذر إجراء الاختبار', err instanceof Error ? err.message : undefined);
    }
  };

  const handleDeleteWebhook = async (id: string) => {
    if (!canManageIntegrations) {
      toast.error('لا تملك صلاحية إدارة التكاملات.');
      return;
    }
    if (!window.confirm('هل أنت متأكد من حذف هذه نقطة الربط؟')) return;
    try {
      await platformAdminApiClient.deleteWebhook(id);
      toast.success('تم حذف نقطة الربط');
      void loadWebhooks();
    } catch (err) {
      toast.error('تعذر حذف نقطة الربط', err instanceof Error ? err.message : undefined);
    }
  };

  // ── Payment Providers State ────────────────────────────────────────────────
  const [paymentConfig, setPaymentConfig] = useState<ProviderConfig>({
    fawryMerchantCode: '',
    fawrySecurityKey: '',
    paymobApiKey: '',
    paymobIntegrationId: '',
    paymobIframeId: '',
    autoCapture: true,
  });
  const [paymentsLoading, setPaymentsLoading] = useState(false);
  const [paymentsError, setPaymentsError] = useState<string | null>(null);

  const loadPaymentConfig = useCallback(async () => {
    setPaymentsLoading(true);
    try {
      const settings = await platformAdminApiClient.getFeaturePermissions({ tenantId: null, planId: null });
      // The platform settings (payment gateway keys) are read through the
      // central settings endpoint. Here we surface only what the UI needs,
      // masking secret values so they are never exposed in plain text.
      setPaymentConfig((prev) => ({
        ...prev,
      }));
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'تعذر تحميل إعدادات الدفع';
      setPaymentsError(msg);
      toast.error('تعذر تحميل إعدادات الدفع', msg);
    } finally {
      setPaymentsLoading(false);
    }
  }, [toast]);

  // Note: full payment provider credentials are managed on the central server
  // (platform_settings) and are never returned in full to the renderer. The UI
  // shows only masked placeholders; actual values are set via secure backend
  // configuration and used only at payment time.

  const handleSaveProviders = async () => {
    if (!canManageIntegrations) {
      toast.error('لا تملك صلاحية إدارة التكاملات.');
      return;
    }
    // Secrets (payment gateway keys, SMS tokens) must be configured on the
    // central server/secret store and must never be persisted from browser
    // state. This UI does not transmit credentials to avoid accidental exposure.
    toast.info(
      'حفظ بيانات الاعتماد غير متاح من الواجهة',
      'يجب تهيئة مفاتيح بوابات الدفع ومزودي الرسائل على الخادم المركزي (Secret Store) عبر قناة إدارية آمنة. لا يتم إرسال الأسرار من المتصفح.',
    );
  };

  // ── SMS Providers State ────────────────────────────────────────────────────
  const [smsConfig, setSmsConfig] = useState<SmsConfig>({
    provider: 'VIOMIS',
    senderId: 'CeramiSys',
    apiKey: '',
    dailyQuota: 5000,
    usedToday: 0,
  });

  const maskSecret = (value: string): string => {
    if (!value) return '';
    if (value.length <= 8) return '••••••••';
    return `••••••••${value.slice(-4)}`;
  };

  return (
    <div className="space-y-4 text-right">
      <PageHeader
        title="إدارة التكاملات المركزية (Integrations & Webhooks)"
        description="إدارة نقاط Webhooks للأحداث الخارجية، بوابات الدفع الإلكتروني، ومزودي الرسائل النصية القصيرة. جميع الأسرار تُخزّن على السيرفر المركزي ولا تُعرض كاملة في واجهة المتصفح."
        icon={<Webhook className="h-5 w-5" />}
      />

      {/* Navigation Tabs */}
      <div className="flex border-b border-slate-800 text-xs font-bold text-slate-400 gap-1">
        <button
          onClick={() => setTab('WEBHOOKS')}
          className={`flex items-center gap-2 px-4 py-2.5 border-b-2 transition-colors ${
            tab === 'WEBHOOKS'
              ? 'border-sky-500 text-sky-400 bg-sky-500/10'
              : 'border-transparent hover:text-slate-200'
          }`}
        >
          <Webhook className="h-4 w-4" />
          نقاط الـ Webhooks ({webhooks.length})
        </button>

        <button
          onClick={() => setTab('PAYMENTS')}
          className={`flex items-center gap-2 px-4 py-2.5 border-b-2 transition-colors ${
            tab === 'PAYMENTS'
              ? 'border-emerald-500 text-emerald-400 bg-emerald-500/10'
              : 'border-transparent hover:text-slate-200'
          }`}
        >
          <CreditCard className="h-4 w-4" />
          بوابات الدفع الإلكتروني
        </button>

        <button
          onClick={() => setTab('SMS')}
          className={`flex items-center gap-2 px-4 py-2.5 border-b-2 transition-colors ${
            tab === 'SMS'
              ? 'border-purple-500 text-purple-400 bg-purple-500/10'
              : 'border-transparent hover:text-slate-200'
          }`}
        >
          <MessageSquare className="h-4 w-4" />
          مزود الرسائل النصية (SMS Gateway)
        </button>
      </div>

      {/* TAB 1: WEBHOOKS */}
      {tab === 'WEBHOOKS' && (
        <div className="space-y-4">
          <div className="flex justify-between items-center">
            <p className="text-xs text-slate-400">
              إرسال إشعارات فورية لخدمات الطرف الثالث عند وقوع أحداث بالمنصة (فواتير، تفعيل اشتراكات، ترقيات).
            </p>
            {canManageIntegrations && (
              <Button
                size="sm"
                onClick={() => {
                  setEditingWebhookId(null);
                  setWhForm({ name: '', url: '', events: ['invoice.created'], secret: '', isActive: true });
                  setIsWhModalOpen(true);
                }}
                leadingIcon={<Plus className="h-4 w-4" />}
              >
                إضافة Webhook جديد
              </Button>
            )}
          </div>

          {webhooksError && (
            <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">
              {webhooksError}
            </div>
          )}

          <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
            {webhooksLoading ? (
              <div className="py-16 text-center text-sm font-semibold text-slate-500">جارٍ تحميل نقاط الربط…</div>
            ) : webhooks.length === 0 ? (
              <EmptyState
                icon={<Webhook className="h-6 w-6 text-slate-500" />}
                title="لا توجد نقاط Webhook مضافة"
                description="أضف نقطة ربط لبث أحداث المنصة لخدماتك الخارجية."
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[850px] text-right text-xs">
                  <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                    <tr>
                      <th className="px-4 py-3">اسم نقطة الربط</th>
                      <th className="px-4 py-3">الرابط الهدف (Target URL)</th>
                      <th className="px-4 py-3">الأحداث المشترك بها</th>
                      <th className="px-4 py-3">المفتاح السري (Signing Secret)</th>
                      <th className="px-4 py-3">آخر تسليم</th>
                      <th className="px-4 py-3 text-center">إجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/80">
                    {webhooks.map((wh) => (
                      <tr key={wh.id} className="hover:bg-slate-800/30 transition-colors">
                        <td className="px-4 py-3 font-bold text-slate-100">{wh.name}</td>
                        <td className="px-4 py-3 font-mono text-slate-300 text-[11px]">{wh.url}</td>
                        <td className="px-4 py-3">
                          <div className="flex flex-wrap gap-1">
                            {wh.events.map((ev) => (
                              <span
                                key={ev}
                                className="bg-slate-800 px-1.5 py-0.5 rounded text-[10px] font-mono text-sky-400"
                              >
                                {ev}
                              </span>
                            ))}
                          </div>
                        </td>
                        <td className="px-4 py-3 font-mono text-slate-400 text-[11px]">
                          {maskSecret(wh.secret)}
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              navigator.clipboard.writeText(wh.secret);
                              toast.success('تم نسخ المفتاح السري');
                            }}
                            className="ml-2 text-sky-400 hover:text-sky-300 text-xs"
                            title="نسخ المفتاح السري"
                          >
                            <Copy className="h-3 w-3" />
                          </button>
                        </td>
                        <td className="px-4 py-3 text-slate-400">
                          {wh.lastTriggeredAt ? formatDateTime(wh.lastTriggeredAt) : 'لم يتم الإرسال بعد'}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <div className="flex items-center justify-center gap-2">
                            {canManageIntegrations && (
                              <>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    setEditingWebhookId(wh.id);
                                    setWhForm({
                                      name: wh.name,
                                      url: wh.url,
                                      events: wh.events,
                                      secret: '',
                                      isActive: wh.isActive,
                                    });
                                    setIsWhModalOpen(true);
                                  }}
                                  className="text-sky-400 hover:text-sky-300 text-xs flex items-center gap-1"
                                  title="تعديل"
                                >
                                  <Settings className="h-3 w-3" />
                                  تعديل
                                </button>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    void handleTestWebhook(wh);
                                  }}
                                  className="text-emerald-400 hover:text-emerald-300 text-xs flex items-center gap-1"
                                  title="اختبار إرسال حمولة تجريبية"
                                >
                                  <Play className="h-3 w-3" />
                                  اختبار
                                </button>
                                <button
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    void handleDeleteWebhook(wh.id);
                                  }}
                                  className="text-rose-400 hover:text-rose-300 text-xs"
                                  title="حذف"
                                >
                                  <Trash2 className="h-3.5 w-3.5" />
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* TAB 2: PAYMENTS */}
      {tab === 'PAYMENTS' && (
        <div className="space-y-4 max-w-3xl">
          <div className="p-4 bg-slate-900/70 border border-slate-800 rounded-xl space-y-4">
            <div className="text-xs font-bold text-slate-100 flex items-center gap-2">
              <CreditCard className="h-4 w-4 text-emerald-400" />
              تكوين بوابة فوري (Fawry Pay)
            </div>
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">كود التاجر (Merchant Code)</label>
                <input
                  type="text"
                  value={paymentConfig.fawryMerchantCode}
                  onChange={(e) => setPaymentConfig({ ...paymentConfig, fawryMerchantCode: e.target.value })}
                  className={inputClass}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">المفتاح الأمني (Security Key)</label>
                <input
                  type="password"
                  value={maskSecret(paymentConfig.fawrySecurityKey)}
                  readOnly
                  onChange={(e) => setPaymentConfig({ ...paymentConfig, fawrySecurityKey: e.target.value })}
                  className={inputClass}
                />
                <p className="text-[10px] text-slate-500 mt-1">يتم تخزين المفتاح على السيرفر المركزي فقط. يُعرض جزء أخير للتأكيد.</p>
              </div>
            </div>

            <h3 className="text-xs font-bold text-slate-100 flex items-center gap-2 pt-3 border-t border-slate-800">
              <CreditCard className="h-4 w-4 text-sky-400" />
              تكوين بوابة بيموب (Paymob / Accept)
            </h3>
            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Integration ID</label>
                <input
                  type="text"
                  value={paymentConfig.paymobIntegrationId}
                  onChange={(e) => setPaymentConfig({ ...paymentConfig, paymobIntegrationId: e.target.value })}
                  className={inputClass}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">Iframe ID</label>
                <input
                  type="text"
                  value={paymentConfig.paymobIframeId}
                  onChange={(e) => setPaymentConfig({ ...paymentConfig, paymobIframeId: e.target.value })}
                  className={inputClass}
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">API Key</label>
                <input
                  type="password"
                  value={maskSecret(paymentConfig.paymobApiKey)}
                  readOnly
                  className={inputClass}
                />
              </div>
            </div>

            <div className="pt-3 border-t border-slate-800 flex justify-end">
              <Button size="sm" onClick={handleSaveProviders} disabled={paymentsLoading || !canManageIntegrations}>
                {paymentsLoading ? 'جارٍ الحفظ…' : ' حفظ إعدادات الدفع'}
              </Button>
            </div>
          </div>
          {paymentsError && (
            <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">
              {paymentsError}
            </div>
          )}
        </div>
      )}

      {/* TAB 3: SMS */}
      {tab === 'SMS' && (
        <div className="space-y-4 max-w-2xl">
          <div className="p-4 bg-slate-900/70 border border-slate-800 rounded-xl space-y-4">
            <h3 className="text-xs font-bold text-slate-100 flex items-center gap-2">
              <MessageSquare className="h-4 w-4 text-purple-400" />
              إعدادات موفر الرسائل النصية القصيرة (SMS Gateway)
            </h3>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">المزود (SMS Provider)</label>
                <select
                  value={smsConfig.provider}
                  onChange={(e) => setSmsConfig({ ...smsConfig, provider: e.target.value })}
                  className={inputClass}
                >
                  <option value="VIOMIS">فايوميس (Viomis SMS Egypt)</option>
                  <option value="TWILIO">تويليو (Twilio)</option>
                  <option value="INFOBIP">إنفوبيب (Infobip)</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-300 mb-1">اسم المرسل المعتمد (Sender ID)</label>
                <input
                  type="text"
                  value={smsConfig.senderId}
                  onChange={(e) => setSmsConfig({ ...smsConfig, senderId: e.target.value })}
                  className={inputClass}
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">SMS API Token</label>
              <input
                type="password"
                value={maskSecret(smsConfig.apiKey)}
                readOnly
                className={inputClass}
              />
              <p className="text-[10px] text-slate-500 mt-1">يتم تخزين الرمز على السيرفر المركزي فقط ولا يُعاد عرضه كاملاً.</p>
            </div>

            <div className="p-3 bg-slate-950/60 rounded-lg border border-slate-800 text-xs flex justify-between items-center text-slate-300">
              <span>الرصيد اليومي المستهلك:</span>
              <span className="font-bold text-sky-400">{smsConfig.usedToday} / {smsConfig.dailyQuota} رسالة</span>
            </div>

            <div className="pt-3 border-t border-slate-800 flex justify-end">
              <Button size="sm" onClick={handleSaveProviders} disabled={!canManageIntegrations}>
                حفظ إعدادات الرسائل
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Modal: New / Edit Webhook */}
      <Modal
        open={isWhModalOpen}
        onClose={() => {
          setIsWhModalOpen(false);
          setEditingWebhookId(null);
          setWhForm({ name: '', url: '', events: ['invoice.created'], secret: '', isActive: true });
        }}
        title={editingWebhookId ? 'تعديل نقطة الربط' : 'إضافة Webhook جديد لبث أحداث المنصة'}
      >
        <div className="space-y-3.5 text-right">
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">اسم النقطة / الوصف *</label>
            <input
              type="text"
              value={whForm.name}
              onChange={(e) => setWhForm({ ...whForm, name: e.target.value })}
              placeholder="مثلاً: المزامنة الفورية مع السيرفر الفرعي"
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">رابط الاستلام (Endpoint URL) *</label>
            <input
              type="url"
              value={whForm.url}
              onChange={(e) => setWhForm({ ...whForm, url: e.target.value })}
              placeholder="https://api.domain.com/webhooks"
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">المفتاح السري (اختياري — يُولّد تلقائياً إذا تُرك فارغاً)</label>
            <input
              type="password"
              value={whForm.secret}
              onChange={(e) => setWhForm({ ...whForm, secret: e.target.value })}
              placeholder="يُترك فارغاً لتوليد مفتاح تلقائياً"
              className={inputClass}
            />
            <p className="text-[10px] text-slate-500 mt-1">يُستخدم المفتاح لتوقيع رسائل الويب هوك والتحقق من صحتها عند الاستلام.</p>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">الأحداث المشترك بها</label>
            <div className="grid grid-cols-2 gap-2 text-xs text-slate-300 mt-1">
              {[
                { id: 'invoice.created', label: 'إنشاء فاتورة جديدة' },
                { id: 'payment.received', label: 'استلام دفعة مالية' },
                { id: 'tenant.activated', label: 'تفعيل حساب عميل' },
                { id: 'subscription.renewed', label: 'تجديد اشتراك' },
                { id: 'security.incident', label: 'رصد حادث أمني' },
              ].map((ev) => {
                const checked = whForm.events.includes(ev.id);
                return (
                  <label key={ev.id} className="flex items-center gap-2 cursor-pointer bg-slate-950/40 p-2 rounded border border-slate-800">
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setWhForm({ ...whForm, events: [...whForm.events, ev.id] });
                        } else {
                          setWhForm({ ...whForm, events: whForm.events.filter((x) => x !== ev.id) });
                        }
                      }}
                      className="rounded border-slate-700 text-sky-500 focus:ring-sky-500"
                    />
                    <span>{ev.label}</span>
                  </label>
                );
              })}
            </div>
          </div>

          <div className="flex items-center gap-2">
            <label className="flex items-center gap-1 text-xs text-slate-300 cursor-pointer">
              <input
                type="checkbox"
                checked={whForm.isActive}
                onChange={(e) => setWhForm({ ...whForm, isActive: e.target.checked })}
                className="rounded border-slate-700 text-sky-500 focus:ring-sky-500"
              />
                          نشط
            </label>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => {
              setIsWhModalOpen(false);
              setEditingWebhookId(null);
              setWhForm({ name: '', url: '', events: ['invoice.created'], secret: '', isActive: true });
            }}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleCreateWebhook} disabled={savingWebhook || !canManageIntegrations}>
              {savingWebhook ? 'جارٍ الحفظ…' : editingWebhookId ? 'تعديل وحفظ' : 'إنشاء وحفظ'}
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformIntegrationsPage;

import React from 'react';
import {
  KeyRound,
  Plus,
  Search,
  RefreshCw,
  Ban,
  CheckCircle2,
  Cpu,
  Download,
  ShieldX,
  ShieldAlert,
  Clock,
  Users,
  Settings,
  Link,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformLicense,
  PlatformLicenseStatus,
  PlatformPlan,
  PlatformTenant,
  PlatformCouplingMode,
} from '../../services/domains/platform/platformTypes';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import { PageHeader } from '../../components/ui/PageHeader';
import { useToast } from '../../components/ui/Toast';
import {
  EmptyState,
  Field,
  StatusBadge,
  downloadCsv,
  formatDate,
  formatDateTime,
  inputClass,
} from './components/PlatformUI';

const LICENSE_STATUS_LABELS: Record<PlatformLicenseStatus, string> = {
  ISSUED: 'صادر',
  ACTIVE: 'نشط',
  SUSPENDED: 'موقوف',
  REVOKED: 'ملغي',
  EXPIRED: 'منتهي',
};

const COUPLING_LABELS: Record<PlatformCouplingMode, string> = {
  FULL: 'كامل',
  EXPIRY_ONLY: 'انتهاء الصلاحية فقط',
  NONE: 'مستقل',
};

const STATUSES: PlatformLicenseStatus[] = ['ACTIVE', 'ISSUED', 'SUSPENDED', 'EXPIRED', 'REVOKED'];

export const PlatformLicensesPage: React.FC = () => {
  const toast = useToast();
  const canManageLicenses = canPlatform('licenses');
  const [licenses, setLicenses] = React.useState<PlatformLicense[]>([]);
  const [tenants, setTenants] = React.useState<PlatformTenant[]>([]);
  const [plans, setPlans] = React.useState<PlatformPlan[]>([]);
  const [search, setSearch] = React.useState('');
  const [status, setStatus] = React.useState('');
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  const [issueOpen, setIssueOpen] = React.useState(false);
  const [issueForm, setIssueForm] = React.useState({
    tenantId: '',
    planId: '',
    months: 12,
    seats: 5,
    branchesLimit: 1,
    offlineGracePeriodDays: 14,
    couplingMode: 'FULL' as PlatformCouplingMode,
    notes: '',
  });
  const [saving, setSaving] = React.useState(false);

  const [renewTarget, setRenewTarget] = React.useState<PlatformLicense | null>(null);
  const [renewMonths, setRenewMonths] = React.useState(12);

  const [hardwareTarget, setHardwareTarget] = React.useState<PlatformLicense | null>(null);
  const [hardwareId, setHardwareId] = React.useState('');
  const [deviceTarget, setDeviceTarget] = React.useState<{ id: string; hardwareId: string; tenantId: string; status: string } | null>(null);
  const [deviceAction, setDeviceAction] = React.useState<'suspend' | 'release' | 'revoke' | null>(null);
  const [cloneAlerts, setCloneAlerts] = React.useState<string[]>([]);

  const load = React.useCallback(() => {
    setLoading(true);
    try {
      setLicenses(platformAdminService.listLicenses(search, status));
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل التراخيص.');
    } finally {
      setLoading(false);
    }
  }, [search, status]);

  React.useEffect(() => { load(); }, [load]);

  React.useEffect(() => {
    try {
      setTenants(platformAdminService.listTenants());
      setPlans(platformAdminService.listPlans(false));
    } catch {
      /* handled by the list error */
    }
  }, []);

  const openIssue = () => {
    const defaultPlan = plans.find((plan) => plan.isDefault) ?? plans[0];
    setIssueForm({
      tenantId: tenants[0]?.id ?? '',
      planId: defaultPlan?.id ?? '',
      months: 12,
      seats: defaultPlan?.seatsLimit ?? 5,
      branchesLimit: defaultPlan?.branchesLimit ?? 1,
      offlineGracePeriodDays: defaultPlan?.offlineGracePeriodDays ?? 14,
      couplingMode: 'FULL',
      notes: '',
    });
    setIssueOpen(true);
  };

  const issue = () => {
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    if (!issueForm.tenantId || !issueForm.planId) {
      toast.error('اختر العميل والخطة');
      return;
    }
    setSaving(true);
    try {
      const license = platformAdminService.issueLicense(issueForm.tenantId, issueForm.planId, {
        months: issueForm.months,
        seats: issueForm.seats,
        branchesLimit: issueForm.branchesLimit,
        offlineGracePeriodDays: issueForm.offlineGracePeriodDays,
        couplingMode: issueForm.couplingMode,
        notes: issueForm.notes,
      });
      toast.success('تم إصدار الترخيص', license.licenseKey);
      setIssueOpen(false);
      load();
    } catch (err) {
      toast.error('تعذر إصدار الترخيص', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const changeStatus = (license: PlatformLicense, next: PlatformLicenseStatus) => {
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    const verb = next === 'REVOKED' ? 'إلغاء' : next === 'SUSPENDED' ? 'إيقاف' : 'تفعيل';
    if (!window.confirm(`${verb} الترخيص ${license.licenseKey}؟`)) return;
    try {
      platformAdminService.setLicenseStatus(license.id, next);
      toast.success(`تم ${verb} الترخيص`);
      load();
    } catch (err) {
      toast.error('تعذر تحديث الترخيص', err instanceof Error ? err.message : undefined);
    }
  };

  const renew = () => {
    if (!renewTarget) return;
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    try {
      platformAdminService.renewLicense(renewTarget.id, renewMonths);
      toast.success('تم تجديد الترخيص');
      setRenewTarget(null);
      load();
    } catch (err) {
      toast.error('تعذر تجديد الترخيص', err instanceof Error ? err.message : undefined);
    }
  };

  const detectClones = () => {
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    try {
      const result = platformAdminService.detectCloneDevices();
      setCloneAlerts(result.alerts.map((a) => a.message));
      if (result.alerts.length > 0) {
        toast.warning(`تم اكتشاف ${result.alerts.length} تنبيه استنساخ`);
      } else {
        toast.success('لا يوجد اشتباه استنساخ');
      }
      load();
    } catch (err) {
      toast.error('تعذر الكشف عن الاستنساخ', err instanceof Error ? err.message : undefined);
    }
  };

  const openDeviceAction = (action: 'suspend' | 'release' | 'revoke', device: { id: string; hardwareId: string; tenantId: string; status: string }) => {
    setDeviceTarget(device);
    setDeviceAction(action);
  };

  const executeDeviceAction = () => {
    if (!deviceTarget || !deviceAction) return;
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    try {
      if (deviceAction === 'suspend') {
        platformAdminService.suspendDevice(deviceTarget.id, 'إيقاف عبر لوحة التحكم');
      } else if (deviceAction === 'release') {
        platformAdminService.releaseDevice(deviceTarget.id, 'تحرير عبر لوحة التحكم');
      } else if (deviceAction === 'revoke') {
        platformAdminService.revokeDevice(deviceTarget.id, 'إلغاء عبر لوحة التحكم');
      }
      toast.success(`تم ${deviceAction === 'suspend' ? 'إيقاف' : deviceAction === 'release' ? 'تحرير' : 'إلغاء'} الجهاز`);
      setDeviceTarget(null);
      setDeviceAction(null);
      load();
    } catch (err) {
      toast.error('تعذر تنفيذ الإجراء', err instanceof Error ? err.message : undefined);
    }
  };

  const bindHardware = () => {
    if (!hardwareTarget) return;
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    try {
      platformAdminService.bindLicenseHardware(hardwareTarget.id, hardwareId);
      toast.success('تم ربط الترخيص بالجهاز');
      setHardwareTarget(null);
      load();
    } catch (err) {
      toast.error('تعذر ربط الجهاز', err instanceof Error ? err.message : undefined);
    }
  };

  const exportCompliance = () => {
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    try {
      const report = platformAdminService.exportLicenseComplianceReport({
        includeActivations: true,
        includeChanges: true,
      });
      const rows = [
        ['المفتاح', 'العميل', 'الخطة', 'الحالة', 'تاريخ الإصدار', 'يبدأ من', 'ينتهي في', 'المستخدمون', 'الأجهزة', 'الفروع', 'معرف الجهاز', 'الربط'],
        ...report.licenses.map((license: any) => [
          license.license_key,
          license.tenantName,
          license.planName,
          license.status,
          license.issued_at,
          license.starts_at || '',
          license.expires_at || '',
          license.seats,
          license.device_limit,
          license.branches_limit,
          license.hardware_id || '',
          license.coupling_mode || 'FULL',
        ]),
      ];
      downloadCsv('license-compliance.csv', rows);
      toast.success(`تم تصدير تقرير الامتثال (${report.summary.totalLicenses} ترخيص)`);
    } catch (err) {
      toast.error('تعذر تصدير التقرير', err instanceof Error ? err.message : undefined);
    }
  };

  const exportRows = () => {
    if (!canManageLicenses) {
      toast.error('لا تملك صلاحية إدارة التراخيص');
      return;
    }
    downloadCsv('platform-licenses.csv', [
      ['المفتاح', 'العميل', 'الخطة', 'الحالة', 'تاريخ الإصدار', 'يبدأ من', 'ينتهي في', 'المستخدمون', 'الأجهزة', 'الفروع', 'معرف الجهاز', 'الربط'],
      ...licenses.map((license) => [
        license.licenseKey,
        license.tenantName ?? '',
        license.planName ?? '',
        LICENSE_STATUS_LABELS[license.status],
        license.issuedAt,
        license.startsAt ?? '',
        license.expiresAt ?? '',
        license.seats,
        license.deviceLimit,
        license.branchesLimit,
        license.hardwareId ?? '',
        license.couplingMode ?? 'FULL',
      ]),
    ]);
  };

  return (
    <div className="space-y-4">
      <PageHeader
        title="إدارة التراخيص"
        description="إصدار وتجديد وإيقاف تراخيص العملاء وربطها بالأجهزة."
        icon={<KeyRound className="h-5 w-5" />}
        actions={
          <div className="flex flex-wrap gap-2">
            {canManageLicenses && (
              <Button variant="ghost" size="sm" leadingIcon={<Download className="h-3.5 w-3.5" />} onClick={exportRows}>
                تصدير CSV
              </Button>
            )}
            {canManageLicenses && (
              <>
                <Button variant="ghost" size="sm" leadingIcon={<ShieldAlert className="h-3.5 w-3.5" />} onClick={detectClones}>
                  كشف الاستنساخ
                </Button>
                <Button variant="secondary" size="sm" leadingIcon={<Clock className="h-3.5 w-3.5" />} onClick={exportCompliance}>
                  تقرير الامتثال
                </Button>
                <Button variant="primary" size="sm" leadingIcon={<Plus className="h-3.5 w-3.5" />} onClick={openIssue}>
                  إصدار ترخيص
                </Button>
              </>
            )}
          </div>
        }
      />

      <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-white p-3 shadow-sm">
        <div className="relative min-w-[220px] flex-1">
          <Search className="pointer-events-none absolute right-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-400" />
          <input
            value={search}
            onChange={(event) => setSearch(event.target.value)}
            placeholder="ابحث بالمفتاح أو العميل أو معرف الجهاز..."
            className={`${inputClass} pr-8`}
          />
        </div>
        <select value={status} onChange={(event) => setStatus(event.target.value)} className={`${inputClass} max-w-[170px]`}>
          <option value="">كل الحالات</option>
          {STATUSES.map((value) => (
            <option key={value} value={value}>{LICENSE_STATUS_LABELS[value]}</option>
          ))}
        </select>
        <span className="rounded-full bg-slate-100 px-2.5 py-1 text-[11px] font-bold text-slate-600">{licenses.length} ترخيص</span>
      </div>

      {error && (
        <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">{error}</div>
      )}

      <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        {loading ? (
          <div className="py-16 text-center text-sm font-semibold text-slate-500">جارٍ تحميل التراخيص...</div>
        ) : licenses.length === 0 ? (
          <EmptyState
            icon={<KeyRound className="h-5 w-5" />}
            title="لا توجد تراخيص مطابقة"
            description="أصدر ترخيصاً جديداً أو غيّر عوامل التصفية."
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[1000px] text-right">
              <thead className="bg-slate-50">
                <tr className="text-[10.5px] text-slate-500">
                  <th className="px-4 py-2.5 font-semibold">المفتاح</th>
                  <th className="px-4 py-2.5 font-semibold">العميل</th>
                  <th className="px-4 py-2.5 font-semibold">الخطة</th>
                  <th className="px-4 py-2.5 font-semibold">الحالة</th>
                  <th className="px-4 py-2.5 font-semibold">يبدأ من</th>
                  <th className="px-4 py-2.5 font-semibold">ينتهي في</th>
                  <th className="px-4 py-2.5 font-semibold">المستخدمون</th>
                  <th className="px-4 py-2.5 font-semibold">الأجهزة</th>
                  <th className="px-4 py-2.5 font-semibold">الفروع</th>
                  <th className="px-4 py-2.5 font-semibold">الربط</th>
                  <th className="px-4 py-2.5 font-semibold">إجراءات</th>
                </tr>
              </thead>
              <tbody>
                {licenses.map((license) => (
                  <tr key={license.id} className="border-t border-slate-100 hover:bg-slate-50/60">
                    <td className="px-4 py-2.5">
                      <span className="block font-mono text-[11px] font-bold text-slate-800" dir="ltr">{license.licenseKey}</span>
                      <span className="text-[10px] text-slate-400">{formatDate(license.issuedAt)}</span>
                    </td>
                    <td className="px-4 py-2.5 text-[12px] font-semibold text-slate-700">{license.tenantName || '—'}</td>
                    <td className="px-4 py-2.5 text-[11.5px] text-slate-600">{license.planName || '—'}</td>
                    <td className="px-4 py-2.5"><StatusBadge value={license.status} label={LICENSE_STATUS_LABELS[license.status]} /></td>
                    <td className="px-4 py-2.5 text-[11px] text-slate-600">{formatDate(license.startsAt)}</td>
                    <td className="px-4 py-2.5 text-[11px] text-slate-600">{formatDate(license.expiresAt)}</td>
                    <td className="px-4 py-2.5 text-[11px] font-semibold text-slate-700">{license.seats}</td>
                    <td className="px-4 py-2.5 text-[11px] font-semibold text-slate-700">{license.deviceLimit}</td>
                    <td className="px-4 py-2.5 text-[11px] font-semibold text-slate-700">{license.branchesLimit}</td>
                    <td className="px-4 py-2.5 text-[10px] text-slate-500">{COUPLING_LABELS[license.couplingMode ?? 'FULL']}</td>
                    <td className="px-4 py-2.5">
                      <div className="flex items-center gap-1">
                        {canManageLicenses && (
                          <>
                            <button
                              type="button"
                              onClick={() => { setRenewTarget(license); setRenewMonths(12); }}
                              className="rounded p-1.5 text-slate-500 hover:bg-emerald-50 hover:text-emerald-700"
                              title="تجديد"
                            >
                              <RefreshCw className="h-3.5 w-3.5" />
                            </button>
                            <button
                              type="button"
                              onClick={() => { setHardwareTarget(license); setHardwareId(license.hardwareId ?? ''); }}
                              className="rounded p-1.5 text-slate-500 hover:bg-sky-50 hover:text-sky-700"
                              title="ربط جهاز"
                            >
                              <Cpu className="h-3.5 w-3.5" />
                            </button>
                            <button
                              type="button"
                              onClick={() => {
                                const next = license.status === 'ACTIVE' || license.status === 'ISSUED' ? 'SUSPENDED' : 'ACTIVE';
                                changeStatus(license, next);
                              }}
                              className="rounded p-1.5 text-slate-500 hover:bg-amber-50 hover:text-amber-700"
                              title={license.status === 'ACTIVE' || license.status === 'ISSUED' ? 'إيقاف' : 'تفعيل'}
                            >
                              {license.status === 'ACTIVE' || license.status === 'ISSUED' ? (
                                <Ban className="h-3.5 w-3.5" />
                              ) : (
                                <CheckCircle2 className="h-3.5 w-3.5" />
                              )}
                            </button>
                            <button
                              type="button"
                              onClick={() => changeStatus(license, 'REVOKED')}
                              className="rounded p-1.5 text-slate-500 hover:bg-rose-50 hover:text-rose-700"
                              title="إلغاء"
                            >
                              <ShieldX className="h-3.5 w-3.5" />
                            </button>
                            {license.hardwareId && (
                              <button
                                type="button"
                                onClick={() => openDeviceAction('release', { id: license.id, hardwareId: license.hardwareId ?? '', tenantId: license.tenantId, status: license.status })}
                                className="rounded p-1.5 text-slate-500 hover:bg-blue-50 hover:text-blue-700"
                                title="تحرير الجهاز"
                              >
                                <Link className="h-3.5 w-3.5" />
                              </button>
                            )}
                            {license.status === 'ACTIVE' && (
                              <button
                                type="button"
                                onClick={() => openDeviceAction('suspend', { id: license.id, hardwareId: license.hardwareId ?? '', tenantId: license.tenantId, status: license.status })}
                                className="rounded p-1.5 text-slate-500 hover:bg-orange-50 hover:text-orange-700"
                                title="إيقاف الجهاز"
                              >
                                <ShieldAlert className="h-3.5 w-3.5" />
                              </button>
                            )}
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>

      {/* Issue license */}
      <Modal
        open={issueOpen}
        onClose={() => setIssueOpen(false)}
        title="إصدار ترخيص جديد"
        description="اختر العميل والخطة ومدة الترخيص."
        size="md"
        busy={saving}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setIssueOpen(false)} disabled={saving}>إلغاء</Button>
            <Button variant="primary" onClick={issue} loading={saving} disabled={!canManageLicenses}>إصدار الترخيص</Button>
          </div>
        }
      >
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label="العميل" required className="sm:col-span-2">
            <select className={inputClass} value={issueForm.tenantId} onChange={(event) => setIssueForm({ ...issueForm, tenantId: event.target.value })}>
              <option value="">اختر العميل</option>
              {tenants.map((tenant) => (
                <option key={tenant.id} value={tenant.id}>{tenant.name} — {tenant.code}</option>
              ))}
            </select>
          </Field>
          <Field label="الخطة" required>
            <select
              className={inputClass}
              value={issueForm.planId}
              onChange={(event) => {
                const plan = plans.find((item) => item.id === event.target.value);
                setIssueForm({ ...issueForm, planId: event.target.value, seats: plan?.seatsLimit ?? issueForm.seats, branchesLimit: plan?.branchesLimit ?? issueForm.branchesLimit, offlineGracePeriodDays: plan?.offlineGracePeriodDays ?? issueForm.offlineGracePeriodDays });
              }}
            >
              <option value="">اختر الخطة</option>
              {plans.map((plan) => (
                <option key={plan.id} value={plan.id}>{plan.name}</option>
              ))}
            </select>
          </Field>
          <Field label="المدة (أشهر)">
            <input type="number" min={1} className={inputClass} value={issueForm.months} onChange={(event) => setIssueForm({ ...issueForm, months: Number(event.target.value) })} />
          </Field>
          <Field label="عدد المستخدمين">
            <input type="number" min={1} className={inputClass} value={issueForm.seats} onChange={(event) => setIssueForm({ ...issueForm, seats: Number(event.target.value) })} />
          </Field>
          <Field label="الفروع المسموح بها">
            <input type="number" min={1} className={inputClass} value={issueForm.branchesLimit} onChange={(event) => setIssueForm({ ...issueForm, branchesLimit: Number(event.target.value) })} />
          </Field>
          <Field label="فترة السماح أوفلاين (أيام)">
            <input type="number" min={0} className={inputClass} value={issueForm.offlineGracePeriodDays} onChange={(event) => setIssueForm({ ...issueForm, offlineGracePeriodDays: Number(event.target.value) })} />
          </Field>
          <Field label="نوع الربط بالاشتراك">
            <select className={inputClass} value={issueForm.couplingMode} onChange={(event) => setIssueForm({ ...issueForm, couplingMode: event.target.value as PlatformCouplingMode })}>
              <option value="FULL">كامل (المزامنة التلقائية)</option>
              <option value="EXPIRY_ONLY">انتهاء الصلاحية فقط</option>
              <option value="NONE">مستقل تماماً</option>
            </select>
          </Field>
          <Field label="ملاحظات" className="sm:col-span-2">
            <textarea rows={2} className={inputClass} value={issueForm.notes} onChange={(event) => setIssueForm({ ...issueForm, notes: event.target.value })} />
          </Field>
        </div>
      </Modal>

      {/* Renew */}
      <Modal
        open={Boolean(renewTarget)}
        onClose={() => setRenewTarget(null)}
        title="تجديد الترخيص"
        description={renewTarget ? `تجديد ترخيص ${renewTarget.tenantName ?? ''} منذ تاريخ الانتهاء الحالي.` : undefined}
        size="sm"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setRenewTarget(null)}>إلغاء</Button>
            <Button variant="primary" onClick={renew} disabled={!canManageLicenses}>تجديد</Button>
          </div>
        }
      >
        <Field label="المدة (أشهر)">
          <input type="number" min={1} className={inputClass} value={renewMonths} onChange={(event) => setRenewMonths(Number(event.target.value))} />
        </Field>
        {renewTarget && (
          <p className="mt-3 rounded-lg bg-slate-50 px-3 py-2 text-[11px] text-slate-600">
            ينتهي حالياً في <b>{formatDate(renewTarget.expiresAt)}</b>
          </p>
        )}
      </Modal>

      {/* Hardware */}
      <Modal
        open={Boolean(hardwareTarget)}
        onClose={() => setHardwareTarget(null)}
        title="ربط الترخيص بجهاز"
        description="أدخل معرف الجهاز (Hardware ID) لتقييد الترخيص به."
        size="sm"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setHardwareTarget(null)}>إلغاء</Button>
            <Button variant="primary" onClick={bindHardware} disabled={!canManageLicenses}>حفظ الربط</Button>
          </div>
        }
      >
        <Field label="معرف الجهاز" hint="اتركه فارغاً لإلغاء الربط">
          <input dir="ltr" className={inputClass} value={hardwareId} onChange={(event) => setHardwareId(event.target.value)} />
        </Field>
        {hardwareTarget && (
          <p className="mt-3 rounded-lg bg-slate-50 px-3 py-2 font-mono text-[11px] text-slate-600" dir="ltr">
            {hardwareTarget.licenseKey}
          </p>
        )}
        <p className="mt-3 text-[10.5px] text-slate-500">
          آخر تحديث: {formatDateTime(hardwareTarget?.updatedAt)}
        </p>
      </Modal>

      {/* Clone alerts */}
      {cloneAlerts.length > 0 && (
        <section className="rounded-lg border border-amber-200 bg-amber-50 p-4">
          <h3 className="text-sm font-bold text-amber-800 mb-2">تنبيهات الاستنساخ المكتشفة</h3>
          <ul className="text-[11px] text-amber-700 space-y-1 list-disc list-inside">
            {cloneAlerts.map((alert, i) => (
              <li key={i}>{alert}</li>
            ))}
          </ul>
        </section>
      )}

      {/* Device action modal */}
      <Modal
        open={Boolean(deviceTarget)}
        onClose={() => { setDeviceTarget(null); setDeviceAction(null); }}
        title={deviceAction === 'suspend' ? 'إيقاف الجهاز' : deviceAction === 'release' ? 'تحرير الجهاز' : 'إلغاء الجهاز'}
        size="sm"
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => { setDeviceTarget(null); setDeviceAction(null); }}>إلغاء</Button>
            <Button variant="danger" onClick={executeDeviceAction} disabled={!canManageLicenses}>
              {deviceAction === 'suspend' ? 'تأكيد الإيقاف' : deviceAction === 'release' ? 'تأكيد التحرير' : 'تأكيد الإلغاء'}
            </Button>
          </div>
        }
      >
        {deviceTarget && (
          <>
            <p className="text-[11px] text-slate-600 mb-3">
              الجهاز: <span className="font-mono text-[10px] text-slate-800" dir="ltr">{deviceTarget.hardwareId}</span>
            </p>
            <p className="text-[11px] text-slate-600 mb-1">
              الإجراء: {deviceAction === 'suspend' ? 'إيقاف' : deviceAction === 'release' ? 'تحرير' : 'إلغاء'}
            </p>
          </>
        )}
      </Modal>
    </div>
  );
};

export default PlatformLicensesPage;

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { Bell, Send, CheckCircle2, Clock, XCircle, Filter } from 'lucide-react';
import { centralPlatformClient } from '../../services/domains/platform/CentralPlatformClient';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import { formatDateTime, inputClass } from './components/PlatformUI';

type NotificationStatus = 'QUEUED' | 'PROCESSING' | 'SENT' | 'DELIVERED' | 'FAILED' | 'CANCELLED';

interface NotificationDelivery {
  id: string;
  notificationId: string;
  channel: 'EMAIL' | 'SMS' | 'IN_APP';
  recipient: string;
  status: NotificationStatus;
  provider: string | null;
  externalId: string | null;
  error: string | null;
  createdAt: string;
}

interface NotificationLog {
  id: string;
  notificationId: string;
  recipient: string;
  tenantName: string;
  channel: 'EMAIL' | 'SMS' | 'IN_APP';
  template: string;
  subject: string;
  status: NotificationStatus;
  sentAt: string;
}

const STATUS_LABELS: Record<NotificationStatus, string> = {
  QUEUED: 'بانتظار',
  PROCESSING: 'قيد المعالجة',
  SENT: 'مرسل',
  DELIVERED: 'تم التسليم',
  FAILED: 'فشل',
  CANCELLED: 'ملغي',
};

export const PlatformNotificationsHubPage: React.FC = () => {
  const canManageNotifications = canPlatform('notifications');
  const [logs, setLogs] = useState<NotificationLog[]>([]);
  const [templates, setTemplates] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [channelFilter, setChannelFilter] = useState('');
  const [isSendOpen, setIsSendOpen] = useState(false);
  const [sendError, setSendError] = useState<string | null>(null);
  const [broadcastForm, setBroadcastForm] = useState({
    channel: 'IN_APP' as 'EMAIL' | 'SMS' | 'IN_APP',
    audience: 'ALL',
    subject: '',
    message: '',
  });

  const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const notificationsResult = await centralPlatformClient.listNotifications({ limit: 100 });
      const templateList = await centralPlatformClient.listNotificationTemplates().catch(() => [] as any[]);
      const mapped: NotificationLog[] = notificationsResult.notifications.map((notification) => ({
        id: notification.id,
        notificationId: notification.id,
        recipient: notification.tenantId ? `عميل: ${notification.tenantId}` : 'النظام العام',
        tenantName: notification.tenantId ? `عميل ${notification.tenantId}` : 'المنصة',
        channel: (notification.channel as 'EMAIL' | 'SMS' | 'IN_APP'),
        template: notification.templateId ? String(notification.templateId) : 'ADMIN_BROADCAST',
        subject: notification.subject,
        status: (notification.status as NotificationStatus),
        sentAt: notification.createdAt,
      }));
      setLogs(mapped);
      setTemplates(templateList);
      setTemplates(templateList);
    } catch (loadError) {
      setError(loadError instanceof Error ? loadError.message : 'تعذر تحميل سجل الإشعارات من السيرفر المركزي.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const filteredLogs = useMemo(
    () => logs.filter((log) => (channelFilter ? log.channel === channelFilter : true)),
    [logs, channelFilter],
  );

  const deliveredCount = useMemo(
    () => logs.filter((log) => log.status === 'SENT' || log.status === 'DELIVERED').length,
    [logs],
  );
  const failedCount = useMemo(() => logs.filter((log) => log.status === 'FAILED').length, [logs]);
  const deliveryRate = logs.length ? Math.round((deliveredCount / logs.length) * 100) : 0;

  const handleSendBroadcast = async () => {
    if (!canManageNotifications) {
      setError('لا تملك صلاحية إرسال الإشعارات.');
      return;
    }
    if (!broadcastForm.subject.trim() || !broadcastForm.message.trim()) {
      setError('الموضوع ومحتوى الرسالة مطلوبان.');
      return;
    }
    setSending(true);
    setSendError(null);
    try {
      const result = await centralPlatformClient.sendNotification({
        audience: broadcastForm.audience,
        channel: broadcastForm.channel,
        subject: broadcastForm.subject.trim(),
        message: broadcastForm.message.trim(),
      });
      await load();
      setIsSendOpen(false);
      setBroadcastForm({ channel: 'IN_APP', audience: 'ALL', subject: '', message: '' });
      setError(null);
    } catch (sendError) {
      const message = sendError instanceof Error ? sendError.message : 'فشل إرسال الإشعار عبر الخدمة المركزية.';
      setSendError(message);
      setError(message);
    } finally {
      setSending(false);
    }
  };

  return (
    <div className="space-y-4 text-right">
      <PageHeader
        title="مركز الإشعارات وسجل التسليم المركزي (Notifications Hub)"
        description="إرسال التنبيهات عبر البريد الإلكتروني والرسائل النصية والإشعارات الداخلية للعملاء، ومتابعة سجلات التسليم من السيرفر المركزي."
        icon={<Bell className="h-5 w-5" />}
        actions={
          canManageNotifications ? (
            <Button size="sm" onClick={() => setIsSendOpen(true)} leadingIcon={<Send className="h-4 w-4" />}>
              إرسال إشعار مركزي جديد
            </Button>
          ) : null
        }
      />

      {error ? (
        <div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">
          {error}
        </div>
      ) : null}

      {/* KPI Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="p-3 bg-slate-900/60 border border-slate-800 rounded-xl">
          <p className="text-[11px] font-semibold text-slate-400">إجمالي الإشعارات المرسلة</p>
          <p className="text-xl font-black text-slate-100 mt-1">{logs.length}</p>
        </div>
        <div className="p-3 bg-emerald-950/20 border border-emerald-500/20 rounded-xl">
          <p className="text-[11px] font-semibold text-emerald-400">نسبة التسليم الناجح</p>
          <p className="text-xl font-black text-emerald-300 mt-1">{logs.length ? deliveryRate : 0}%</p>
        </div>
        <div className="p-3 bg-sky-950/20 border border-sky-500/20 rounded-xl">
          <p className="text-[11px] font-semibold text-sky-400">القنوات المستخدمة</p>
          <p className="text-xl font-black text-sky-300 mt-1">{['EMAIL', 'SMS', 'IN_APP'].filter((c) => logs.some((l) => l.channel === c)).join(' + ') || 'لا إشعارات بعد'}</p>
        </div>
      </div>

      {/* Filter Bar */}
      <div className="flex items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/60 p-3 shadow-sm">
        <Filter className="h-4 w-4 text-slate-400" />
        <select value={channelFilter} onChange={(e) => setChannelFilter(e.target.value)} className={`${inputClass} max-w-[200px]`}>
          <option value="">جميع القنوات</option>
          <option value="EMAIL">بريد إلكتروني (Email)</option>
          <option value="SMS">رسائل نصية (SMS)</option>
          <option value="IN_APP">داخل التطبيق (In-App)</option>
        </select>
      </div>

      {/* Logs Table */}
      <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[850px] text-right text-xs">
            <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
              <tr>
                <th className="px-4 py-3">القناة / المستلم</th>
                <th className="px-4 py-3">القالب والموضوع</th>
                <th className="px-4 py-3">الحالة</th>
                <th className="px-4 py-3">وقت التسليم</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-800/80">
              {filteredLogs.map((log) => (
                <tr key={log.id} className="hover:bg-slate-800/30 transition-colors">
                  <td className="px-4 py-3">
                    <div className="font-bold text-slate-100">{STATUS_LABELS[log.status] || log.status}</div>
                    <div className="text-[11px] font-mono text-slate-400">{log.channel}</div>
                  </td>
                  <td className="px-4 py-3">
                    <div className="font-semibold text-slate-200">{log.subject}</div>
                    <div className="text-[10px] font-mono text-slate-500">{log.template}</div>
                  </td>
                  <td className="px-4 py-3">
                    {log.status === 'SENT' || log.status === 'DELIVERED' ? (
                      <span className="text-emerald-400 font-bold flex items-center gap-1">
                        <CheckCircle2 className="h-3.5 w-3.5" /> تم التسليم
                      </span>
                    ) : log.status === 'FAILED' ? (
                      <span className="text-red-400 font-bold flex items-center gap-1">
                        <XCircle className="h-3.5 w-3.5" /> فشل التسليم
                      </span>
                    ) : (
                      <span className="text-amber-300 font-bold flex items-center gap-1">
                        <Clock className="h-3.5 w-3.5" /> {STATUS_LABELS[log.status] || log.status}
                      </span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-slate-400">{formatDateTime(log.sentAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          {!loading && filteredLogs.length === 0 ? (
            <div className="p-6 text-center text-xs text-slate-400">لا توجد إشعارات مسجلة بعد.</div>
          ) : null}
        </div>
      </div>

      {/* Modal: Broadcast */}
      <Modal open={isSendOpen} onClose={() => setIsSendOpen(false)} title="إرسال إشعار مركزي جديد">
        <div className="space-y-3.5 text-right">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">القناة</label>
              <select
                value={broadcastForm.channel}
                onChange={(e) => setBroadcastForm({ ...broadcastForm, channel: e.target.value as 'EMAIL' | 'SMS' | 'IN_APP' })}
                className={inputClass}
              >
                <option value="IN_APP">داخل التطبيق (In-App)</option>
                <option value="EMAIL">بريد إلكتروني (Email)</option>
                <option value="SMS">رسائل نصية (SMS)</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">المستهدفون</label>
              <select
                value={broadcastForm.audience}
                onChange={(e) => setBroadcastForm({ ...broadcastForm, audience: e.target.value })}
                className={inputClass}
              >
                <option value="ALL">كافة العملاء النشطين</option>
                <option value="TRIAL">المشتركون في الفترة التجريبية فقط</option>
                <option value="EXPIRED">أصحاب الاشتراكات المنتهية</option>
              </select>
            </div>
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">عنوان الإشعار / الموضوع *</label>
            <input type="text" value={broadcastForm.subject} onChange={(e) => setBroadcastForm({ ...broadcastForm, subject: e.target.value })} className={inputClass} />
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">نص الرسالة *</label>
            <textarea rows={4} value={broadcastForm.message} onChange={(e) => setBroadcastForm({ ...broadcastForm, message: e.target.value })} className={inputClass} />
          </div>
          {sendError ? <div className="rounded border border-red-200 bg-red-50 p-2 text-xs text-red-700">{sendError}</div> : null}
          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsSendOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={() => void handleSendBroadcast()} disabled={sending || !canManageNotifications}>
              {sending ? 'جارٍ الإرسال…' : 'إرسال عبر الخدمة المركزية'}
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformNotificationsHubPage;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Activity,
  Play,
  RotateCcw,
  XCircle,
  CheckCircle2,
  Clock,
  AlertTriangle,
  Server,
  Calendar,
  ShieldCheck,
  ShieldAlert,
  RefreshCw,
  Search,
  Filter,
  Check,
  X,
  Plus,
  ArrowRight,
  Database,
  Smartphone,
  Cpu,
  Layers,
  Terminal,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformOpsJob,
  PlatformOpsJobStatus,
  PlatformMaintenanceWindow,
  PlatformMaintenanceStatus,
  PlatformOpApproval,
  PlatformOpApprovalStatus,
  PlatformSyncLogEntry,
  PlatformSyncStatus,
  PlatformTenant,
} from '../../services/domains/platform/platformTypes';
import { Button } from '../../components/ui/Button';
import { PageHeader } from '../../components/ui/PageHeader';
import { EmptyState, formatDateTime, inputClass } from './components/PlatformUI';

type OperationsTab = 'jobs' | 'scheduled' | 'sync' | 'approvals' | 'maintenance' | 'errors';

export const PlatformOperationsSettingsPage: React.FC = () => {
  const [activeTab, setActiveTab] = useState<OperationsTab>('jobs');
  const canManageOperations = canPlatform('operations');
  const [loading, setLoading] = useState<boolean>(true);
  const [tenants, setTenants] = useState<PlatformTenant[]>([]);

  // Jobs state
  const [jobs, setJobs] = useState<PlatformOpsJob[]>([]);
  const [jobStatusFilter, setJobStatusFilter] = useState<string>('');
  const [jobTenantFilter, setJobTenantFilter] = useState<string>('');
  const [jobSearch, setJobSearch] = useState<string>('');
  const [newJobModalOpen, setNewJobModalOpen] = useState<boolean>(false);
  const [newJobType, setNewJobType] = useState<string>('SCHEMA_MIGRATE');
  const [newJobTenantId, setNewJobTenantId] = useState<string>('');
  const [newJobPriority, setNewJobPriority] = useState<number>(5);

  // Maintenance state
  const [maintenanceWindows, setMaintenanceWindows] = useState<PlatformMaintenanceWindow[]>([]);
  const [newMaintModalOpen, setNewMaintModalOpen] = useState<boolean>(false);
  const [newMaintTitle, setNewMaintTitle] = useState<string>('');
  const [newMaintDesc, setNewMaintDesc] = useState<string>('');
  const [newMaintStart, setNewMaintStart] = useState<string>('');
  const [newMaintEnd, setNewMaintEnd] = useState<string>('');
  const [newMaintServices, setNewMaintServices] = useState<string>('api,web,sync');

  // Approvals state
  const [approvals, setApprovals] = useState<PlatformOpApproval[]>([]);
  const [approvalActionModal, setApprovalActionModal] = useState<{ id: string; type: 'approve' | 'reject' } | null>(null);
  const [approvalNotes, setApprovalNotes] = useState<string>('');

  // Sync state
  const [syncLogs, setSyncLogs] = useState<PlatformSyncLogEntry[]>([]);
  const [syncStatusFilter, setSyncStatusFilter] = useState<string>('');

  // Load Tenants
  const loadTenants = useCallback(() => {
    try {
      const list = platformAdminService.listTenants();
      setTenants(list);
    } catch {
      // Fallback
      setTenants([]);
    }
  }, []);

  // Load Data based on active tab
  const loadData = useCallback(() => {
    setLoading(true);
    try {
      if (activeTab === 'jobs' || activeTab === 'scheduled' || activeTab === 'errors') {
        const res = platformAdminService.listOpsJobs({
          status: activeTab === 'errors' ? 'FAILED' : jobStatusFilter || undefined,
          tenantId: jobTenantFilter || undefined,
        });
        setJobs(res.jobs);
      }
      if (activeTab === 'maintenance') {
        const mw = platformAdminService.listMaintenanceWindows();
        setMaintenanceWindows(mw);
      }
      if (activeTab === 'approvals') {
        const apprs = platformAdminService.listOpApprovals();
        setApprovals(apprs);
      }
      if (activeTab === 'sync') {
        const logs = platformAdminService.listSyncStatus({
          status: syncStatusFilter || undefined,
        });
        setSyncLogs(logs);
      }
    } catch (err) {
      console.error('Failed to load operations data:', err);
    } finally {
      setLoading(false);
    }
  }, [activeTab, jobStatusFilter, jobTenantFilter, syncStatusFilter]);

  useEffect(() => {
    loadTenants();
  }, [loadTenants]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Actions
  const handleRetryJob = (id: string) => {
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    try {
      platformAdminService.retryOpsJob(id);
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  const handleCancelJob = (id: string) => {
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    if (!confirm('هل أنت متأكد من إلغاء هذه العملية؟')) return;
    try {
      platformAdminService.cancelOpsJob(id);
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  const handleCreateJob = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    try {
      platformAdminService.createOpsJob({
        type: newJobType,
        tenantId: newJobTenantId || undefined,
        priority: Number(newJobPriority),
      });
      setNewJobModalOpen(false);
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  const handleCreateMaintenance = (e: React.FormEvent) => {
    e.preventDefault();
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    if (!newMaintTitle || !newMaintStart || !newMaintEnd) return;
    try {
      platformAdminService.createMaintenanceWindow({
        title: newMaintTitle,
        description: newMaintDesc || undefined,
        startsAt: newMaintStart,
        endsAt: newMaintEnd,
        affectedServices: newMaintServices.split(',').map((s) => s.trim()).filter(Boolean),
      });
      setNewMaintModalOpen(false);
      setNewMaintTitle('');
      setNewMaintDesc('');
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  const handleCancelMaintenance = (id: string) => {
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    if (!confirm('هل أنت متأكد من إلغاء نافذة الصيانة؟')) return;
    try {
      platformAdminService.cancelMaintenanceWindow(id);
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  const handleConfirmApprovalAction = () => {
    if (!approvalActionModal) return;
    if (!canManageOperations) {
      alert('لا تملك صلاحية إدارة العمليات.');
      return;
    }
    try {
      if (approvalActionModal.type === 'approve') {
        platformAdminService.approveOp(approvalActionModal.id, approvalNotes);
      } else {
        platformAdminService.rejectOp(approvalActionModal.id, approvalNotes);
      }
      setApprovalActionModal(null);
      setApprovalNotes('');
      loadData();
    } catch (e) {
      alert((e as Error).message);
    }
  };

  // Helper labels & styling
  const getJobStatusBadge = (status: PlatformOpsJobStatus) => {
    switch (status) {
      case 'PENDING':
        return <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/10 text-amber-400 border border-amber-500/20"><Clock className="w-3 h-3" /> قيد الانتظار</span>;
      case 'RUNNING':
        return <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-500/10 text-blue-400 border border-blue-500/20"><RefreshCw className="w-3 h-3 animate-spin" /> قيد التشغيل</span>;
      case 'DONE':
        return <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20"><CheckCircle2 className="w-3 h-3" /> مكتملة</span>;
      case 'FAILED':
        return <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-rose-500/10 text-rose-400 border border-rose-500/20"><AlertTriangle className="w-3 h-3" /> فشلت</span>;
      case 'CANCELLED':
        return <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-medium bg-zinc-500/10 text-zinc-400 border border-zinc-500/20"><XCircle className="w-3 h-3" /> ملغاة</span>;
    }
  };

  const getMaintStatusBadge = (status: PlatformMaintenanceStatus) => {
    switch (status) {
      case 'SCHEDULED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-blue-500/10 text-blue-400 border border-blue-500/20">مجدولة</span>;
      case 'ACTIVE':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/10 text-amber-400 border border-amber-500/20 animate-pulse">جارية حالياً</span>;
      case 'COMPLETED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">مكتملة</span>;
      case 'CANCELLED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-zinc-500/10 text-zinc-400 border border-zinc-500/20">ملغاة</span>;
    }
  };

  const getApprovalStatusBadge = (status: PlatformOpApprovalStatus) => {
    switch (status) {
      case 'PENDING':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-amber-500/10 text-amber-400 border border-amber-500/20">في انتظار الموافقة</span>;
      case 'APPROVED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">تمت الموافقة</span>;
      case 'REJECTED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-rose-500/10 text-rose-400 border border-rose-500/20">مرفوضة</span>;
      case 'CANCELLED':
        return <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-zinc-500/10 text-zinc-400 border border-zinc-500/20">ملغاة</span>;
    }
  };

  const filteredJobs = useMemo(() => {
    return jobs.filter((j) => {
      if (jobSearch) {
        const q = jobSearch.toLowerCase();
        const matchesId = j.id.toLowerCase().includes(q);
        const matchesType = j.type.toLowerCase().includes(q);
        const matchesTenant = j.tenantId?.toLowerCase().includes(q);
        if (!matchesId && !matchesType && !matchesTenant) return false;
      }
      if (activeTab === 'scheduled' && !j.scheduledAt) return false;
      return true;
    });
  }, [jobs, jobSearch, activeTab]);

  return (
    <div className="space-y-6" dir="rtl">
      {/* Page Header */}
      <PageHeader
        title="مركز التشغيل والموافقات"
        description="إدارة طوابير العمليات، المهام المجدولة، حالات المزامنة، نوافذ الصيانة، وموافقات العمليات الحساسة"
        actions={
          <div className="flex items-center gap-2">
            <Button variant="secondary" onClick={loadData}>
              <RefreshCw className="w-4 h-4 ml-2" />
              تحديث
            </Button>
            {activeTab === 'jobs' && canManageOperations && (
              <Button variant="primary" onClick={() => setNewJobModalOpen(true)}>
                <Plus className="w-4 h-4 ml-2" />
                إنشاء مهمة تشغيل
              </Button>
            )}
            {activeTab === 'maintenance' && canManageOperations && (
              <Button variant="primary" onClick={() => setNewMaintModalOpen(true)}>
                <Plus className="w-4 h-4 ml-2" />
                جدولة صيانة
              </Button>
            )}
          </div>
        }
      />

      {/* Tabs */}
      <div className="flex border-b border-zinc-800 space-x-1 space-x-reverse overflow-x-auto">
        <button
          onClick={() => setActiveTab('jobs')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'jobs'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Activity className="w-4 h-4" />
          طابور العمليات (Queue)
        </button>
        <button
          onClick={() => setActiveTab('scheduled')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'scheduled'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Clock className="w-4 h-4" />
          المهام المجدولة
        </button>
        <button
          onClick={() => setActiveTab('sync')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'sync'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Cpu className="w-4 h-4" />
          حالة المزامنة والأجهزة
        </button>
        <button
          onClick={() => setActiveTab('approvals')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'approvals'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <ShieldCheck className="w-4 h-4" />
          موافقات العمليات الحساسة
        </button>
        <button
          onClick={() => setActiveTab('maintenance')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'maintenance'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <Calendar className="w-4 h-4" />
          أعمال الصيانة المجدولة
        </button>
        <button
          onClick={() => setActiveTab('errors')}
          className={`flex items-center gap-2 px-4 py-3 text-sm font-medium border-b-2 transition-colors whitespace-nowrap ${
            activeTab === 'errors'
              ? 'border-emerald-500 text-emerald-400'
              : 'border-transparent text-zinc-400 hover:text-zinc-200'
          }`}
        >
          <AlertTriangle className="w-4 h-4" />
          سجل الأخطاء والمعالجات
        </button>
      </div>

      {/* Main Tab Views */}
      {/* ─── TAB 1 & 2 & 6: Jobs, Scheduled, Errors ───────────────────────────────── */}
      {(activeTab === 'jobs' || activeTab === 'scheduled' || activeTab === 'errors') && (
        <div className="space-y-4">
          {/* Filters */}
          <div className="flex flex-wrap items-center justify-between gap-3 bg-zinc-900/50 p-3 rounded-lg border border-zinc-800">
            <div className="flex items-center gap-3 flex-1 min-w-[280px]">
              <div className="relative flex-1">
                <Search className="w-4 h-4 absolute right-3 top-3 text-zinc-400" />
                <input
                  type="text"
                  placeholder="بحث بنوع المهمة أو المعرف..."
                  value={jobSearch}
                  onChange={(e) => setJobSearch(e.target.value)}
                  className={`${inputClass} pr-9`}
                />
              </div>
              {activeTab === 'jobs' && (
                <select
                  value={jobStatusFilter}
                  onChange={(e) => setJobStatusFilter(e.target.value)}
                  className={inputClass}
                >
                  <option value="">جميع الحالات</option>
                  <option value="PENDING">قيد الانتظار</option>
                  <option value="RUNNING">قيد التشغيل</option>
                  <option value="DONE">مكتملة</option>
                  <option value="FAILED">فاشلة</option>
                  <option value="CANCELLED">ملغاة</option>
                </select>
              )}
              <select
                value={jobTenantFilter}
                onChange={(e) => setJobTenantFilter(e.target.value)}
                className={inputClass}
              >
                <option value="">جميع العملاء</option>
                {tenants.map((t) => (
                  <option key={t.id} value={t.id}>
                    {t.name} ({t.code})
                  </option>
                ))}
              </select>
            </div>
            <div className="text-xs text-zinc-400">
              إجمالي النتائج: <span className="font-semibold text-zinc-200">{filteredJobs.length}</span>
            </div>
          </div>

          {/* Table */}
          <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
            <table className="w-full text-right text-sm">
              <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800">
                <tr>
                  <th className="py-3 px-4">نوع العملية</th>
                  <th className="py-3 px-4">العميل المرتبط</th>
                  <th className="py-3 px-4">الحالة</th>
                  <th className="py-3 px-4">الأولوية</th>
                  <th className="py-3 px-4">المحاولات</th>
                  <th className="py-3 px-4">التاريخ والجدولة</th>
                  <th className="py-3 px-4 text-left">إجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/60">
                {filteredJobs.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center">
                      <EmptyState title="لا توجد مهام تشغيل تطابق الفلاتر المحددة" />
                    </td>
                  </tr>
                ) : (
                  filteredJobs.map((job) => (
                    <tr key={job.id} className="hover:bg-zinc-800/20 transition-colors">
                      <td className="py-3 px-4">
                        <div className="font-medium text-zinc-200">{job.type}</div>
                        <div className="text-xs text-zinc-500 font-mono mt-0.5">{job.id.substring(0, 8)}...</div>
                        {job.errorMessage && (
                          <div className="text-xs text-rose-400 mt-1 max-w-md truncate" title={job.errorMessage}>
                            خطأ: {job.errorMessage}
                          </div>
                        )}
                      </td>
                      <td className="py-3 px-4">
                        {job.tenantId ? (
                          <span className="text-zinc-300">
                            {tenants.find((t) => t.id === job.tenantId)?.name || job.tenantId}
                          </span>
                        ) : (
                          <span className="text-zinc-500 text-xs">نظام عام</span>
                        )}
                      </td>
                      <td className="py-3 px-4">{getJobStatusBadge(job.status)}</td>
                      <td className="py-3 px-4">
                        <span className="text-xs font-semibold px-2 py-0.5 rounded bg-zinc-800 text-zinc-300">
                          {job.priority}
                        </span>
                      </td>
                      <td className="py-3 px-4">
                        <span className={`text-xs ${job.retries > 0 ? 'text-amber-400 font-semibold' : 'text-zinc-400'}`}>
                          {job.retries} / {job.maxRetries}
                        </span>
                      </td>
                      <td className="py-3 px-4 text-xs text-zinc-400">
                        <div>أنشئت: {formatDateTime(job.createdAt)}</div>
                        {job.scheduledAt && <div className="text-blue-400">مجدولة: {formatDateTime(job.scheduledAt)}</div>}
                      </td>
                      <td className="py-3 px-4 text-left">
                        <div className="flex items-center justify-end gap-1.5">
                          {canManageOperations && (job.status === 'FAILED' || job.status === 'CANCELLED') && (
                            <Button
                              variant="secondary"
                              size="sm"
                              onClick={() => handleRetryJob(job.id)}
                              title="إعادة المحاولة فوراً"
                            >
                              <RotateCcw className="w-3.5 h-3.5 ml-1 text-amber-400" />
                              إعادة
                            </Button>
                          )}
                          {canManageOperations && (job.status === 'PENDING' || job.status === 'RUNNING') && (
                            <Button
                              variant="danger"
                              size="sm"
                              onClick={() => handleCancelJob(job.id)}
                              title="إلغاء العملية"
                            >
                              <X className="w-3.5 h-3.5 ml-1" />
                              إلغاء
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ─── TAB 3: Sync & Devices ────────────────────────────────────────────────── */}
      {activeTab === 'sync' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between gap-3 bg-zinc-900/50 p-3 rounded-lg border border-zinc-800">
            <div className="flex items-center gap-3">
              <select
                value={syncStatusFilter}
                onChange={(e) => setSyncStatusFilter(e.target.value)}
                className={inputClass}
              >
                <option value="">جميع حالات المزامنة</option>
                <option value="SUCCESS">نجحت (SUCCESS)</option>
                <option value="PARTIAL">جزئية (PARTIAL)</option>
                <option value="FAIL">فشلت (FAIL)</option>
              </select>
            </div>
            <div className="text-xs text-zinc-400">
              سجلات المزامنة الأخيرة: <span className="font-semibold text-zinc-200">{syncLogs.length}</span>
            </div>
          </div>

          <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
            <table className="w-full text-right text-sm">
              <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800">
                <tr>
                  <th className="py-3 px-4">نوع المزامنة</th>
                  <th className="py-3 px-4">العميل</th>
                  <th className="py-3 px-4">الجهاز</th>
                  <th className="py-3 px-4">الحالة</th>
                  <th className="py-3 px-4">السجلات المتزامنة</th>
                  <th className="py-3 px-4">التاريخ والوقت</th>
                  <th className="py-3 px-4">التفاصيل</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/60">
                {syncLogs.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center">
                      <EmptyState title="لا توجد سجلات مزامنة حالياً" />
                    </td>
                  </tr>
                ) : (
                  syncLogs.map((log) => (
                    <tr key={log.id} className="hover:bg-zinc-800/20 transition-colors">
                      <td className="py-3 px-4 font-medium text-zinc-200">{log.syncType}</td>
                      <td className="py-3 px-4">
                        {log.tenantId ? (
                          <span className="text-zinc-300">
                            {tenants.find((t) => t.id === log.tenantId)?.name || log.tenantId}
                          </span>
                        ) : (
                          <span className="text-zinc-500">—</span>
                        )}
                      </td>
                      <td className="py-3 px-4 font-mono text-xs text-zinc-400">
                        {log.deviceId ? log.deviceId.substring(0, 10) + '...' : 'الرئيسي'}
                      </td>
                      <td className="py-3 px-4">
                        {log.status === 'SUCCESS' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">ناجحة</span>
                        )}
                        {log.status === 'PARTIAL' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-amber-500/10 text-amber-400 border border-amber-500/20">جزئية</span>
                        )}
                        {log.status === 'FAIL' && (
                          <span className="px-2 py-0.5 rounded text-xs bg-rose-500/10 text-rose-400 border border-rose-500/20">فشلت</span>
                        )}
                      </td>
                      <td className="py-3 px-4 text-zinc-200 font-semibold">{log.recordsSynced}</td>
                      <td className="py-3 px-4 text-xs text-zinc-400">{formatDateTime(log.createdAt)}</td>
                      <td className="py-3 px-4 text-xs text-zinc-400 max-w-xs truncate" title={log.errorDetail || ''}>
                        {log.errorDetail || '—'}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ─── TAB 4: Sensitive Operations Approvals ─────────────────────────────────── */}
      {activeTab === 'approvals' && (
        <div className="space-y-4">
          <div className="bg-amber-950/20 border border-amber-800/30 p-4 rounded-lg flex items-start gap-3">
            <ShieldAlert className="w-5 h-5 text-amber-400 flex-shrink-0 mt-0.5" />
            <div className="text-sm">
              <div className="font-semibold text-amber-300">نظام الموافقة الثنائية على العمليات الحساسة</div>
              <div className="text-amber-200/70 text-xs mt-0.5">
                العمليات مثل حذف بيانات العملاء، ترحيل المخططات، والعمليات المالية تتطلب موافقة صريحة من مسؤول المنصة قبل التنفيذ.
              </div>
            </div>
          </div>

          <div className="overflow-x-auto bg-zinc-900/40 rounded-lg border border-zinc-800">
            <table className="w-full text-right text-sm">
              <thead className="bg-zinc-900/80 text-zinc-400 border-b border-zinc-800">
                <tr>
                  <th className="py-3 px-4">نوع العملية</th>
                  <th className="py-3 px-4">طالب العملية</th>
                  <th className="py-3 px-4">الحالة</th>
                  <th className="py-3 px-4">تاريخ الطلب</th>
                  <th className="py-3 px-4">المسؤول / المعتمد</th>
                  <th className="py-3 px-4">ملاحظات</th>
                  <th className="py-3 px-4 text-left">القرار</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-zinc-800/60">
                {approvals.length === 0 ? (
                  <tr>
                    <td colSpan={7} className="py-8 text-center">
                      <EmptyState title="لا توجد طلبات موافقة معلقة أو مسجلة" />
                    </td>
                  </tr>
                ) : (
                  approvals.map((appr) => (
                    <tr key={appr.id} className="hover:bg-zinc-800/20 transition-colors">
                      <td className="py-3 px-4 font-medium text-zinc-200">{appr.opType}</td>
                      <td className="py-3 px-4 text-xs font-mono text-zinc-400">{appr.requestedBy}</td>
                      <td className="py-3 px-4">{getApprovalStatusBadge(appr.status)}</td>
                      <td className="py-3 px-4 text-xs text-zinc-400">{formatDateTime(appr.createdAt)}</td>
                      <td className="py-3 px-4 text-xs font-mono text-zinc-400">{appr.approvedBy || '—'}</td>
                      <td className="py-3 px-4 text-xs text-zinc-400 max-w-xs truncate">{appr.notes || '—'}</td>
                      <td className="py-3 px-4 text-left">
                        {appr.status === 'PENDING' && canManageOperations && (
                          <div className="flex items-center justify-end gap-1.5">
                            <Button
                              variant="success"
                              size="sm"
                              onClick={() => setApprovalActionModal({ id: appr.id, type: 'approve' })}
                            >
                              <Check className="w-3.5 h-3.5 ml-1" />
                              موافقة
                            </Button>
                            <Button
                              variant="danger"
                              size="sm"
                              onClick={() => setApprovalActionModal({ id: appr.id, type: 'reject' })}
                            >
                              <X className="w-3.5 h-3.5 ml-1" />
                              رفض
                            </Button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* ─── TAB 5: Maintenance Windows ───────────────────────────────────────────── */}
      {activeTab === 'maintenance' && (
        <div className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {maintenanceWindows.length === 0 ? (
              <div className="col-span-full py-12 text-center bg-zinc-900/30 rounded-lg border border-zinc-800">
                <EmptyState title="لا توجد نوافذ صيانة مجدولة حالياً" />
              </div>
            ) : (
              maintenanceWindows.map((mw) => (
                <div key={mw.id} className="bg-zinc-900/60 p-4 rounded-lg border border-zinc-800 space-y-3">
                  <div className="flex items-start justify-between">
                    <div>
                      <h4 className="font-semibold text-zinc-100">{mw.title}</h4>
                      <div className="text-xs text-zinc-500 mt-0.5">أنشئت بواسطة: {mw.createdBy}</div>
                    </div>
                    {getMaintStatusBadge(mw.status)}
                  </div>
                  {mw.description && <p className="text-xs text-zinc-400 leading-relaxed">{mw.description}</p>}
                  <div className="bg-zinc-950 p-2.5 rounded border border-zinc-800/80 text-xs space-y-1 text-zinc-300">
                    <div>من: <span className="font-semibold text-zinc-100">{formatDateTime(mw.startsAt)}</span></div>
                    <div>إلى: <span className="font-semibold text-zinc-100">{formatDateTime(mw.endsAt)}</span></div>
                  </div>
                  <div>
                    <div className="text-xs text-zinc-500 mb-1">الخدمات المتأثرة:</div>
                    <div className="flex flex-wrap gap-1">
                      {mw.affectedServices.map((srv, idx) => (
                        <span key={idx} className="px-2 py-0.5 rounded text-[11px] bg-zinc-800 text-zinc-300 font-mono">
                          {srv}
                        </span>
                      ))}
                    </div>
                  </div>
                  {mw.status === 'SCHEDULED' && canManageOperations && (
                    <div className="pt-2 border-t border-zinc-800/60 flex justify-end">
                      <Button variant="danger" size="sm" onClick={() => handleCancelMaintenance(mw.id)}>
                        <X className="w-3.5 h-3.5 ml-1" />
                        إلغاء نافذة الصيانة
                      </Button>
                    </div>
                  )}
                </div>
              ))
            )}
          </div>
        </div>
      )}

      {/* ─── Modals ───────────────────────────────────────────────────────────────── */}
      {/* Create Job Modal */}
      {newJobModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-xl max-w-lg w-full p-6 space-y-4">
            <h3 className="text-lg font-semibold text-zinc-100">إنشاء مهمة تشغيل جديدة</h3>
            <form onSubmit={handleCreateJob} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">نوع العملية</label>
                <select
                  value={newJobType}
                  onChange={(e) => setNewJobType(e.target.value)}
                  className={`w-full ${inputClass}`}
                >
                  <option value="SCHEMA_MIGRATE">ترحيل مخطط قاعدة البيانات (SCHEMA_MIGRATE)</option>
                  <option value="BACKUP">نسخ احتياطي شامل (BACKUP)</option>
                  <option value="RESTORE">استرجاع نسخة احتياطية (RESTORE)</option>
                  <option value="DEVICE_SYNC">إعادة مزامنة الأجهزة (DEVICE_SYNC)</option>
                  <option value="DATA_EXPORT">تصدير بيانات (DATA_EXPORT)</option>
                  <option value="BILLING_CHARGE">دورة فوترة واشتراكات (BILLING_CHARGE)</option>
                  <option value="NOTIFICATION_BLAST">إرسال إشعارات جماعية (NOTIFICATION_BLAST)</option>
                </select>
              </div>

              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">العميل المستهدف (اختياري)</label>
                <select
                  value={newJobTenantId}
                  onChange={(e) => setNewJobTenantId(e.target.value)}
                  className={`w-full ${inputClass}`}
                >
                  <option value="">جميع العملاء / مستوى المنصة العام</option>
                  {tenants.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name} ({t.code})
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">الأولوية (1 الأعلى - 10 الأقل)</label>
                <input
                  type="number"
                  min="1"
                  max="10"
                  value={newJobPriority}
                  onChange={(e) => setNewJobPriority(Number(e.target.value))}
                  className={`w-full ${inputClass}`}
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-zinc-800">
                <Button variant="secondary" type="button" onClick={() => setNewJobModalOpen(false)}>
                  إلغاء
                </Button>
                <Button variant="primary" type="submit" disabled={!canManageOperations}>
                  إدراج في الطابور
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Create Maintenance Window Modal */}
      {newMaintModalOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-xl max-w-lg w-full p-6 space-y-4">
            <h3 className="text-lg font-semibold text-zinc-100">جدولة أعمال صيانة جديدة</h3>
            <form onSubmit={handleCreateMaintenance} className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">عنوان الصيانة</label>
                <input
                  type="text"
                  required
                  placeholder="مثال: ترقية خوادم قواعد البيانات المركزية"
                  value={newMaintTitle}
                  onChange={(e) => setNewMaintTitle(e.target.value)}
                  className={`w-full ${inputClass}`}
                />
              </div>

              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">وصف الصيانة</label>
                <textarea
                  rows={3}
                  placeholder="تفاصيل التحديث والأثر المتوقع على الخدمة..."
                  value={newMaintDesc}
                  onChange={(e) => setNewMaintDesc(e.target.value)}
                  className={`w-full ${inputClass}`}
                />
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-xs font-medium text-zinc-400 mb-1">تاريخ ووقت البدء</label>
                  <input
                    type="datetime-local"
                    required
                    value={newMaintStart}
                    onChange={(e) => setNewMaintStart(e.target.value)}
                    className={`w-full ${inputClass}`}
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium text-zinc-400 mb-1">تاريخ ووقت الانتهاء</label>
                  <input
                    type="datetime-local"
                    required
                    value={newMaintEnd}
                    onChange={(e) => setNewMaintEnd(e.target.value)}
                    className={`w-full ${inputClass}`}
                  />
                </div>
              </div>

              <div>
                <label className="block text-xs font-medium text-zinc-400 mb-1">الخدمات المتأثرة (مفصولة بفاصلة)</label>
                <input
                  type="text"
                  value={newMaintServices}
                  onChange={(e) => setNewMaintServices(e.target.value)}
                  placeholder="api, payments, sync, web"
                  className={`w-full ${inputClass}`}
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-zinc-800">
                <Button variant="secondary" type="button" onClick={() => setNewMaintModalOpen(false)}>
                  إلغاء
                </Button>
                <Button variant="primary" type="submit" disabled={!canManageOperations}>
                  تأكيد الجدولة
                </Button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Approval Confirm Modal */}
      {approvalActionModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-zinc-900 border border-zinc-800 rounded-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-semibold text-zinc-100">
              {approvalActionModal.type === 'approve' ? 'الموافقة على العملية' : 'رفض العملية'}
            </h3>
            <p className="text-xs text-zinc-400 leading-relaxed">
              {approvalActionModal.type === 'approve'
                ? 'بتأكيد الموافقة، سيتم السماح بتنفيذ العملية الحساسة واعتمادها في سجل العمليات.'
                : 'برفض العملية، سيتم إلغاؤها نهائياً وإخطار الطالب بالرفض.'}
            </p>
            <div>
              <label className="block text-xs font-medium text-zinc-400 mb-1">ملاحظات القرار (اختياري)</label>
              <textarea
                rows={3}
                placeholder="أدخل سبب القرار أو أية تعليمات..."
                value={approvalNotes}
                onChange={(e) => setApprovalNotes(e.target.value)}
                className={`w-full ${inputClass}`}
              />
            </div>
            <div className="flex justify-end gap-2 pt-3 border-t border-zinc-800">
              <Button variant="secondary" type="button" onClick={() => setApprovalActionModal(null)}>
                إلغاء
              </Button>
              <Button
                variant={approvalActionModal.type === 'approve' ? 'success' : 'danger'}
                type="button"
                onClick={handleConfirmApprovalAction}
                disabled={!canManageOperations}
              >
                {approvalActionModal.type === 'approve' ? 'تأكيد الموافقة' : 'تأكيد الرفض'}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default PlatformOperationsSettingsPage;

import React from 'react';
import {
  Boxes,
  Plus,
  Pencil,
  Rocket,
  Sparkles,
  SlidersHorizontal,
  BadgeCheck,
  AlertTriangle,
  Users,
  CheckCircle2,
  XCircle,
  Clock,
  RotateCcw,
  FileCheck,
  ShieldAlert,
  Search,
  ExternalLink,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformFeatureFlag,
  PlatformFeatureOverride,
  PlatformModule,
  PlatformRelease,
  PlatformReleaseTarget,
  PlatformTenant,
} from '../../services/domains/platform/platformTypes';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import { PageHeader } from '../../components/ui/PageHeader';
import { useToast } from '../../components/ui/Toast';
import {
  EmptyState,
  Field,
  StatusBadge,
  Toggle,
  formatDate,
  inputClass,
} from './components/PlatformUI';

const TABS = [
  { id: 'modules', label: 'الوحدات', icon: SlidersHorizontal },
  { id: 'features', label: 'المزايا والرايات (Feature Flags)', icon: Sparkles },
  { id: 'releases', label: 'الإصدارات وحزم التحديث', icon: Rocket },
] as const;

type TabId = (typeof TABS)[number]['id'];

const RELEASE_STATUS_LABELS: Record<string, string> = {
  DRAFT: 'مسودة',
  PUBLISHED: 'منشور',
  DEPRECATED: 'متوقف',
};

const CHANNEL_LABELS: Record<string, string> = {
  STABLE: 'مستقر',
  BETA: 'تجريبي',
  NIGHTLY: 'ليلي',
};

const TARGET_STATUS_LABELS: Record<string, { label: string; color: string; icon: any }> = {
  PENDING: { label: 'قيد الانتظار', color: 'bg-amber-50 text-amber-700 border-amber-200', icon: Clock },
  SUCCESS: { label: 'تم بنجاح', color: 'bg-emerald-50 text-emerald-700 border-emerald-200', icon: CheckCircle2 },
  FAILED: { label: 'فشل التحديث', color: 'bg-rose-50 text-rose-700 border-rose-200', icon: XCircle },
  SKIPPED: { label: 'تم التخطي', color: 'bg-slate-100 text-slate-700 border-slate-200', icon: Clock },
};

const emptyFeature = {
  id: undefined as string | undefined,
  code: '',
  name: '',
  description: '',
  category: '',
  isEnabled: true,
  rolloutPercent: 100,
  isStagingOnly: false,
  minPlanTier: '',
};

const emptyRelease = {
  id: undefined as string | undefined,
  version: '',
  channel: 'STABLE' as string,
  status: 'PUBLISHED' as string,
  targetsSummary: null as Record<string, number> | null,
  notes: '',
  rollbackVersion: '',
  isMandatory: false,
  minVersion: '',
  rolloutGroup: 'ALL',
  stagingGroup: 'PRODUCTION',
  fileUrl: '',
  fileName: '',
  fileSize: '' as string,
  checksumSha256: '',
  packageSignature: '',
  changelog: '',
  releasedAt: new Date().toISOString().slice(0, 10),
};

export const PlatformProductPage: React.FC = () => {
  const toast = useToast();
  const canManageProduct = canPlatform('product', 'platform.product.update');
  const [tab, setTab] = React.useState<TabId>('modules');
  const [modules, setModules] = React.useState<PlatformModule[]>([]);
  const [features, setFeatures] = React.useState<PlatformFeatureFlag[]>([]);
  const [releases, setReleases] = React.useState<PlatformRelease[]>([]);
  const [tenants, setTenants] = React.useState<PlatformTenant[]>([]);
  const [loading, setLoading] = React.useState(true);
  const [error, setError] = React.useState<string | null>(null);

  // Feature Modals & State
  const [featureOpen, setFeatureOpen] = React.useState(false);
  const [featureForm, setFeatureForm] = React.useState(emptyFeature);
  const [selectedFeatureForOverrides, setSelectedFeatureForOverrides] = React.useState<PlatformFeatureFlag | null>(null);
  const [featureOverrides, setFeatureOverrides] = React.useState<PlatformFeatureOverride[]>([]);
  const [newOverrideTenantId, setNewOverrideTenantId] = React.useState('');
  const [newOverrideEnabled, setNewOverrideEnabled] = React.useState(true);
  const [newOverrideCustomRollout, setNewOverrideCustomRollout] = React.useState<number | ''>('');

  // Release Modals & State
  const [releaseOpen, setReleaseOpen] = React.useState(false);
  const [releaseForm, setReleaseForm] = React.useState(emptyRelease);
  const [selectedReleaseForTargets, setSelectedReleaseForTargets] = React.useState<PlatformRelease | null>(null);
  const [releaseTargets, setReleaseTargets] = React.useState<PlatformReleaseTarget[]>([]);
  const [targetSearchTerm, setTargetSearchTerm] = React.useState('');
  const [selectedTenantIdsForRelease, setSelectedTenantIdsForRelease] = React.useState<string[]>([]);

  // Rollback Modal State
  const [rollbackOpen, setRollbackOpen] = React.useState(false);
  const [rollbackReleaseItem, setRollbackReleaseItem] = React.useState<PlatformRelease | null>(null);
  const [safeRollbackVersion, setSafeRollbackVersion] = React.useState('');

  const [saving, setSaving] = React.useState(false);

  const load = React.useCallback(() => {
    setLoading(true);
    try {
      setModules(platformAdminService.listModules());
      setFeatures(platformAdminService.listFeatureFlags());
      setReleases(platformAdminService.listReleases());
      setTenants(platformAdminService.listTenants());
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل بيانات المنتج.');
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  const toggleModule = (module: PlatformModule) => {
    try {
      platformAdminService.setModuleEnabled(module.id, !module.isEnabled);
      toast.success(module.isEnabled ? 'تم تعطيل الوحدة' : 'تم تفعيل الوحدة');
      load();
    } catch (err) {
      toast.error('تعذر تحديث الوحدة', err instanceof Error ? err.message : undefined);
    }
  };

  // ─── Feature Flags Management ──────────────────────────────────────────

  const openFeature = (flag?: PlatformFeatureFlag) => {
    setFeatureForm(
      flag
        ? {
            id: flag.id,
            code: flag.code,
            name: flag.name,
            description: flag.description ?? '',
            category: flag.category ?? '',
            isEnabled: flag.isEnabled,
            rolloutPercent: flag.rolloutPercent,
            isStagingOnly: Boolean(flag.isStagingOnly),
            minPlanTier: flag.minPlanTier ?? '',
          }
        : { ...emptyFeature }
    );
    setFeatureOpen(true);
  };

  const saveFeature = () => {
    setSaving(true);
    try {
      platformAdminService.upsertFeatureFlag({
        ...featureForm,
        rolloutPercent: Number(featureForm.rolloutPercent),
        minPlanTier: featureForm.minPlanTier || undefined,
      });
      toast.success(featureForm.id ? 'تم تحديث الميزة' : 'تم إنشاء الميزة');
      setFeatureOpen(false);
      load();
    } catch (err) {
      toast.error('تعذر حفظ الميزة', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const toggleFeature = (flag: PlatformFeatureFlag) => {
    try {
      platformAdminService.setFeatureEnabled(flag.id, !flag.isEnabled);
      toast.success(flag.isEnabled ? 'تم تعطيل الميزة' : 'تم تفعيل الميزة');
      load();
    } catch (err) {
      toast.error('تعذر تحديث الميزة', err instanceof Error ? err.message : undefined);
    }
  };

  const openOverridesModal = (flag: PlatformFeatureFlag) => {
    setSelectedFeatureForOverrides(flag);
    try {
      const ovs = platformAdminService.listFeatureOverrides(flag.id);
      setFeatureOverrides(ovs);
      setNewOverrideTenantId('');
      setNewOverrideEnabled(true);
      setNewOverrideCustomRollout('');
    } catch (err) {
      toast.error('تعذر تحميل تخصيصات الميزة', err instanceof Error ? err.message : undefined);
    }
  };

  const addOverride = () => {
    if (!selectedFeatureForOverrides || !newOverrideTenantId) return;
    try {
      platformAdminService.setFeatureOverride({
        featureId: selectedFeatureForOverrides.id,
        targetType: 'TENANT',
        targetId: newOverrideTenantId,
        isEnabled: newOverrideEnabled,
        customRolloutPercent: newOverrideCustomRollout !== '' ? Number(newOverrideCustomRollout) : null,
      });
      toast.success('تمت إضافة التخصيص بنجاح');
      const ovs = platformAdminService.listFeatureOverrides(selectedFeatureForOverrides.id);
      setFeatureOverrides(ovs);
      setNewOverrideTenantId('');
      load();
    } catch (err) {
      toast.error('تعذر حفظ التخصيص', err instanceof Error ? err.message : undefined);
    }
  };

  const removeOverride = (overrideId: string) => {
    if (!selectedFeatureForOverrides) return;
    try {
      platformAdminService.removeFeatureOverride(overrideId);
      toast.success('تم حذف التخصيص');
      const ovs = platformAdminService.listFeatureOverrides(selectedFeatureForOverrides.id);
      setFeatureOverrides(ovs);
      load();
    } catch (err) {
      toast.error('تعذر حذف التخصيص', err instanceof Error ? err.message : undefined);
    }
  };

  // ─── Release Management ────────────────────────────────────────────────

  const openRelease = (release?: PlatformRelease) => {
    setReleaseForm(
      release
        ? {
            id: release.id,
            version: release.version,
            channel: release.channel,
            status: release.status ?? 'PUBLISHED',
            targetsSummary: release.targetsSummary ?? null,
            isMandatory: release.isMandatory ?? false,
            minVersion: release.minVersion ?? '',
            rolloutGroup: release.rolloutGroup || 'ALL',
            stagingGroup: release.stagingGroup || 'PRODUCTION',
            fileUrl: release.fileUrl ?? '',
            fileName: release.fileName ?? '',
            fileSize: release.fileSize != null ? String(release.fileSize) : '',
            checksumSha256: release.checksumSha256 ?? '',
            packageSignature: release.packageSignature ?? '',
            changelog: release.changelog ?? '',
            rollbackVersion: release.rollbackVersion ?? '',
            notes: release.notes ?? '',
            releasedAt: (release.releasedAt ?? release.createdAt).slice(0, 10),
          }
        : { ...emptyRelease }
    );
    setReleaseOpen(true);
  };

  const saveRelease = () => {
    setSaving(true);
    try {
      platformAdminService.upsertRelease({
        ...releaseForm,
        fileSize: releaseForm.fileSize !== '' ? Number(releaseForm.fileSize) : undefined,
        releasedAt: releaseForm.releasedAt ? new Date(releaseForm.releasedAt).toISOString() : undefined,
      });
      toast.success(releaseForm.id ? 'تم تحديث الإصدار وحزمته' : 'تم إنشاء الإصدار بنجاح');
      setReleaseOpen(false);
      load();
    } catch (err) {
      toast.error('تعذر حفظ الإصدار', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const openTargetsModal = (release: PlatformRelease) => {
    setSelectedReleaseForTargets(release);
    try {
      const targets = platformAdminService.listReleaseTargets(release.id);
      setReleaseTargets(targets);
      setSelectedTenantIdsForRelease(targets.map((t) => t.tenantId));
      setTargetSearchTerm('');
    } catch (err) {
      toast.error('تعذر استرجاع مستهدفي الإصدار', err instanceof Error ? err.message : undefined);
    }
  };

  const saveTargets = () => {
    if (!selectedReleaseForTargets) return;
    setSaving(true);
    try {
      const updated = platformAdminService.setReleaseTargets(selectedReleaseForTargets.id, selectedTenantIdsForRelease);
      setReleaseTargets(updated);
      toast.success(`تم إسناد الإصدار إلى ${selectedTenantIdsForRelease.length} عميل.`);
      load();
    } catch (err) {
      toast.error('تعذر تحديث مستهدفي الإصدار', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const markTargetStatus = (targetId: string, status: PlatformReleaseTarget['status']) => {
    if (!selectedReleaseForTargets) return;
    try {
      const target = releaseTargets.find((t) => t.id === targetId);
      if (!target) return;
      platformAdminService.updateReleaseTargetStatus(selectedReleaseForTargets.id, target.tenantId, status);
      toast.success('تم تحديث حالة العميل');
      setReleaseTargets(platformAdminService.listReleaseTargets(selectedReleaseForTargets.id));
      load();
    } catch (err) {
      toast.error('تعذر تحديث الحالة', err instanceof Error ? err.message : undefined);
    }
  };

  const openRollbackModal = (release: PlatformRelease) => {
    setRollbackReleaseItem(release);
    setSafeRollbackVersion(release.rollbackVersion || (release.minVersion ?? ''));
    setRollbackOpen(true);
  };

  const confirmRollback = () => {
    if (!rollbackReleaseItem || !safeRollbackVersion.trim()) return;
    setSaving(true);
    try {
      platformAdminService.rollbackRelease(rollbackReleaseItem.id, safeRollbackVersion.trim());
      toast.success(`تم التراجع عن الإصدار v${rollbackReleaseItem.version} وتوجيه العملاء للإصدار v${safeRollbackVersion}`);
      setRollbackOpen(false);
      load();
    } catch (err) {
      toast.error('تعذر التراجع عن الإصدار', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-4">
      <PageHeader
        title="التحكم في المنتج والمزايا (Product Control)"
        description="إدارة المزايا وFeature Flags وحزم التحديثات والـ Rollout والاستهداف الآمن."
        icon={<Boxes className="h-5 w-5" />}
        actions={
          tab === 'features' ? (
            canManageProduct ? (
              <Button variant="primary" size="sm" leadingIcon={<Plus className="h-3.5 w-3.5" />} onClick={() => openFeature()}>
                ميزة جديدة
              </Button>
            ) : null
          ) : tab === 'releases' ? (
            canManageProduct ? (
              <Button variant="primary" size="sm" leadingIcon={<Plus className="h-3.5 w-3.5" />} onClick={() => openRelease()}>
                إصدار / حزمة جديدة
              </Button>
            ) : null
          ) : undefined
        }
      />

      <div className="inline-flex rounded-lg bg-slate-100 p-1">
        {TABS.map((item) => {
          const Icon = item.icon;
          return (
            <button
              key={item.id}
              type="button"
              onClick={() => setTab(item.id)}
              className={`inline-flex items-center gap-1.5 rounded-md px-3 py-1.5 text-[12px] font-bold transition ${
                tab === item.id ? 'bg-white text-slate-900 shadow' : 'text-slate-500'
              }`}
            >
              <Icon className="h-3.5 w-3.5" />
              {item.label}
            </button>
          );
        })}
      </div>

      {error && (
        <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">
          {error}
        </div>
      )}

      {loading ? (
        <div className="rounded-xl border border-slate-200 bg-white py-16 text-center text-sm font-semibold text-slate-500 shadow-sm">
          جارٍ تحميل بيانات المنتج...
        </div>
      ) : tab === 'modules' ? (
        <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
          {modules.length === 0 ? (
            <EmptyState icon={<Boxes className="h-5 w-5" />} title="لا توجد وحدات" />
          ) : (
            <div className="divide-y divide-slate-100">
              {modules.map((module) => (
                <div key={module.id} className="flex items-center justify-between gap-3 px-4 py-3">
                  <div className="flex min-w-0 items-start gap-3">
                    <span
                      className={`mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${
                        module.isEnabled ? 'bg-emerald-50 text-emerald-600' : 'bg-slate-100 text-slate-400'
                      }`}
                    >
                      <BadgeCheck className="h-4 w-4" />
                    </span>
                    <div className="min-w-0">
                      <p className="flex flex-wrap items-center gap-2 text-[12.5px] font-bold text-slate-800">
                        {module.name}
                        <span className="font-mono text-[9.5px] font-normal text-slate-400" dir="ltr">
                          {module.code}
                        </span>
                      </p>
                      <p className="text-[10.5px] text-slate-500">{module.description || 'بدون وصف'}</p>
                      {module.minPlanCode && (
                        <p className="mt-0.5 text-[9.5px] font-semibold text-sky-600">الحد الأدنى: {module.minPlanCode}</p>
                      )}
                    </div>
                  </div>
                  <div className="flex shrink-0 items-center gap-2">
                    <span className={`text-[10.5px] font-bold ${module.isEnabled ? 'text-emerald-600' : 'text-slate-400'}`}>
                      {module.isEnabled ? 'مفعّلة' : 'معطّلة'}
                    </span>
                    <Toggle checked={module.isEnabled} onChange={() => toggleModule(module)} disabled={!canManageProduct} label={module.name} />
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      ) : tab === 'features' ? (
        <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
          {features.length === 0 ? (
            <EmptyState
              icon={<Sparkles className="h-5 w-5" />}
              title="لا توجد مزايا"
              description="أضف ميزة للتحكم في إتاحتها للمشتركين وتخصيص الـ Feature Flags."
            />
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full min-w-[900px] text-right">
                <thead className="bg-slate-50">
                  <tr className="text-[10.5px] text-slate-500">
                    <th className="px-4 py-2.5 font-semibold">الميزة والرمز</th>
                    <th className="px-4 py-2.5 font-semibold">الفئة</th>
                    <th className="px-4 py-2.5 font-semibold">نسبة الإتاحة والتجربة</th>
                    <th className="px-4 py-2.5 font-semibold">تخصيص العملاء</th>
                    <th className="px-4 py-2.5 font-semibold">الحالة</th>
                    <th className="px-4 py-2.5 font-semibold">إجراءات</th>
                  </tr>
                </thead>
                <tbody>
                  {features.map((flag) => (
                    <tr key={flag.id} className="border-t border-slate-100 hover:bg-slate-50/60">
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-1.5">
                          <p className="text-[12px] font-bold text-slate-800">{flag.name}</p>
                          {flag.isStagingOnly && (
                            <span className="rounded bg-amber-100 px-1.5 py-0.5 text-[9px] font-bold text-amber-800">
                              بيئة اختبار (Staging)
                            </span>
                          )}
                        </div>
                        <p className="font-mono text-[9.5px] text-slate-400" dir="ltr">
                          {flag.code}
                        </p>
                        {flag.description && <p className="text-[10px] text-slate-500">{flag.description}</p>}
                      </td>
                      <td className="px-4 py-2.5 text-[11px] text-slate-600">{flag.category || '—'}</td>
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-2">
                          <div className="h-1.5 w-20 overflow-hidden rounded-full bg-slate-200">
                            <div className="h-full rounded-full bg-sky-500" style={{ width: `${flag.rolloutPercent}%` }} />
                          </div>
                          <span className="text-[10.5px] font-semibold text-slate-600">{flag.rolloutPercent}%</span>
                        </div>
                      </td>
                      <td className="px-4 py-2.5">
                        <button
                          type="button"
                          onClick={() => openOverridesModal(flag)}
                          className="inline-flex items-center gap-1 rounded-md border border-slate-200 bg-white px-2 py-1 text-[11px] font-semibold text-slate-700 hover:bg-slate-50 hover:border-slate-300"
                        >
                          <Users className="h-3 w-3 text-sky-600" />
                          <span>{flag.overridesCount || 0} عملاء مخصصين</span>
                        </button>
                      </td>
                      <td className="px-4 py-2.5">
                        <span className={`text-[10.5px] font-bold ${flag.isEnabled ? 'text-emerald-600' : 'text-slate-400'}`}>
                          {flag.isEnabled ? 'مفعّلة' : 'معطّلة'}
                        </span>
                      </td>
                      <td className="px-4 py-2.5">
                        <div className="flex items-center gap-2">
                          <Toggle checked={flag.isEnabled} onChange={() => toggleFeature(flag)} disabled={!canManageProduct} label={flag.name} />
                          <button
                            type="button"
                            onClick={() => openFeature(flag)}
                            className="rounded p-1.5 text-slate-500 hover:bg-sky-50 hover:text-sky-700"
                            title="تعديل"
                          >
                            <Pencil className="h-3.5 w-3.5" />
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      ) : (
        <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
          {releases.length === 0 ? (
            <EmptyState icon={<Rocket className="h-5 w-5" />} title="لا توجد إصدارات" description="سجّل إصدارات المنتج لمتابعة النشر وحزم التحديثات." />
          ) : (
            <div className="divide-y divide-slate-100">
              {releases.map((release) => (
                <div key={release.id} className="flex flex-wrap items-center justify-between gap-3 px-4 py-3.5 hover:bg-slate-50/50">
                  <div className="flex min-w-0 items-start gap-3">
                    <span className="mt-0.5 flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-sky-50 text-sky-600">
                      <Rocket className="h-4 w-4" />
                    </span>
                    <div className="min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="text-[13px] font-bold text-slate-900" dir="ltr">
                          v{release.version}
                        </span>
                        <span className="rounded-full bg-slate-100 px-2 py-0.5 text-[9.5px] font-bold text-slate-600">
                          {CHANNEL_LABELS[release.channel]}
                        </span>
                        <StatusBadge value={release.status ?? ''} label={RELEASE_STATUS_LABELS[release.status ?? '']} />
                        {release.isMandatory && (
                          <span className="rounded bg-rose-50 border border-rose-200 px-1.5 py-0.5 text-[9.5px] font-bold text-rose-700">
                            تحديث إلزامي
                          </span>
                        )}
                        {release.stagingGroup && release.stagingGroup !== 'PRODUCTION' && (
                          <span className="rounded bg-amber-50 border border-amber-200 px-1.5 py-0.5 text-[9.5px] font-bold text-amber-700">
                            {release.stagingGroup}
                          </span>
                        )}
                      </div>

                      <p className="mt-0.5 text-[11px] text-slate-600">{release.notes || 'بدون ملاحظات'}</p>

                      {/* Package and Integrity info */}
                      <div className="mt-1.5 flex flex-wrap items-center gap-3 text-[10px] text-slate-500">
                        {release.fileName && (
                          <span className="inline-flex items-center gap-1 font-mono text-slate-700">
                            <FileCheck className="h-3 w-3 text-sky-600" /> {release.fileName}
                            {release.fileSize && <span>({(release.fileSize / (1024 * 1024)).toFixed(2)} MB)</span>}
                          </span>
                        )}
                        {release.checksumSha256 && (
                          <span className="inline-flex items-center gap-1 font-mono text-slate-500" title={`SHA-256: ${release.checksumSha256}`}>
                            <span className="font-semibold text-slate-700">SHA256:</span> {release.checksumSha256.slice(0, 10)}...
                          </span>
                        )}
                        {release.packageSignature && (
                          <span className="inline-flex items-center gap-1 text-emerald-600 font-semibold" title="الحزمة موقّعة رقمياً">
                            ✓ موقّع
                          </span>
                        )}
                        <span>{formatDate(release.releasedAt)}</span>
                      </div>

                      {/* Targets summary badges */}
                      {release.targetsSummary && release.targetsSummary.total > 0 && (
                        <div className="mt-2 flex items-center gap-2">
                          <span className="text-[10px] font-bold text-slate-600">متابعة التحديث:</span>
                          <span className="inline-flex items-center gap-1 rounded bg-slate-100 px-1.5 py-0.5 text-[9.5px] font-semibold text-slate-700">
                            الإجمالي: {release.targetsSummary.total}
                          </span>
                          <span className="inline-flex items-center gap-1 rounded bg-emerald-50 text-emerald-700 px-1.5 py-0.5 text-[9.5px] font-bold">
                            نجح: {release.targetsSummary.success}
                          </span>
                          {release.targetsSummary.failed > 0 && (
                            <span className="inline-flex items-center gap-1 rounded bg-rose-50 text-rose-700 px-1.5 py-0.5 text-[9.5px] font-bold">
                              فشل: {release.targetsSummary.failed}
                            </span>
                          )}
                          <span className="inline-flex items-center gap-1 rounded bg-amber-50 text-amber-700 px-1.5 py-0.5 text-[9.5px] font-bold">
                            انتظار: {release.targetsSummary.pending}
                          </span>
                        </div>
                      )}
                    </div>
                  </div>

                  <div className="flex items-center gap-2">
                    <Button
                      variant="secondary"
                      size="sm"
                      leadingIcon={<Users className="h-3.5 w-3.5 text-sky-600" />}
                      onClick={() => openTargetsModal(release)}
                    >
                      استهداف ومتابعة العملاء
                    </Button>
                    {release.status !== 'DEPRECATED' && (
                      <Button
                        variant="secondary"
                        size="sm"
                        className="text-amber-700 hover:bg-amber-50"
                        leadingIcon={<RotateCcw className="h-3.5 w-3.5" />}
                        onClick={() => openRollbackModal(release)}
                      >
                        تراجع طارئ
                      </Button>
                    )}
                    <button
                      type="button"
                      onClick={() => openRelease(release)}
                      className="rounded p-1.5 text-slate-500 hover:bg-sky-50 hover:text-sky-700"
                      title="تعديل الحزمة والبيانات"
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      )}

      {/* ─── Feature Modal ─── */}
      <Modal
        open={featureOpen}
        onClose={() => setFeatureOpen(false)}
        title={featureForm.id ? 'تعديل ميزة ومنطق التحكم' : 'ميزة جديدة'}
        size="md"
        busy={saving}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setFeatureOpen(false)} disabled={saving}>
              إلغاء
            </Button>
            <Button variant="primary" onClick={saveFeature} loading={saving} disabled={!canManageProduct}>
              حفظ
            </Button>
          </div>
        }
      >
        <div className="grid gap-3 sm:grid-cols-2">
          <Field label="اسم الميزة" required>
            <input className={inputClass} value={featureForm.name} onChange={(e) => setFeatureForm({ ...featureForm, name: e.target.value })} />
          </Field>
          <Field label="الرمز البرمجي (Code)" required hint={featureForm.id ? 'لا يمكن تعديل الرمز' : 'مثال: sales.quick_invoice'}>
            <input
              dir="ltr"
              className={inputClass}
              value={featureForm.code}
              disabled={Boolean(featureForm.id)}
              onChange={(e) => setFeatureForm({ ...featureForm, code: e.target.value.toLowerCase() })}
            />
          </Field>
          <Field label="الفئة (Category)">
            <input className={inputClass} value={featureForm.category} onChange={(e) => setFeatureForm({ ...featureForm, category: e.target.value })} />
          </Field>
          <Field label="نسبة الإتاحة العامة (%)">
            <input
              type="number"
              min={0}
              max={100}
              className={inputClass}
              value={featureForm.rolloutPercent}
              onChange={(e) => setFeatureForm({ ...featureForm, rolloutPercent: Number(e.target.value) })}
            />
          </Field>
          <Field label="الحد الأدنى لدرجة الخطة (Tier)">
            <input
              placeholder="مثال: PRO أو ENTERPRISE"
              className={inputClass}
              value={featureForm.minPlanTier}
              onChange={(e) => setFeatureForm({ ...featureForm, minPlanTier: e.target.value })}
            />
          </Field>
          <div className="flex items-center justify-between rounded-xl border border-slate-200 px-3 py-2">
            <div>
              <p className="text-[12px] font-bold text-slate-800">بيئة اختبار فقط (Staging)</p>
              <p className="text-[10px] text-slate-500">حصر الميزة لمجموعات الاختبار قبل الإطلاق العام.</p>
            </div>
            <Toggle checked={featureForm.isStagingOnly} onChange={(val) => setFeatureForm({ ...featureForm, isStagingOnly: val })} label="Staging" />
          </div>
          <Field label="الوصف التوضيحي" className="sm:col-span-2">
            <textarea rows={2} className={inputClass} value={featureForm.description} onChange={(e) => setFeatureForm({ ...featureForm, description: e.target.value })} />
          </Field>
        </div>
        <div className="mt-3 flex items-center justify-between rounded-xl border border-slate-200 px-3 py-2">
          <div>
            <p className="text-[12px] font-bold text-slate-800">تفعيل الميزة</p>
            <p className="text-[10.5px] text-slate-500">عند التعطيل لن تكون الميزة متاحة لأي مشترك إلا بتخصيص صريح.</p>
          </div>
          <Toggle checked={featureForm.isEnabled} onChange={(next) => setFeatureForm({ ...featureForm, isEnabled: next })} label="تفعيل الميزة" />
        </div>
      </Modal>

      {/* ─── Feature Overrides Modal (Tenant-specific Feature Flags) ─── */}
      <Modal
        open={Boolean(selectedFeatureForOverrides)}
        onClose={() => setSelectedFeatureForOverrides(null)}
        title={`تخصيص الميزة: ${selectedFeatureForOverrides?.name ?? ''}`}
        size="lg"
      >
        <div className="space-y-4">
          <div className="rounded-lg bg-sky-50 p-3 text-[11px] text-sky-800">
            يمكنك هنا فرض تفعيل أو حجب الميزة لعملاء محددين بغض النظر عن نسبة الإتاحة العامة للنظام.
          </div>

          {/* Add Override Form */}
          <div className="rounded-xl border border-slate-200 bg-slate-50/50 p-3">
            <p className="text-[11.5px] font-bold text-slate-800 mb-2">إضافة تخصيص لعميل جديد:</p>
            <div className="grid gap-2.5 sm:grid-cols-3">
              <div className="sm:col-span-2">
                <select className={inputClass} value={newOverrideTenantId} onChange={(e) => setNewOverrideTenantId(e.target.value)}>
                  <option value="">اختر العميل المستهدف...</option>
                  {tenants.map((t) => (
                    <option key={t.id} value={t.id}>
                      {t.name} ({t.code})
                    </option>
                  ))}
                </select>
              </div>
              <div className="flex items-center gap-2">
                <select
                  className={inputClass}
                  value={newOverrideEnabled ? '1' : '0'}
                  onChange={(e) => setNewOverrideEnabled(e.target.value === '1')}
                >
                  <option value="1">تفعيل إجباري</option>
                  <option value="0">حجب إجباري</option>
                </select>
                <Button variant="primary" size="sm" onClick={addOverride} disabled={!newOverrideTenantId || !canManageProduct}>
                  إضافة
                </Button>
              </div>
            </div>
          </div>

          {/* Overrides Table */}
          <div className="overflow-hidden rounded-xl border border-slate-200">
            {featureOverrides.length === 0 ? (
              <div className="py-8 text-center text-xs text-slate-500 font-semibold">
                لا توجد تخصيصات خاصة لهذه الميزة بعد. تنطبق عليها قواعد الإتاحة العامة.
              </div>
            ) : (
              <table className="w-full text-right text-[11px]">
                <thead className="bg-slate-50 text-slate-600 font-semibold border-b border-slate-200">
                  <tr>
                    <th className="px-3 py-2">العميل المستهدف</th>
                    <th className="px-3 py-2">الحالة المفروضة</th>
                    <th className="px-3 py-2">تاريخ التخصيص</th>
                    <th className="px-3 py-2">إجراء</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {featureOverrides.map((ov) => (
                    <tr key={ov.id} className="hover:bg-slate-50/50">
                      <td className="px-3 py-2 font-bold text-slate-800">{ov.targetName || ov.targetId}</td>
                      <td className="px-3 py-2">
                        <span
                          className={`inline-block rounded px-2 py-0.5 text-[10px] font-bold ${
                            ov.isEnabled ? 'bg-emerald-50 text-emerald-700' : 'bg-rose-50 text-rose-700'
                          }`}
                        >
                          {ov.isEnabled ? 'مفعّل دائماً' : 'محجوب تماماً'}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-slate-400">{formatDate(ov.createdAt)}</td>
                      <td className="px-3 py-2">
                        <button
                          type="button"
                          onClick={() => removeOverride(ov.id)}
                          className="rounded px-2 py-1 text-rose-600 hover:bg-rose-50 font-semibold"
                        >
                          حذف
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        </div>
      </Modal>

      {/* ─── Release Form Modal ─── */}
      <Modal
        open={releaseOpen}
        onClose={() => setReleaseOpen(false)}
        title={releaseForm.id ? `تعديل إصدار v${releaseForm.version}` : 'إصدار جديد وحزمة تحديث'}
        size="lg"
        busy={saving}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setReleaseOpen(false)} disabled={saving}>
              إلغاء
            </Button>
            <Button variant="primary" onClick={saveRelease} loading={saving} disabled={!canManageProduct}>
              حفظ الإصدار
            </Button>
          </div>
        }
      >
        <div className="grid gap-3 sm:grid-cols-3">
          <Field label="رقم الإصدار" required hint="مثال: 2.5.0">
            <input dir="ltr" className={inputClass} value={releaseForm.version} onChange={(e) => setReleaseForm({ ...releaseForm, version: e.target.value })} />
          </Field>
          <Field label="القناة (Channel)">
            <select className={inputClass} value={releaseForm.channel} onChange={(e) => setReleaseForm({ ...releaseForm, channel: e.target.value as PlatformRelease['channel'] })}>
              {Object.entries(CHANNEL_LABELS).map(([val, lbl]) => (
                <option key={val} value={val}>
                  {lbl}
                </option>
              ))}
            </select>
          </Field>
          <Field label="الحالة (Status)">
            <select className={inputClass} value={releaseForm.status} onChange={(e) => setReleaseForm({ ...releaseForm, status: e.target.value })}>
              {Object.entries(RELEASE_STATUS_LABELS).map(([val, lbl]) => (
                <option key={val} value={val}>
                  {lbl}
                </option>
              ))}
            </select>
          </Field>

          <Field label="النسخة الدنيا المطلوبة (Min Version)" hint="تمنع التخطي إذا كانت النسخة أقدم">
            <input dir="ltr" placeholder="مثال: 2.0.0" className={inputClass} value={releaseForm.minVersion} onChange={(e) => setReleaseForm({ ...releaseForm, minVersion: e.target.value })} />
          </Field>
          <Field label="بيئة النشر (Staging Group)">
            <select className={inputClass} value={releaseForm.stagingGroup} onChange={(e) => setReleaseForm({ ...releaseForm, stagingGroup: e.target.value })}>
              <option value="PRODUCTION">الإنتاج الكامل (Production)</option>
              <option value="CANARY">إطلاق تدريجي (Canary 10%)</option>
              <option value="BETA_TESTERS">مختبرو بيتا (Beta Testers)</option>
              <option value="INTERNAL">فريق العمل الداخلي (Internal)</option>
            </select>
          </Field>
          <Field label="تاريخ الإصدار">
            <input type="date" className={inputClass} value={releaseForm.releasedAt} onChange={(e) => setReleaseForm({ ...releaseForm, releasedAt: e.target.value })} />
          </Field>

          {/* Package details */}
          <div className="sm:col-span-3 rounded-xl border border-slate-200 bg-slate-50/50 p-3 space-y-3">
            <p className="text-[12px] font-bold text-slate-800 flex items-center gap-1.5">
              <FileCheck className="h-4 w-4 text-sky-600" /> بيانات ملف التثبيت والتوقيع والـ Checksum
            </p>
            <div className="grid gap-2.5 sm:grid-cols-2">
              <Field label="رابط تحميل الحزمة (URL)">
                <input dir="ltr" placeholder="https://releases.ceramisys.com/v2.5.0.exe" className={inputClass} value={releaseForm.fileUrl} onChange={(e) => setReleaseForm({ ...releaseForm, fileUrl: e.target.value })} />
              </Field>
              <Field label="اسم الملف (File Name)">
                <input dir="ltr" placeholder="Ceramisys-Setup-2.5.0.exe" className={inputClass} value={releaseForm.fileName} onChange={(e) => setReleaseForm({ ...releaseForm, fileName: e.target.value })} />
              </Field>
              <Field label="بصمة التجزئة SHA-256 Checksum" hint="للتحقق من سلامة الملف عند التنزيل">
                <input dir="ltr" placeholder="e.g. 5d41402abc4b2a76b9719d911017c592..." className={inputClass} value={releaseForm.checksumSha256} onChange={(e) => setReleaseForm({ ...releaseForm, checksumSha256: e.target.value })} />
              </Field>
              <Field label="التوقيع الرقمي للحزمة (Digital Signature)">
                <input dir="ltr" placeholder="ceramisys-signed-pkg-..." className={inputClass} value={releaseForm.packageSignature} onChange={(e) => setReleaseForm({ ...releaseForm, packageSignature: e.target.value })} />
              </Field>
              <Field label="حجم الملف بالبايت (Size in Bytes)">
                <input type="number" dir="ltr" placeholder="e.g. 85000000" className={inputClass} value={releaseForm.fileSize} onChange={(e) => setReleaseForm({ ...releaseForm, fileSize: e.target.value })} />
              </Field>
              <Field label="إصدار التراجع الآمن في الطوارئ (Rollback Target)">
                <input dir="ltr" placeholder="مثال: 2.4.9" className={inputClass} value={releaseForm.rollbackVersion} onChange={(e) => setReleaseForm({ ...releaseForm, rollbackVersion: e.target.value })} />
              </Field>
            </div>
          </div>

          <div className="sm:col-span-3 flex items-center justify-between rounded-xl border border-slate-200 px-3 py-2 bg-white">
            <div>
              <p className="text-[12px] font-bold text-slate-800">تحديث إلزامي (Mandatory Enforcement)</p>
              <p className="text-[10px] text-slate-500">منع متابعة العمل على النسخ السابقة حتى إتمام ترقية العميل.</p>
            </div>
            <Toggle checked={releaseForm.isMandatory} onChange={(val) => setReleaseForm({ ...releaseForm, isMandatory: val })} label="إلزامي" />
          </div>

          <Field label="سجل التغييرات الكامل (Changelog)" className="sm:col-span-3">
            <textarea rows={3} placeholder="ما الجديد في هذا الإصدار..." className={inputClass} value={releaseForm.changelog} onChange={(e) => setReleaseForm({ ...releaseForm, changelog: e.target.value })} />
          </Field>
          <Field label="ملاحظات داخلية" className="sm:col-span-3">
            <textarea rows={2} className={inputClass} value={releaseForm.notes} onChange={(e) => setReleaseForm({ ...releaseForm, notes: e.target.value })} />
          </Field>
        </div>
      </Modal>

      {/* ─── Release Targets & Tracking Modal ─── */}
      <Modal
        open={Boolean(selectedReleaseForTargets)}
        onClose={() => setSelectedReleaseForTargets(null)}
        title={`استهداف ومتابعة تحديث الإصدار v${selectedReleaseForTargets?.version ?? ''}`}
        size="lg"
        busy={saving}
        footer={
          <div className="flex justify-between items-center w-full">
            <span className="text-[11px] font-semibold text-slate-500">
              تم تحديد {selectedTenantIdsForRelease.length} من أصل {tenants.length} عميل.
            </span>
            <div className="flex gap-2">
              <Button variant="ghost" onClick={() => setSelectedReleaseForTargets(null)} disabled={saving}>
                إغلاق
              </Button>
              <Button variant="primary" onClick={saveTargets} loading={saving} disabled={!canManageProduct}>
                حفظ المستهدفين
              </Button>
            </div>
          </div>
        }
      >
        <div className="space-y-4">
          <div className="flex items-center justify-between gap-3 bg-slate-50 p-2.5 rounded-lg border border-slate-200">
            <div className="relative flex-1">
              <Search className="absolute right-2.5 top-2.5 h-3.5 w-3.5 text-slate-400" />
              <input
                className={`${inputClass} pr-8 text-xs`}
                placeholder="بحث عن عميل..."
                value={targetSearchTerm}
                onChange={(e) => setTargetSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => setSelectedTenantIdsForRelease(tenants.map((t) => t.id))}
                className="rounded bg-white border border-slate-200 px-2.5 py-1 text-[11px] font-semibold text-slate-700 hover:bg-slate-100"
              >
                تحديد الكل
              </button>
              <button
                type="button"
                onClick={() => setSelectedTenantIdsForRelease([])}
                className="rounded bg-white border border-slate-200 px-2.5 py-1 text-[11px] font-semibold text-slate-700 hover:bg-slate-100"
              >
                إلغاء التحديد
              </button>
            </div>
          </div>

          <div className="max-h-[380px] overflow-y-auto divide-y divide-slate-100 rounded-xl border border-slate-200">
            {tenants
              .filter(
                (t) =>
                  !targetSearchTerm ||
                  t.name.toLowerCase().includes(targetSearchTerm.toLowerCase()) ||
                  t.code.toLowerCase().includes(targetSearchTerm.toLowerCase())
              )
              .map((tenant) => {
                const isSelected = selectedTenantIdsForRelease.includes(tenant.id);
                const targetRecord = releaseTargets.find((r) => r.tenantId === tenant.id);
                const statusMeta = targetRecord ? TARGET_STATUS_LABELS[targetRecord.status] : null;

                return (
                  <div
                    key={tenant.id}
                    className={`flex items-center justify-between p-3 transition ${
                      isSelected ? 'bg-sky-50/40' : 'hover:bg-slate-50/60'
                    }`}
                  >
                    <div className="flex items-center gap-3">
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={(e) => {
                          if (e.target.checked) {
                            setSelectedTenantIdsForRelease([...selectedTenantIdsForRelease, tenant.id]);
                          } else {
                            setSelectedTenantIdsForRelease(selectedTenantIdsForRelease.filter((id) => id !== tenant.id));
                          }
                        }}
                        className="h-4 w-4 rounded border-slate-300 text-sky-600 focus:ring-sky-500"
                      />
                      <div>
                        <p className="text-[12px] font-bold text-slate-800">{tenant.name}</p>
                        <p className="font-mono text-[9.5px] text-slate-400" dir="ltr">
                          {tenant.code} — {tenant.businessType || 'عام'}
                        </p>
                      </div>
                    </div>

                    <div className="flex items-center gap-3">
                      {targetRecord && statusMeta ? (
                        <div className="flex items-center gap-2">
                          <span
                            className={`inline-flex items-center gap-1 rounded-full border px-2 py-0.5 text-[9.5px] font-bold ${statusMeta.color}`}
                          >
                            <statusMeta.icon className="h-3 w-3" />
                            {statusMeta.label}
                          </span>
                          {targetRecord.error && (
                            <span className="text-[9.5px] text-rose-600 max-w-[150px] truncate" title={targetRecord.error}>
                              {targetRecord.error}
                            </span>
                          )}
                          <select
                            className="rounded border border-slate-200 text-[10px] p-1 bg-white"
                            value={targetRecord.status}
                            onChange={(e) => markTargetStatus(targetRecord.id, e.target.value as PlatformReleaseTarget['status'])}
                          >
                            <option value="PENDING">قيد الانتظار</option>
                            <option value="SUCCESS">نجح التحديث</option>
                            <option value="FAILED">فشل</option>
                            <option value="SKIPPED">تخطي</option>
                          </select>
                        </div>
                      ) : (
                        <span className="text-[10px] text-slate-400">غير مدرج بالتحديث</span>
                      )}
                    </div>
                  </div>
                );
              })}
          </div>
        </div>
      </Modal>

      {/* ─── Rollback Modal ─── */}
      <Modal
        open={rollbackOpen}
        onClose={() => setRollbackOpen(false)}
        title="تراجع طارئ عن الإصدار (Emergency Rollback)"
        size="md"
        busy={saving}
        footer={
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={() => setRollbackOpen(false)} disabled={saving}>
              إلغاء
            </Button>
            <Button variant="danger" onClick={confirmRollback} loading={saving} disabled={!canManageProduct}>
              تأكيد التراجع الآن
            </Button>
          </div>
        }
      >
        <div className="space-y-3">
          <div className="flex items-start gap-3 rounded-xl border border-rose-200 bg-rose-50 p-3 text-rose-800">
            <ShieldAlert className="h-5 w-5 shrink-0 mt-0.5 text-rose-600" />
            <div className="text-[11.5px] leading-relaxed">
              <p className="font-bold">تحذير أمان عالي:</p>
              سيؤدي هذا الإجراء إلى إيقاف الإصدار <span className="font-mono font-bold">v{rollbackReleaseItem?.version}</span> فوراً
              وتحويل حالته إلى متوقف (DEPRECATED)، وتوجيه أجهزة العملاء المستهدفة للرجوع للنسخة الآمنة.
            </div>
          </div>

          <Field label="رقم الإصدار الآمن المراد الرجوع إليه" required>
            <input
              dir="ltr"
              placeholder="مثال: 2.4.9"
              className={inputClass}
              value={safeRollbackVersion}
              onChange={(e) => setSafeRollbackVersion(e.target.value)}
            />
          </Field>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformProductPage;

import React, { useState, useEffect, useCallback } from 'react';
import {
  Boxes,
  Package,
  UploadCloud,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  RotateCcw,
  Ban,
  Download,
  Users,
  Search,
  ExternalLink,
  ShieldAlert,
  Plus,
  FileCode,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformRelease,
  PlatformReleaseTarget,
  PlatformTenant,
} from '../../services/domains/platform/platformTypes';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import {
  EmptyState,
  StatusBadge,
  formatDateTime,
  inputClass,
} from './components/PlatformUI';

const emptyRelease: PlatformRelease = {
  id: '',
  version: '',
  channel: 'STABLE',
  status: 'PUBLISHED',
  isMandatory: false,
  minVersion: '1.0.0',
  rolloutGroup: 'ALL',
  notes: '',
  fileUrl: '',
  fileName: '',
  checksumSha256: '',
  changelog: '',
  createdAt: '',
  updatedAt: '',
};

export const PlatformReleasesPage: React.FC = () => {
  const [releases, setReleases] = useState<PlatformRelease[]>([]);
  const [tenants, setTenants] = useState<PlatformTenant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Targets Modal
  const [activeReleaseForTargets, setActiveReleaseForTargets] = useState<PlatformRelease | null>(null);
  const [targets, setTargets] = useState<PlatformReleaseTarget[]>([]);
  const [selectedTenantIds, setSelectedTenantIds] = useState<string[]>([]);
  const [targetsLoading, setTargetsLoading] = useState(false);

  // Upsert Release Modal
  const [isUpsertOpen, setIsUpsertOpen] = useState(false);
  const [releaseForm, setReleaseForm] = useState<PlatformRelease>({ ...emptyRelease });

  const canManageReleases = canPlatform('releases');

  const loadData = useCallback(() => {
    setLoading(true);
    try {
      const rels = platformAdminService.listReleases();
      const tens = platformAdminService.listTenants();
      setReleases(rels);
      setTenants(tens);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل إصدارات المنصة.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleOpenTargets = (rel: PlatformRelease) => {
    setActiveReleaseForTargets(rel);
    setTargetsLoading(true);
    try {
      const list = platformAdminService.listReleaseTargets(rel.id);
      setTargets(list);
      setSelectedTenantIds(list.map((t) => t.tenantId));
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تحميل أهداف الإصدار.');
    } finally {
      setTargetsLoading(false);
    }
  };

  const handleSaveTargets = () => {
    if (!activeReleaseForTargets) return;
    if (!canManageReleases) {
      alert('لا تملك صلاحية إدارة الإصدارات.');
      return;
    }
    try {
      platformAdminService.setReleaseTargets(activeReleaseForTargets.id, selectedTenantIds);
      setActiveReleaseForTargets(null);
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشل تحديث أهداف العملاء.');
    }
  };

  const handleDisableRelease = (id: string) => {
    if (!canManageReleases) {
      alert('لا تملك صلاحية إدارة الإصدارات.');
      return;
    }
    if (!confirm('هل أنت متأكد من تعطيل/إيقاف هذا الإصدار لمنع تحميله أو استخدامه؟')) return;
    try {
      platformAdminService.disableRelease(id);
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تعطيل الإصدار.');
    }
  };

  const handleRollback = (rel: PlatformRelease) => {
    if (!canManageReleases) {
      alert('لا تملك صلاحية إدارة الإصدارات.');
      return;
    }
    const safeVer = prompt(`أدخل الإصدار الآمن الذي ترغب في التراجع الطارئ إليه (الإصدار الحالي: ${rel.version}):`);
    if (!safeVer || !safeVer.trim()) return;
    try {
      platformAdminService.rollbackRelease(rel.id, safeVer.trim());
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تنفيذ التراجع الطارئ.');
    }
  };

  const handleSaveRelease = () => {
    if (!canManageReleases) {
      alert('لا تملك صلاحية إدارة الإصدارات.');
      return;
    }
    if (!releaseForm.version.trim()) {
      alert('رقم الإصدار مطلوب.');
      return;
    }
    try {
      platformAdminService.upsertRelease(releaseForm);
      setIsUpsertOpen(false);
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشل حفظ الإصدار.');
    }
  };

  return (
    <div className="space-y-4 text-right">
      <PageHeader
        title="إدارة الإصدارات والتحديثات المركزية (Releases & Rollout)"
        description="إدارة حزم التحديث، التوزيع التدريجي على العملاء، التوقيعات الرقمية، والتراجع الطارئ عند حدوث أخطاء."
        icon={<Boxes className="h-5 w-5" />}
        actions={
          canManageReleases ? (
            <Button
              size="sm"
              onClick={() => {
                setReleaseForm({ ...emptyRelease });
                setIsUpsertOpen(true);
              }}
              leadingIcon={<Plus className="h-4 w-4" />}
            >
              إضافة إصدار جديد
            </Button>
          ) : null
        }
      />

      {error && (
        <div className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-lg text-xs font-bold text-rose-300">
          {error}
        </div>
      )}

      {/* Releases Table */}
      <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
        {loading ? (
          <div className="py-16 text-center text-sm font-semibold text-slate-500">جارٍ تحميل الإصدارات...</div>
        ) : releases.length === 0 ? (
          <EmptyState
            icon={<Package className="h-6 w-6 text-slate-500" />}
            title="لا توجد حزم أو إصدارات"
            description="أنشئ أول إصدار للنظام لتوزيعه على العملاء والتحكم في دورات التحديث."
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[950px] text-right text-xs">
              <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                <tr>
                  <th className="px-4 py-3">الإصدار / القناة</th>
                  <th className="px-4 py-3">الحالة</th>
                  <th className="px-4 py-3">إجباري / الحد الأدنى</th>
                  <th className="px-4 py-3">مجموعة التوزيع</th>
                  <th className="px-4 py-3">نتائج التطبيق (Targets)</th>
                  <th className="px-4 py-3">تاريخ النشر</th>
                  <th className="px-4 py-3 text-center">إجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {releases.map((rel) => {
                  const summary = rel.targetsSummary || { total: 0, pending: 0, success: 0, failed: 0 };
                  return (
                    <tr key={rel.id} className="hover:bg-slate-800/30 transition-colors">
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2">
                          <span className="font-mono font-bold text-slate-100 text-sm">{rel.version}</span>
                          <span
                            className={`rounded px-1.5 py-0.5 text-[9px] font-black ${
                              rel.channel === 'STABLE'
                                ? 'bg-emerald-500/20 text-emerald-300'
                                : rel.channel === 'HOTFIX'
                                ? 'bg-rose-500/20 text-rose-300'
                                : 'bg-amber-500/20 text-amber-300'
                            }`}
                          >
                            {rel.channel}
                          </span>
                        </div>
                        {rel.notes && <p className="text-[11px] text-slate-400 mt-0.5">{rel.notes}</p>}
                      </td>

                      <td className="px-4 py-3">
                        <span
                          className={`font-bold inline-flex items-center gap-1 ${
                            rel.status === 'PUBLISHED'
                              ? 'text-emerald-400'
                              : rel.status === 'DEPRECATED'
                              ? 'text-rose-400'
                              : 'text-slate-400'
                          }`}
                        >
                          {rel.status === 'PUBLISHED' ? 'منشور (نشط)' : rel.status === 'DEPRECATED' ? 'معطّل/ملغي' : 'مسودة'}
                        </span>
                        {rel.rollbackVersion && (
                          <div className="text-[10px] text-amber-400 mt-0.5">
                            تراجع إلى: {rel.rollbackVersion}
                          </div>
                        )}
                      </td>

                      <td className="px-4 py-3">
                        <div>{rel.isMandatory ? <span className="text-rose-400 font-bold">إجباري</span> : 'اختياري'}</div>
                        <div className="text-[10px] text-slate-500">أدنى: {rel.minVersion || 'لا يوجد'}</div>
                      </td>

                      <td className="px-4 py-3">
                        <span className="font-mono text-slate-300 bg-slate-800 px-2 py-0.5 rounded text-[10px]">
                          {rel.rolloutGroup}
                        </span>
                      </td>

                      <td className="px-4 py-3">
                        <div className="flex items-center gap-2 text-[11px]">
                          <span className="text-emerald-400 font-bold" title="ناجح">{summary.success}✓</span>
                          <span className="text-amber-400 font-bold" title="قيد الانتظار">{summary.pending}⌛</span>
                          {summary.failed > 0 && (
                            <span className="text-rose-400 font-bold" title="فشل">{summary.failed}✗</span>
                          )}
                          <span className="text-slate-500 text-[10px]">({summary.total} عميل)</span>
                        </div>
                      </td>

                      <td className="px-4 py-3 text-slate-400">{formatDateTime(rel.createdAt)}</td>

                      <td className="px-4 py-3 text-center">
                        <div className="flex items-center justify-center gap-2">
                          <button
                            onClick={() => handleOpenTargets(rel)}
                            className="text-sky-400 hover:text-sky-300 text-xs flex items-center gap-1"
                            title="تحديد أو فحص العملاء المستهدفين"
                          >
                            <Users className="h-3.5 w-3.5" />
                            العملاء
                          </button>

                          {rel.status !== 'DEPRECATED' && canManageReleases && (
                            <>
                              <button
                                onClick={() => handleDisableRelease(rel.id)}
                                className="text-rose-400 hover:text-rose-300 text-xs"
                                title="تعطيل فوري للإصدار"
                              >
                                تعطيل
                              </button>
                              <button
                                onClick={() => handleRollback(rel)}
                                className="text-amber-400 hover:text-amber-300 text-xs flex items-center gap-1"
                                title="تراجع طارئ"
                              >
                                <RotateCcw className="h-3 w-3" />
                                تراجع
                              </button>
                            </>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal: Release Targets */}
      <Modal
        open={Boolean(activeReleaseForTargets)}
        onClose={() => setActiveReleaseForTargets(null)}
        title={`العملاء المستهدفون للإصدار ${activeReleaseForTargets?.version || ''}`}
      >
        <div className="space-y-4 text-right">
          <p className="text-xs text-slate-400">
            حدد العملاء الذين سيتم طرح وتطبيق هذا الإصدار عليهم، أو راقب حالة تطبيق التحديث:
          </p>

          <div className="max-h-60 overflow-y-auto space-y-1.5 border border-slate-800 p-2 rounded-lg bg-slate-950/40">
            {tenants.map((t) => {
              const checked = selectedTenantIds.includes(t.id);
              const targetStatus = targets.find((tgt) => tgt.tenantId === t.id);
              return (
                <label
                  key={t.id}
                  className="flex items-center justify-between p-2 rounded hover:bg-slate-800/40 cursor-pointer text-xs"
                >
                  <div className="flex items-center gap-2">
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setSelectedTenantIds([...selectedTenantIds, t.id]);
                        } else {
                          setSelectedTenantIds(selectedTenantIds.filter((id) => id !== t.id));
                        }
                      }}
                      className="rounded border-slate-700 text-sky-500 focus:ring-sky-500"
                    />
                    <span className="font-bold text-slate-200">{t.name}</span>
                    <span className="font-mono text-[10px] text-slate-500">({t.code})</span>
                  </div>

                  {targetStatus && (
                    <span
                      className={`text-[10px] font-bold ${
                        targetStatus.status === 'SUCCESS'
                          ? 'text-emerald-400'
                          : targetStatus.status === 'FAILED'
                          ? 'text-rose-400'
                          : 'text-amber-400'
                      }`}
                    >
                      {targetStatus.status}
                    </span>
                  )}
                </label>
              );
            })}
          </div>

          <div className="flex justify-between items-center pt-3 border-t border-slate-800">
            <span className="text-xs text-slate-400">
              تم تحديد {selectedTenantIds.length} من أصل {tenants.length} عميل
            </span>
            <div className="flex gap-2">
              <Button variant="secondary" size="sm" onClick={() => setActiveReleaseForTargets(null)}>
                إغلاق
              </Button>
              <Button size="sm" onClick={handleSaveTargets} disabled={!canManageReleases}>
                حفظ التعيين والنشر
              </Button>
            </div>
          </div>
        </div>
      </Modal>

      {/* Modal: New / Edit Release */}
      <Modal
        open={isUpsertOpen}
        onClose={() => setIsUpsertOpen(false)}
        title="إنشاء أو تحديث حزمة إصدار"
      >
        <div className="space-y-3 text-right">
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">رقم الإصدار (SemVer) *</label>
              <input
                type="text"
                value={releaseForm.version}
                onChange={(e) => setReleaseForm({ ...releaseForm, version: e.target.value })}
                placeholder="2.1.0"
                className={inputClass}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">قناة الإصدار</label>
              <select
                value={releaseForm.channel}
                onChange={(e) => setReleaseForm({ ...releaseForm, channel: e.target.value as any })}
                className={inputClass}
              >
                <option value="STABLE">مستقر (STABLE)</option>
                <option value="HOTFIX">إصلاح طارئ (HOTFIX)</option>
                <option value="BETA">تجريبي (BETA)</option>
                <option value="ALPHA">داخلي (ALPHA)</option>
              </select>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">رابط تحميل الحزمة (URL)</label>
              <input
                type="text"
                value={releaseForm.fileUrl ?? ''}
                onChange={(e) => setReleaseForm({ ...releaseForm, fileUrl: e.target.value })}
                placeholder="https://releases.ceramisys.com/v2.1.0.tar.gz"
                className={inputClass}
              />
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">بصمة التحقق SHA256</label>
              <input
                type="text"
                value={releaseForm.checksumSha256 ?? ''}
                onChange={(e) => setReleaseForm({ ...releaseForm, checksumSha256: e.target.value })}
                placeholder="hash..."
                className={inputClass}
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">ملاحظات الإصدار / التغييرات</label>
            <textarea
              rows={3}
              value={releaseForm.changelog ?? ''}
              onChange={(e) => setReleaseForm({ ...releaseForm, changelog: e.target.value })}
              placeholder="تفاصيل التحديث والميزات الجديدة..."
              className={inputClass}
            />
          </div>

          <div>
            <label className="flex items-center gap-2 cursor-pointer text-xs text-slate-300 mt-1">
              <input
                type="checkbox"
                checked={releaseForm.isMandatory ?? false}
                onChange={(e) => setReleaseForm({ ...releaseForm, isMandatory: e.target.checked })}
                className="rounded border-slate-700 text-sky-500 focus:ring-sky-500"
              />
              <span>تحديث إجباري (يمنع العمل على الإصدارات الأقدم)</span>
            </label>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsUpsertOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleSaveRelease} disabled={!canManageReleases}>
              نشر الإصدار
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformReleasesPage;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  ShieldAlert,
  ShieldCheck,
  Shield,
  Lock,
  Unlock,
  Key,
  KeyRound,
  RotateCcw,
  AlertTriangle,
  CheckCircle2,
  XCircle,
  Clock,
  RefreshCw,
  LogOut,
  Smartphone,
  Laptop,
  Globe,
  Radio,
  FileWarning,
  Flame,
  Zap,
  Server,
  Layers,
  Search,
  Plus,
  Copy,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformCentralSecurityOverview,
  PlatformStaffSession,
  PlatformStaffLogin,
  PlatformCentralSecurityIncident,
  PlatformSigningKey,
  PlatformApiKey,
  PlatformTenant,
} from '../../services/domains/platform/platformTypes';
import type { PlatformOwnerAuditEntry } from '../../services/domains/platform/PlatformBootstrapService';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import {
  EmptyState,
  StatusBadge,
  formatDateTime,
  inputClass,
} from './components/PlatformUI';

type SecurityTab = 'OVERVIEW' | 'SESSIONS' | 'LOGINS' | 'KEYS' | 'INCIDENTS';

export const PlatformSecurityCenterPage: React.FC = () => {
  const [tab, setTab] = useState<SecurityTab>('OVERVIEW');
  const [data, setData] = useState<PlatformCentralSecurityOverview | null>(null);
  const [apiKeys, setApiKeys] = useState<PlatformApiKey[]>([]);
  const [tenants, setTenants] = useState<PlatformTenant[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [ownerAccounts, setOwnerAccounts] = useState<PlatformOwnerAuditEntry[]>([]);

  // Filters
  const [loginFilterFailed, setLoginFilterFailed] = useState(false);
  const [loginSearch, setLoginSearch] = useState('');

  // API Key Modals & States
  const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState(false);
  const [newKeyResult, setNewKeyResult] = useState<{ plainTextKey: string; key: PlatformApiKey } | null>(null);
  const [apiKeyForm, setApiKeyForm] = useState<{
    tenantId: string;
    name: string;
    scopes: string[];
    expiresAt: string;
  }>({
    tenantId: '',
    name: '',
    scopes: ['read', 'write'],
    expiresAt: '',
  });

  // Modals
  const [isIncidentModalOpen, setIsIncidentModalOpen] = useState(false);
  const [incidentForm, setIncidentForm] = useState<{
    type: string;
    severity: 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW';
    title: string;
    details: string;
    sourceIp: string;
  }>({
    type: 'SUSPICIOUS_TRAFFIC',
    severity: 'HIGH',
    title: '',
    details: '',
    sourceIp: '',
  });

  // Load Security Overview
  const canManageSecurity = canPlatform('security-center');

  const loadSecurity = useCallback(() => {
    setLoading(true);
    try {
      const overview = platformAdminService.getPlatformSecurityOverview();
      const keys = platformAdminService.listApiKeys();
      const tenantList = platformAdminService.listTenants();
      setData(overview);
      setApiKeys(keys);
      setTenants(tenantList);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل مركز الأمان.');
    } finally {
      // The owner-account audit is owner-only; a non-owner simply does not see it.
      try {
        setOwnerAccounts(platformAdminService.auditPlatformOwnerAccounts());
      } catch {
        setOwnerAccounts([]);
      }
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadSecurity();
  }, [loadSecurity]);

  // Revoke Single Session
  const handleRevokeSession = (sessionId: string) => {
    if (!confirm('هل أنت متأكد من رغبتك في إنهاء هذه الجلسة عن بعد؟')) return;
    try {
      platformAdminService.revokeStaffSession(sessionId);
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر إنهاء الجلسة.');
    }
  };

  // Revoke All Other Sessions
  const handleRevokeAllOtherSessions = () => {
    if (!confirm('تأكيد: سيتم تسجيل خروج كافة الموظفين من جلساتهم المفتوحة فوراً!')) return;
    try {
      platformAdminService.revokeAllOtherStaffSessions();
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشلت العملية.');
    }
  };

  // Rotate Signing Key
  const handleRotateKey = (keyAlias: string) => {
    if (!confirm(`هل أنت متأكد من تدوير مفتاح التوقيع (${keyAlias})؟`)) return;
    try {
      platformAdminService.rotatePlatformSigningKey(keyAlias);
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تدوير المفتاح.');
    }
  };

  // Revoke API Key
  const handleRevokeApiKey = (id: string) => {
    if (!confirm('هل أنت متأكد من إلغاء مفتاح الـ API هذا؟')) return;
    try {
      platformAdminService.revokeApiKey(id);
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر إلغاء المفتاح.');
    }
  };

  // Rotate API Key
  const handleRotateApiKey = (id: string) => {
    if (!confirm('هل أنت متأكد من تدوير هذا المفتاح؟ سيتم إلغاء المفتاح الحالي فوراً وتوليد مفتاح جديد بنفس الصلاحيات.')) return;
    try {
      const res = platformAdminService.rotateApiKey(id);
      setNewKeyResult(res);
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر تدوير مفتاح الـ API.');
    }
  };

  // Create API Key
  const handleCreateApiKey = () => {
    if (!apiKeyForm.name.trim()) {
      alert('اسم المفتاح مطلوب.');
      return;
    }
    const tenantTarget = apiKeyForm.tenantId || (tenants[0]?.id ?? '');
    if (!tenantTarget) {
      alert('يجب اختيار العميل أو توفير عميل مسجل أولاً.');
      return;
    }
    try {
      const res = platformAdminService.createApiKey({
        tenantId: tenantTarget,
        name: apiKeyForm.name.trim(),
        scopes: apiKeyForm.scopes,
        expiresAt: apiKeyForm.expiresAt || undefined,
      });
      setIsApiKeyModalOpen(false);
      setNewKeyResult(res);
      setApiKeyForm({
        tenantId: tenants[0]?.id ?? '',
        name: '',
        scopes: ['read', 'write'],
        expiresAt: '',
      });
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشل إنشاء مفتاح الـ API.');
    }
  };

  // Create Incident
  const handleCreateIncident = () => {
    if (!incidentForm.title.trim()) {
      alert('عنوان الحادث مطلوب.');
      return;
    }
    try {
      platformAdminService.recordSecurityIncident(incidentForm);
      setIsIncidentModalOpen(false);
      setIncidentForm({
        type: 'SUSPICIOUS_TRAFFIC',
        severity: 'HIGH',
        title: '',
        details: '',
        sourceIp: '',
      });
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشل تسجيل الحادث.');
    }
  };

  // Contain/Resolve Incident
  const handleRespondIncident = (id: string, resolve: boolean) => {
    const action = prompt(
      resolve
        ? 'أدخل ملخص الإجراء النهائي لحل الحادث الأمني وإغلاقه:'
        : 'أدخل إجراء الاحتواء الأمني المتخذ فوراً:'
    );
    if (!action) return;
    try {
      platformAdminService.respondToSecurityIncident(id, action, resolve);
      loadSecurity();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشلت الاستجابة.');
    }
  };

  // Filtered Logins
  const filteredLogins = useMemo(() => {
    if (!data) return [];
    return data.recentLogins.filter((l) => {
      if (loginFilterFailed && l.status === 'SUCCESS') return false;
      if (
        loginSearch &&
        !l.email.toLowerCase().includes(loginSearch.toLowerCase()) &&
        !(l.ipAddress || '').includes(loginSearch)
      ) {
        return false;
      }
      return true;
    });
  }, [data, loginFilterFailed, loginSearch]);

  if (error) {
    return (
      <div role="alert" className="rounded-xl border border-rose-800 bg-rose-950/40 p-5 text-rose-200">
        <div className="flex items-center gap-2">
          <AlertTriangle className="h-6 w-6 text-rose-400" />
          <span className="font-bold">{error}</span>
        </div>
      </div>
    );
  }

  if (loading || !data) {
    return (
      <div className="flex min-h-[400px] items-center justify-center">
        <div className="flex items-center gap-3 text-slate-400">
          <RefreshCw className="h-5 w-5 animate-spin text-emerald-400" />
          <span>جارٍ فحص وتحليل الحالة الأمنية المركزية للمنصة...</span>
        </div>
      </div>
    );
  }

  const isScoreHigh = data.securityScore >= 85;
  const isScoreMedium = data.securityScore >= 65 && data.securityScore < 85;

  return (
    <div className="space-y-5">
      {/* Page Header */}
      <PageHeader
        title="مركز الأمان المركزي (Central Security Center)"
        description="المراقبة الأمنية لمسؤولي المنصة، رصد محاولات الاختراق، إدارة الجلسات ومفاتيح التوقيع الرقمي، والاستجابة للطوارئ."
        icon={<ShieldCheck className="h-6 w-6 text-emerald-400" />}
        actions={
          <div className="flex items-center gap-2">
            <Button
              variant="secondary"
              size="sm"
              onClick={loadSecurity}
              leadingIcon={<RefreshCw className="h-3.5 w-3.5" />}
            >
              تحديث
            </Button>
            <Button
              variant="danger"
              size="sm"
              onClick={handleRevokeAllOtherSessions}
              disabled={!canManageSecurity}
              leadingIcon={<Flame className="h-3.5 w-3.5" />}
            >
              إنهاء كافة الجلسات النشطة
            </Button>
          </div>
        }
      />

      {/* Hero: Central Security Posture Score Card */}
      <section
        className={`relative overflow-hidden rounded-2xl border p-6 shadow-xl ${
          isScoreHigh
            ? 'border-emerald-800/60 bg-gradient-to-br from-slate-900 via-slate-900 to-emerald-950 text-white'
            : isScoreMedium
            ? 'border-amber-800/60 bg-gradient-to-br from-slate-900 via-slate-900 to-amber-950 text-white'
            : 'border-rose-800/60 bg-gradient-to-br from-slate-900 via-slate-900 to-rose-950 text-white'
        }`}
      >
        <div className="relative z-10 flex flex-col gap-6 lg:flex-row lg:items-center lg:justify-between">
          <div className="space-y-2">
            <div className="flex items-center gap-2">
              <span
                className={`inline-flex items-center gap-1.5 rounded-full px-3 py-1 text-xs font-bold border ${
                  isScoreHigh
                    ? 'bg-emerald-500/20 text-emerald-300 border-emerald-500/30'
                    : isScoreMedium
                    ? 'bg-amber-500/20 text-amber-300 border-amber-500/30'
                    : 'bg-rose-500/20 text-rose-300 border-rose-500/30'
                }`}
              >
                {isScoreHigh ? (
                  <CheckCircle2 className="h-3.5 w-3.5" />
                ) : (
                  <AlertTriangle className="h-3.5 w-3.5" />
                )}
                {isScoreHigh ? 'الوضع الأمني محصن ومستقر' : 'تنبيهات أمنية قيد المتابعة'}
              </span>
              <span className="text-xs text-slate-400">تقييم مبني على الـ 2FA، الجلسات، وسجلات المحاولات الفاشلة</span>
            </div>

            <div className="flex items-baseline gap-3">
              <h1 className="text-5xl font-black tracking-tight">{data.securityScore}%</h1>
              <span className="text-sm font-semibold text-slate-300">مؤشر أمان المنصة العام</span>
            </div>

            <p className="text-sm text-slate-300 max-w-xl">
              المصادقة الثنائية (2FA) لموظفي المنصة، الجلسات المفتوحة والأجهزة الموثوقة، مفاتيح التوقيع الرقمي، مع تسجيل دقيق لكافة محاولات الدخول والحوادث الأمنية.
            </p>
          </div>

          {/* Quick Metrics Strip */}
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-4 lg:gap-4">
            <div className="rounded-xl border border-white/10 bg-white/5 p-3.5 text-center backdrop-blur-sm">
              <p className="text-[11px] font-semibold text-slate-400">المصادقة 2FA</p>
              <p className="mt-1 text-xl font-black text-emerald-400">
                {data.twoFactorEnforcement.compliantStaffCount} / {data.twoFactorEnforcement.totalStaffCount}
              </p>
              <p className="text-[10px] text-slate-400">موظفون ممتثلون</p>
            </div>

            <div className="rounded-xl border border-white/10 bg-white/5 p-3.5 text-center backdrop-blur-sm">
              <p className="text-[11px] font-semibold text-slate-400">الجلسات المفتوحة</p>
              <p className="mt-1 text-xl font-black text-sky-400">{data.activeStaffSessionsCount}</p>
              <p className="text-[10px] text-slate-400">{data.trustedDevicesCount} أجهزة موثوقة</p>
            </div>

            <div className="rounded-xl border border-white/10 bg-white/5 p-3.5 text-center backdrop-blur-sm">
              <p className="text-[11px] font-semibold text-slate-400">فشل الدخول (24h)</p>
              <p
                className={`mt-1 text-xl font-black ${
                  data.failedLogins24hCount > 0 ? 'text-rose-400' : 'text-emerald-400'
                }`}
              >
                {data.failedLogins24hCount}
              </p>
              <p className="text-[10px] text-slate-400">محاولات مسجلة</p>
            </div>

            <div className="rounded-xl border border-white/10 bg-white/5 p-3.5 text-center backdrop-blur-sm">
              <p className="text-[11px] font-semibold text-slate-400">الحوادث النشطة</p>
              <p
                className={`mt-1 text-xl font-black ${
                  data.activeIncidentsCount > 0 ? 'text-amber-400' : 'text-emerald-400'
                }`}
              >
                {data.activeIncidentsCount}
              </p>
              <p className="text-[10px] text-slate-400">تتطلب استجابة</p>
            </div>
          </div>
        </div>
      </section>

      {/* Owner account audit — owner-only review of every account claiming the owner role */}
      {ownerAccounts.length > 0 && (
        <section className="rounded-2xl border border-slate-800 bg-slate-900/70 p-5 shadow-sm">
          <div className="mb-4 flex items-center gap-2">
            <ShieldAlert className="h-5 w-5 text-purple-400" />
            <h2 className="text-sm font-black text-slate-100">حسابات مالك المنصة</h2>
            <span className="text-[11px] text-slate-400">
              مراجعة الحسابات التي تحمل دور مالك المنصة (SUPER_ADMIN) ومصدر اعتمادها.
            </span>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-right text-xs">
              <thead>
                <tr className="border-b border-slate-800 text-[11px] text-slate-400">
                  <th className="px-3 py-2 font-semibold">الحساب</th>
                  <th className="px-3 py-2 font-semibold">المصدر</th>
                  <th className="px-3 py-2 font-semibold">الحالة</th>
                  <th className="px-3 py-2 font-semibold">الاعتماد</th>
                  <th className="px-3 py-2 font-semibold">ملاحظات</th>
                </tr>
              </thead>
              <tbody>
                {ownerAccounts.map((account) => (
                  <tr key={`${account.source}:${account.id}`} className="border-b border-slate-800/60">
                    <td className="px-3 py-2 font-semibold text-slate-200" dir="ltr">{account.label}</td>
                    <td className="px-3 py-2 text-slate-400">
                      {account.source === 'platform_staff' ? 'موظفو المنصة' : 'مستخدمو ERP'}
                    </td>
                    <td className="px-3 py-2">
                      <StatusBadge value={account.isActive ? 'success' : 'neutral'} label={account.isActive ? 'مفعّل' : 'غير مفعّل'} />
                    </td>
                    <td className="px-3 py-2">
                      <StatusBadge value={account.approved ? 'success' : 'danger'} label={account.approved ? 'معتمد' : 'غير معتمد'} />
                    </td>
                    <td className="px-3 py-2 text-[11px] text-amber-300">
                      {account.concerns.length > 0 ? account.concerns.join(' • ') : '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* Navigation Tabs */}
      <div className="flex border-b border-slate-800 pb-0">
        <button
          onClick={() => setTab('OVERVIEW')}
          className={`flex items-center gap-2 px-5 py-3 text-xs font-bold border-b-2 transition-all ${
            tab === 'OVERVIEW'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Shield className="h-4 w-4" />
          <span>نظرة عامة والإنذارات</span>
        </button>

        <button
          onClick={() => setTab('SESSIONS')}
          className={`flex items-center gap-2 px-5 py-3 text-xs font-bold border-b-2 transition-all ${
            tab === 'SESSIONS'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Laptop className="h-4 w-4" />
          <span>الجلسات المركزية والأجهزة الموثوقة ({data.sessions.length})</span>
        </button>

        <button
          onClick={() => setTab('LOGINS')}
          className={`flex items-center gap-2 px-5 py-3 text-xs font-bold border-b-2 transition-all ${
            tab === 'LOGINS'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Clock className="h-4 w-4" />
          <span>سجل محاولات الدخول والأنشطة</span>
        </button>

        <button
          onClick={() => setTab('KEYS')}
          className={`flex items-center gap-2 px-5 py-3 text-xs font-bold border-b-2 transition-all ${
            tab === 'KEYS'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <Key className="h-4 w-4" />
          <span>مفاتيح API والتوقيع الرقمي</span>
        </button>

        <button
          onClick={() => setTab('INCIDENTS')}
          className={`flex items-center gap-2 px-5 py-3 text-xs font-bold border-b-2 transition-all ${
            tab === 'INCIDENTS'
              ? 'border-emerald-500 text-emerald-400 bg-slate-900/60'
              : 'border-transparent text-slate-400 hover:text-slate-200'
          }`}
        >
          <FileWarning className="h-4 w-4" />
          <span>سجل الحوادث والاستجابة ({data.incidents.length})</span>
        </button>
      </div>

      {/* TAB 1: OVERVIEW & ACTIVE THREATS */}
      {tab === 'OVERVIEW' && (
        <div className="space-y-5">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {/* 1. 2FA Policy Card (live: reads real enforcement + compliance) */}
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 shadow-sm">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-slate-200 flex items-center gap-1.5">
                  <Lock className="h-4 w-4 text-emerald-400" />
                  سياسة المصادقة الثنائية (2FA)
                </span>
                <span className={`rounded text-[10px] font-bold px-2 py-0.5 ${
                  data.twoFactorEnforcement.enabled
                    ? 'bg-emerald-500/20 text-emerald-300'
                    : 'bg-amber-500/20 text-amber-300'
                }`}>
                  {data.twoFactorEnforcement.enabled ? 'إلزامية' : 'غير إلزامية'}
                </span>
              </div>
              <p className="text-xs text-slate-400 leading-relaxed">
                {data.twoFactorEnforcement.enabled
                  ? 'إلزامية على كافة موظفي المنصة. الحساب غير المفعّل لا يستطيع استخدام لوحة التحكم.'
                  : 'المصادقة الثنائية غير ملزمة حالياً. يمكن للمالك تفعيل الإلزام من هنا أو من صفحة الفريق.'}
              </p>
              <div className="mt-3 pt-2 border-t border-slate-800 text-[11px] text-slate-400 space-y-1.5">
                <div className="flex justify-between">
                  <span>نسبة الامتثال</span>
                  <span className={`font-bold ${data.twoFactorEnforcement.totalStaffCount > 0 && data.twoFactorEnforcement.compliantStaffCount === data.twoFactorEnforcement.totalStaffCount ? 'text-emerald-400' : 'text-amber-400'}`}>
                    {data.twoFactorEnforcement.compliantStaffCount} / {data.twoFactorEnforcement.totalStaffCount}
                  </span>
                </div>
                <button
                  disabled={!canManageSecurity}
                  onClick={() => {
                    if (!canManageSecurity) return;
                    try {
                      platformAdminService.setStaffMfaEnforcement(data.twoFactorEnforcement.enabled ? 'optional' : 'required');
                      loadSecurity();
                    } catch (err) {
                      alert(err instanceof Error ? err.message : 'تعذر تغيير السياسة.');
                    }
                  }}
                  className="w-full rounded-lg border border-slate-700 px-3 py-1.5 text-[10.5px] font-bold text-sky-300 transition hover:border-sky-600 hover:text-sky-200 disabled:cursor-not-allowed disabled:opacity-40"
                >
                  {data.twoFactorEnforcement.enabled ? 'اجعلها اختيارية' : 'اجعلها إلزامية'}
                </button>
              </div>
            </div>

            {/* 2. Cryptographic Signing */}
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 shadow-sm">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-slate-200 flex items-center gap-1.5">
                  <KeyRound className="h-4 w-4 text-sky-400" />
                  محرك التوقيع الرقمي (Ed25519)
                </span>
                <span className="rounded bg-sky-500/20 text-sky-300 text-[10px] font-bold px-2 py-0.5">
                  مشفر
                </span>
              </div>
              <p className="text-xs text-slate-400 leading-relaxed">
                كافة التراخيص وتكوينات العملاء موقعة تشفيرياً بمفاتيح مركزية مع تدوير دوري لمنع التلاعب.
              </p>
              <div className="mt-3 pt-2 border-t border-slate-800 text-[11px] text-slate-400 flex justify-between">
                <span>المفاتيح النشطة</span>
                <span className="text-sky-300 font-bold">{data.signingKeys.length} مفاتيح</span>
              </div>
            </div>

            {/* 3. Incident Readiness */}
            <div className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 shadow-sm">
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-bold text-slate-200 flex items-center gap-1.5">
                  <Zap className="h-4 w-4 text-amber-400" />
                  جاهزية الاستجابة للطوارئ
                </span>
                <span className="rounded bg-amber-500/20 text-amber-300 text-[10px] font-bold px-2 py-0.5">
                  Playbook
                </span>
              </div>
              <p className="text-xs text-slate-400 leading-relaxed">
                إجراءات احتواء الحوادث الأمنية السريعة متاحة بنقرة واحدة لإنهاء الجلسات أو حظر الـ IP.
              </p>
              <div className="mt-3 pt-2 border-t border-slate-800 text-[11px] text-slate-400 flex justify-between">
                <span>الحوادث المفتوحة</span>
                <span
                  className={`font-bold ${
                    data.activeIncidentsCount === 0 ? 'text-emerald-400' : 'text-rose-400'
                  }`}
                >
                  {data.activeIncidentsCount}
                </span>
              </div>
            </div>
          </div>

          {/* Quick Active Incidents Banner if any */}
          {data.incidents.filter((i) => i.status !== 'RESOLVED').length > 0 && (
            <div className="rounded-xl border border-rose-800/80 bg-rose-950/30 p-4">
              <h3 className="text-xs font-bold text-rose-300 flex items-center gap-2 mb-2">
                <AlertTriangle className="h-4 w-4" />
                حوادث أمنية قيد الاحتواء والتحقيق تتطلب انتباهك:
              </h3>
              <ul className="space-y-2">
                {data.incidents
                  .filter((i) => i.status !== 'RESOLVED')
                  .map((inc) => (
                    <li
                      key={inc.id}
                      className="flex items-center justify-between bg-slate-900/80 p-2.5 rounded-lg border border-rose-800/50 text-xs"
                    >
                      <div>
                        <span className="font-bold text-slate-100">{inc.title}</span>
                        <span className="text-slate-400 text-[11px] mr-2">
                          (المصدر: {inc.sourceIp || 'خارجي'})
                        </span>
                      </div>
                      <Button
                        size="sm"
                        variant="secondary"
                        disabled={!canManageSecurity}
                        onClick={() => handleRespondIncident(inc.id, true)}
                      >
                        إغلاق وحل الحادث
                      </Button>
                    </li>
                  ))}
              </ul>
            </div>
          )}
        </div>
      )}

      {/* TAB 2: STAFF SESSIONS */}
      {tab === 'SESSIONS' && (
        <section className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
          <header className="border-b border-slate-800 px-4 py-3 bg-slate-950/40 flex items-center justify-between">
            <div>
              <h3 className="text-xs font-bold text-slate-200">
                الجلسات النشطة لمديري وموظفي المنصة ({data.sessions.length})
              </h3>
              <p className="text-[10.5px] text-slate-400">
                يمكن إنهاء أي جلسة مشبوهة أو غير معتادة عن بعد فوراً لحماية النظام.
              </p>
            </div>
            <Button
              size="sm"
              variant="danger"
              onClick={handleRevokeAllOtherSessions}
              disabled={!canManageSecurity}
              leadingIcon={<LogOut className="h-3.5 w-3.5" />}
            >
              إنهاء كافة الجلسات الأخرى
            </Button>
          </header>

          <div className="overflow-x-auto">
            <table className="w-full min-w-[800px] text-right">
              <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                <tr>
                  <th className="px-4 py-3">الموظف والدور</th>
                  <th className="px-4 py-3">الجهاز والمتصفح</th>
                  <th className="px-4 py-3">عنوان IP</th>
                  <th className="px-4 py-3">موثوقية الجهاز</th>
                  <th className="px-4 py-3">آخر نشاط</th>
                  <th className="px-4 py-3 text-center">الإجراء</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {data.sessions.map((sess) => (
                  <tr key={sess.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="px-4 py-3 text-xs">
                      <p className="font-bold text-slate-100 flex items-center gap-1.5">
                        {sess.staffName}
                        {sess.isCurrent && (
                          <span className="rounded bg-emerald-500/20 text-emerald-300 text-[9px] px-1.5 py-0.5 font-bold">
                            جلستك الحالية
                          </span>
                        )}
                      </p>
                      <p className="text-[10.5px] text-slate-400">{sess.staffRole}</p>
                    </td>

                    <td className="px-4 py-3 text-xs text-slate-300">
                      <span className="flex items-center gap-1.5">
                        <Laptop className="h-3.5 w-3.5 text-slate-400" />
                        {sess.deviceName || 'غير محدد'}
                      </span>
                    </td>

                    <td className="px-4 py-3 text-xs font-mono text-slate-300">{sess.ipAddress || '—'}</td>

                    <td className="px-4 py-3 text-xs">
                      {sess.isTrustedDevice ? (
                        <span className="inline-flex items-center gap-1 text-emerald-400 font-bold">
                          <CheckCircle2 className="h-3 w-3" /> موثوق
                        </span>
                      ) : (
                        <span className="inline-flex items-center gap-1 text-amber-400 font-bold">
                          <AlertTriangle className="h-3 w-3" /> غير مصادق
                        </span>
                      )}
                    </td>

                    <td className="px-4 py-3 text-xs text-slate-400">
                      {formatDateTime(sess.lastActivityAt)}
                    </td>

                    <td className="px-4 py-3 text-center">
                      {!sess.isCurrent && (
                        <Button
                          size="sm"
                          variant="danger"
                          onClick={() => handleRevokeSession(sess.id)}
                          disabled={!canManageSecurity}
                          leadingIcon={<LogOut className="h-3 w-3" />}
                        >
                          إنهاء الجلسة
                        </Button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      )}

      {/* TAB 3: STAFF LOGINS AUDIT */}
      {tab === 'LOGINS' && (
        <section className="space-y-3">
          <div className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-slate-800 bg-slate-900/80 p-3 shadow-sm">
            <div className="relative min-w-[240px]">
              <Search className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                value={loginSearch}
                onChange={(e) => setLoginSearch(e.target.value)}
                placeholder="ابحث بالبريد أو عنوان IP..."
                className={`${inputClass} pr-9 text-xs`}
              />
            </div>

            <label className="flex items-center gap-2 text-xs text-slate-300 cursor-pointer select-none">
              <input
                type="checkbox"
                checked={loginFilterFailed}
                onChange={(e) => setLoginFilterFailed(e.target.checked)}
                className="rounded border-slate-700 bg-slate-800 text-rose-500 focus:ring-rose-500"
              />
              <span className={loginFilterFailed ? 'text-rose-400 font-bold' : ''}>
                عرض المحاولات الفاشلة والمحظورة فقط
              </span>
            </label>
          </div>

          <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
            <div className="overflow-x-auto">
              <table className="w-full min-w-[800px] text-right">
                <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                  <tr>
                    <th className="px-4 py-3">البريد الإلكتروني</th>
                    <th className="px-4 py-3">عنوان IP</th>
                    <th className="px-4 py-3">حالة المحاولة</th>
                    <th className="px-4 py-3">السبب / الملاحظات</th>
                    <th className="px-4 py-3">التوقيت</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-800/80">
                  {filteredLogins.length === 0 ? (
                    <tr>
                      <td colSpan={5} className="py-12 text-center text-xs text-slate-500">
                        لا توجد سجلات دخول تطابق البحث.
                      </td>
                    </tr>
                  ) : (
                    filteredLogins.map((login) => (
                      <tr key={login.id} className="hover:bg-slate-800/30 transition-colors">
                        <td className="px-4 py-3 text-xs font-bold text-slate-100">{login.email}</td>
                        <td className="px-4 py-3 text-xs font-mono text-slate-300">{login.ipAddress || '—'}</td>
                        <td className="px-4 py-3 text-xs">
                          <span
                            className={`inline-flex items-center gap-1 font-bold ${
                              login.status === 'SUCCESS'
                                ? 'text-emerald-400'
                                : login.status === 'BLOCKED'
                                ? 'text-rose-500'
                                : 'text-amber-400'
                            }`}
                          >
                            {login.status === 'SUCCESS' ? (
                              <CheckCircle2 className="h-3 w-3" />
                            ) : (
                              <XCircle className="h-3 w-3" />
                            )}
                            {login.status === 'SUCCESS'
                              ? 'ناجح'
                              : login.status === 'BLOCKED'
                              ? 'محظور IP'
                              : 'فشل كلمة المرور'}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-xs text-slate-400">{login.failureReason || '—'}</td>
                        <td className="px-4 py-3 text-xs text-slate-400">{formatDateTime(login.attemptedAt)}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        </section>
      )}

      {/* TAB 4: API & SIGNING KEYS */}
      {tab === 'KEYS' && (
        <div className="space-y-5">
          {/* Cryptographic Signing Keys */}
          <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 shadow-sm">
            <header className="mb-3 flex items-center justify-between border-b border-slate-800 pb-2.5">
              <div>
                <h3 className="text-xs font-bold text-slate-100 flex items-center gap-2">
                  <KeyRound className="h-4 w-4 text-emerald-400" />
                  مفاتيح التوقيع الرقمي للمنصة (Cryptographic Signing Keys)
                </h3>
                <p className="text-[11px] text-slate-400">
                  تستخدم لتوليد وتوقيع التراخيص وحزم التكوين لضمان عدم تزييفها.
                </p>
              </div>
            </header>

            <div className="grid gap-3 sm:grid-cols-2">
              {data.signingKeys.map((k) => (
                <div
                  key={k.id}
                  className="rounded-lg border border-slate-800 bg-slate-950/60 p-3.5 flex items-center justify-between"
                >
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-bold text-slate-100">{k.keyAlias}</span>
                      <span className="rounded bg-sky-500/20 text-sky-300 text-[10px] font-bold px-1.5 py-0.5">
                        v{k.version}
                      </span>
                    </div>
                    <p className="text-[11px] text-slate-400 mt-1">
                      الخوارزمية: <span className="font-mono text-slate-300">{k.algorithm}</span>
                    </p>
                    <p className="text-[10px] text-slate-500">تم الإنشاء: {formatDateTime(k.createdAt)}</p>
                  </div>

                  <Button
                    size="sm"
                    variant="secondary"
                    onClick={() => k.keyAlias && handleRotateKey(k.keyAlias)}
                    disabled={!canManageSecurity}
                    leadingIcon={<RotateCcw className="h-3.5 w-3.5" />}
                  >
                    تدوير المفتاح
                  </Button>
                </div>
              ))}
            </div>
          </section>

          {/* Platform API Keys */}
          <section className="rounded-xl border border-slate-800 bg-slate-900/70 p-4 shadow-sm">
            <header className="mb-3 flex items-center justify-between border-b border-slate-800 pb-2.5">
              <div>
                <h3 className="text-xs font-bold text-slate-100 flex items-center gap-2">
                  <Key className="h-4 w-4 text-sky-400" />
                  مفاتيح الـ API المركزية
                </h3>
                <p className="text-[11px] text-slate-400">
                  مفاتيح التكامل الخاصة بالمنصة وخدمات الربط الخارجي ونطاقات الصلاحيات.
                </p>
              </div>
              {canManageSecurity && (
                <Button
                  size="sm"
                  onClick={() => {
                    setApiKeyForm({
                      tenantId: tenants[0]?.id ?? '',
                      name: '',
                      scopes: ['read', 'write'],
                      expiresAt: '',
                    });
                    setIsApiKeyModalOpen(true);
                  }}
                  leadingIcon={<Plus className="h-4 w-4" />}
                >
                  إنشاء مفتاح API جديد
                </Button>
              )}
            </header>

            {apiKeys.length === 0 ? (
              <p className="text-xs text-slate-500 py-4 text-center">لا توجد مفاتيح API مسجلة حالياً.</p>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-right text-xs">
                  <thead className="border-b border-slate-800 text-[11px] text-slate-400">
                    <tr>
                      <th className="py-2 px-3">اسم المفتاح</th>
                      <th className="py-2 px-3">البادئة</th>
                      <th className="py-2 px-3">الصلاحيات</th>
                      <th className="py-2 px-3">الحالة</th>
                      <th className="py-2 px-3">تاريخ الانتهاء</th>
                      <th className="py-2 px-3">آخر استخدام</th>
                      <th className="py-2 px-3 text-center">إجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800">
                    {apiKeys.map((key) => (
                      <tr key={key.id}>
                        <td className="py-2.5 px-3 font-bold text-slate-200">{key.name}</td>
                        <td className="py-2.5 px-3 font-mono text-slate-400">{key.keyPrefix}...</td>
                        <td className="py-2.5 px-3 text-slate-400">
                          {key.scopes.join(', ') || 'الكل'}
                        </td>
                        <td className="py-2.5 px-3">
                          <span
                            className={`font-bold ${
                              key.isActive ? 'text-emerald-400' : 'text-rose-400'
                            }`}
                          >
                            {key.isActive ? 'نشط' : 'ملغي'}
                          </span>
                        </td>
                        <td className="py-2.5 px-3 text-slate-400">
                          {key.expiresAt ? formatDateTime(key.expiresAt) : 'دائم'}
                        </td>
                        <td className="py-2.5 px-3 text-slate-400">
                          {key.lastUsedAt ? formatDateTime(key.lastUsedAt) : 'لم يستخدم'}
                        </td>
                        <td className="py-2.5 px-3 text-center">
                          {key.isActive && (
                            <div className="flex items-center justify-center gap-2">
                              <button
                                disabled={!canManageSecurity}
                                onClick={() => handleRotateApiKey(key.id)}
                                className="text-sky-400 hover:underline text-xs flex items-center gap-1"
                                title="تدوير المفتاح"
                              >
                                <RotateCcw className="h-3 w-3" />
                                تدوير
                              </button>
                              <span className="text-slate-600">|</span>
                              <button
                                disabled={!canManageSecurity}
                                onClick={() => handleRevokeApiKey(key.id)}
                                className="text-rose-400 hover:underline text-xs"
                              >
                                إلغاء
                              </button>
                            </div>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </section>
        </div>
      )}

      {/* TAB 5: INCIDENTS & EMERGENCY PLAYBOOK */}
      {tab === 'INCIDENTS' && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-xs font-bold text-slate-200">
              سجل الحوادث الأمنية المركزية ({data.incidents.length})
            </h3>
            <Button
              size="sm"
              disabled={!canManageSecurity}
              onClick={() => { if (!canManageSecurity) return; setIsIncidentModalOpen(true); }}
              leadingIcon={<ShieldAlert className="h-4 w-4" />}
            >
              تسجيل بلاغ أمني يدوي
            </Button>
          </div>

          <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
            {data.incidents.length === 0 ? (
              <EmptyState
                icon={<ShieldCheck className="h-6 w-6 text-emerald-400" />}
                title="السجل نظيف تماماً"
                description="لم يتم رصد أي اختراقات أو حوادث أمنية على المنصة."
              />
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[800px] text-right">
                  <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                    <tr>
                      <th className="px-4 py-3">عنوان الحادث</th>
                      <th className="px-4 py-3">مستوى الخطورة</th>
                      <th className="px-4 py-3">الحالة</th>
                      <th className="px-4 py-3">إجراء الاحتواء المتخذ</th>
                      <th className="px-4 py-3">التوقيت</th>
                      <th className="px-4 py-3 text-center">إجراءات</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-800/80">
                    {data.incidents.map((inc) => (
                      <tr key={inc.id} className="hover:bg-slate-800/30 transition-colors">
                        <td className="px-4 py-3 text-xs">
                          <p className="font-bold text-slate-100">{inc.title}</p>
                          {inc.details && <p className="text-[11px] text-slate-400 mt-0.5">{inc.details}</p>}
                        </td>

                        <td className="px-4 py-3 text-xs">
                          <span
                            className={`rounded px-2 py-0.5 text-[10px] font-black ${
                              inc.severity === 'CRITICAL'
                                ? 'bg-rose-500/20 text-rose-300 border border-rose-500/30'
                                : inc.severity === 'HIGH'
                                ? 'bg-amber-500/20 text-amber-300 border border-amber-500/30'
                                : 'bg-slate-800 text-slate-300'
                            }`}
                          >
                            {inc.severity}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-xs">
                          <span
                            className={`font-bold ${
                              inc.status === 'RESOLVED'
                                ? 'text-emerald-400'
                                : inc.status === 'CONTAINED'
                                ? 'text-sky-400'
                                : 'text-rose-400'
                            }`}
                          >
                            {inc.status === 'RESOLVED'
                              ? 'تم الحل'
                              : inc.status === 'CONTAINED'
                              ? 'قيد الاحتواء'
                              : 'مفتوح'}
                          </span>
                        </td>

                        <td className="px-4 py-3 text-xs text-slate-300">
                          {inc.containmentAction || 'بانتظار إجراء'}
                        </td>

                        <td className="px-4 py-3 text-xs text-slate-400">
                          {formatDateTime(inc.createdAt)}
                        </td>

                        <td className="px-4 py-3 text-center">
                          {inc.status !== 'RESOLVED' && (
                            <Button
                              size="sm"
                              variant="secondary"
                              disabled={!canManageSecurity}
                        onClick={() => handleRespondIncident(inc.id, true)}
                            >
                              إغلاق كـ محلول
                            </Button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Modal: Record Manual Incident */}
      <Modal
        open={isIncidentModalOpen}
        onClose={() => setIsIncidentModalOpen(false)}
        title="تسجيل بلاغ أمني جديد"
      >
        <div className="space-y-3.5 text-right">
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">عنوان البلاغ الأمني *</label>
            <input
              type="text"
              value={incidentForm.title}
              onChange={(e) => setIncidentForm({ ...incidentForm, title: e.target.value })}
              placeholder="مثلاً: محاولات هجوم Brute Force مكثفة..."
              className={inputClass}
            />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">مستوى الخطورة</label>
              <select
                value={incidentForm.severity}
                onChange={(e) => setIncidentForm({ ...incidentForm, severity: e.target.value as any })}
                className={inputClass}
              >
                <option value="CRITICAL">حرجة (Critical)</option>
                <option value="HIGH">عالية (High)</option>
                <option value="MEDIUM">متوسطة (Medium)</option>
                <option value="LOW">منخفضة (Low)</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">مصدر IP المشتبه به</label>
              <input
                type="text"
                value={incidentForm.sourceIp}
                onChange={(e) => setIncidentForm({ ...incidentForm, sourceIp: e.target.value })}
                placeholder="192.168.1.1"
                className={inputClass}
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">تفاصيل وملاحظات الحادث</label>
            <textarea
              rows={3}
              value={incidentForm.details}
              onChange={(e) => setIncidentForm({ ...incidentForm, details: e.target.value })}
              className={inputClass}
            />
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsIncidentModalOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleCreateIncident} disabled={!canManageSecurity}>
              تسجيل البلاغ
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal: Create API Key */}
      <Modal
        open={isApiKeyModalOpen}
        onClose={() => setIsApiKeyModalOpen(false)}
        title="إنشاء مفتاح API تجاري مركزي"
      >
        <div className="space-y-3.5 text-right">
          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">اسم المفتاح / الوصف *</label>
            <input
              type="text"
              value={apiKeyForm.name}
              onChange={(e) => setApiKeyForm({ ...apiKeyForm, name: e.target.value })}
              placeholder="مثلاً: مفتاح الربط مع متجر Shopify أو نظام المحاسبة الخارجي"
              className={inputClass}
            />
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">العميل المرتبط (المستأجر) *</label>
            <select
              value={apiKeyForm.tenantId}
              onChange={(e) => setApiKeyForm({ ...apiKeyForm, tenantId: e.target.value })}
              className={inputClass}
            >
              {tenants.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name} ({t.code})
                </option>
              ))}
            </select>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">نطاقات الصلاحية (Scopes)</label>
            <div className="grid grid-cols-2 gap-2 text-xs text-slate-300 mt-1">
              {[
                { id: 'read', label: 'قراءة البيانات (read)' },
                { id: 'write', label: 'كتابة وتعديل (write)' },
                { id: 'invoices', label: 'الفواتير والمدفوعات (invoices)' },
                { id: 'products', label: 'الكتالوج والمنتجات (products)' },
                { id: 'webhooks', label: 'إدارة Webhooks' },
                { id: 'admin', label: 'تحكم إداري كامل (admin)' },
              ].map((s) => {
                const checked = apiKeyForm.scopes.includes(s.id);
                return (
                  <label key={s.id} className="flex items-center gap-2 cursor-pointer bg-slate-950/40 p-2 rounded border border-slate-800">
                    <input
                      type="checkbox"
                      checked={checked}
                      onChange={(e) => {
                        if (e.target.checked) {
                          setApiKeyForm({ ...apiKeyForm, scopes: [...apiKeyForm.scopes, s.id] });
                        } else {
                          setApiKeyForm({ ...apiKeyForm, scopes: apiKeyForm.scopes.filter((sc) => sc !== s.id) });
                        }
                      }}
                      className="rounded border-slate-700 text-sky-500 focus:ring-sky-500"
                    />
                    <span>{s.label}</span>
                  </label>
                );
              })}
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">تاريخ انتهاء الصلاحية (اختياري)</label>
            <input
              type="datetime-local"
              value={apiKeyForm.expiresAt}
              onChange={(e) => setApiKeyForm({ ...apiKeyForm, expiresAt: e.target.value })}
              className={inputClass}
            />
            <span className="text-[10px] text-slate-500 mt-0.5 block">اتركه فارغاً ليكون المفتاح دائماً وغير مقيد بوقت انتهاء.</span>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setIsApiKeyModalOpen(false)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleCreateApiKey} disabled={!canManageSecurity}>
              إنشاء المفتاح الآن
            </Button>
          </div>
        </div>
      </Modal>

      {/* Modal: New API Key Result (Show Secret Key Once) */}
      <Modal
        open={Boolean(newKeyResult)}
        onClose={() => setNewKeyResult(null)}
        title="تم إنشاء مفتاح الـ API بنجاح"
      >
        <div className="space-y-4 text-right">
          <div className="p-3 bg-amber-500/10 border border-amber-500/20 rounded-lg flex items-start gap-2.5">
            <AlertTriangle className="h-5 w-5 text-amber-400 shrink-0 mt-0.5" />
            <div className="text-xs text-amber-200">
              <strong className="font-bold block mb-1">تنبيه أمان فائق الأهمية:</strong>
              هذه هي المرة الوحيدة التي سيظهر فيها مفتاح الـ API السري كاملاً. قم بنسخه وحفظه في بيئة آمنة فوراً؛ لن تتمكن من رؤيته مرة أخرى!
            </div>
          </div>

          {newKeyResult && (
            <div className="space-y-2">
              <label className="block text-xs font-semibold text-slate-300">مفتاح الـ API السري الكامل (Secret Key):</label>
              <div className="flex items-center gap-2">
                <input
                  type="text"
                  readOnly
                  value={newKeyResult.plainTextKey}
                  className={`${inputClass} font-mono text-emerald-400 select-all`}
                />
                <Button
                  size="sm"
                  variant="secondary"
                  onClick={() => {
                    navigator.clipboard.writeText(newKeyResult.plainTextKey);
                    alert('تم نسخ المفتاح إلى الحافظة بنجاح.');
                  }}
                  leadingIcon={<Copy className="h-4 w-4" />}
                >
                  نسخ
                </Button>
              </div>

              <div className="mt-3 p-3 bg-slate-950/60 rounded-lg border border-slate-800 text-xs space-y-1 text-slate-300">
                <p><strong>اسم المفتاح:</strong> {newKeyResult.key.name}</p>
                <p><strong>البادئة:</strong> <span className="font-mono">{newKeyResult.key.keyPrefix}</span></p>
                <p><strong>الصلاحيات:</strong> {newKeyResult.key.scopes.join(', ') || 'الكل'}</p>
                <p><strong>معرف المفتاح:</strong> <span className="font-mono">{newKeyResult.key.id}</span></p>
              </div>
            </div>
          )}

          <div className="flex justify-end pt-3 border-t border-slate-800">
            <Button size="sm" onClick={() => setNewKeyResult(null)}>
              لقد قمت بحفظ المفتاح بأمان، إغلاق
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

export default PlatformSecurityCenterPage;

import React from 'react';
import {
  Settings,
  Save,
  KeyRound,
  ShieldCheck,
  Building2,
  Mail,
  CreditCard,
  Globe,
  Lock,
  Database,
  Languages,
  RefreshCw,
  Server,
  AlertTriangle,
  RotateCw,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { AuthService } from '../../services/domains/auth/AuthService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type { PlatformSettingsMap } from '../../services/domains/platform/platformTypes';
import type { User } from '../../types';
import { Button } from '../../components/ui/Button';
import { PageHeader } from '../../components/ui/PageHeader';
import { useToast } from '../../components/ui/Toast';
import { Field, inputClass, formatDateTime } from './components/PlatformUI';

interface PlatformSettingsPageProps {
  currentUser: User;
}

type SettingsTab = 'identity' | 'legal' | 'communications' | 'payments' | 'network' | 'security' | 'backup' | 'password';

export const PlatformSettingsPage: React.FC<PlatformSettingsPageProps> = ({ currentUser }) => {
  const toast = useToast();
  const canManageSettings = canPlatform('settings');
  const [activeTab, setActiveTab] = React.useState<SettingsTab>('identity');
  const [settings, setSettings] = React.useState<PlatformSettingsMap | null>(null);
  const [loading, setLoading] = React.useState(true);
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState<string | null>(null);

  // Key rotation state
  const [rotatingKey, setRotatingKey] = React.useState(false);

  // Password Change state
  const [passwordForm, setPasswordForm] = React.useState({ current: '', next: '', confirm: '' });
  const [changingPassword, setChangingPassword] = React.useState(false);
  const [passwordError, setPasswordError] = React.useState<string | null>(null);

  const load = React.useCallback(() => {
    setLoading(true);
    try {
      setSettings(platformAdminService.getSettings());
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل إعدادات المنصة.');
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  const saveSettings = () => {
    if (!settings) return;
    if (!canManageSettings) {
      toast.error('لا تملك صلاحية تعديل إعدادات المنصة');
      return;
    }
    setSaving(true);
    try {
      const updated = platformAdminService.updateSettings({
        ...settings,
        defaultTrialDays: String(Math.max(1, Number(settings.defaultTrialDays) || 14)),
      });
      setSettings(updated);
      toast.success('تم حفظ إعدادات المنصة بنجاح');
    } catch (err) {
      toast.error('تعذر حفظ الإعدادات', err instanceof Error ? err.message : undefined);
    } finally {
      setSaving(false);
    }
  };

  const handleRotateEncryptionKeys = () => {
    if (!canManageSettings) {
      toast.error('لا تملك صلاحية إدارة إعدادات الأمان');
      return;
    }
    if (!window.confirm('هل أنت متأكد من تدوير مفاتيح التشفير المركزية للمنصة؟ سيتم تسجيل الحدث كعملية أمنية عالية الخطورة.')) {
      return;
    }
    setRotatingKey(true);
    try {
      const res = platformAdminService.rotatePlatformEncryptionKeys();
      toast.success(`تم تدوير المفاتيح بنجاح (بصمة المفتاح: ${res.newKeyFingerprint})`);
      load();
    } catch (err) {
      toast.error('فشل تدوير المفاتيح', err instanceof Error ? err.message : undefined);
    } finally {
      setRotatingKey(false);
    }
  };

  const changePassword = async () => {
    setPasswordError(null);
    if (passwordForm.next !== passwordForm.confirm) {
      setPasswordError('تأكيد كلمة المرور غير مطابق.');
      return;
    }
    if (passwordForm.next.length < 8) {
      setPasswordError('كلمة المرور الجديدة يجب أن تكون 8 أحرف على الأقل.');
      return;
    }
    setChangingPassword(true);
    try {
      await new AuthService().changeOwnPasswordAsync(
        currentUser.id,
        passwordForm.current,
        passwordForm.next,
        currentUser.fullName
      );
      toast.success('تم تغيير كلمة المرور بنجاح');
      setPasswordForm({ current: '', next: '', confirm: '' });
    } catch (err) {
      setPasswordError(err instanceof Error ? err.message : 'تعذر تغيير كلمة المرور.');
    } finally {
      setChangingPassword(false);
    }
  };

  if (loading || !settings) {
    return (
      <div className="py-24 text-center text-sm font-semibold text-slate-500">
        جارٍ تحميل إعدادات المنصة المركزية...
      </div>
    );
  }

  const tabs: Array<{ id: SettingsTab; label: string; icon: React.ReactNode }> = [
    { id: 'identity', label: 'الهوية والعام', icon: <Settings className="h-4 w-4" /> },
    { id: 'legal', label: 'البيانات القانونية والضريبية', icon: <Building2 className="h-4 w-4" /> },
    { id: 'communications', label: 'البريد وخوادم الرسائل', icon: <Mail className="h-4 w-4" /> },
    { id: 'payments', label: 'الدفع والفوترة', icon: <CreditCard className="h-4 w-4" /> },
    { id: 'network', label: 'النطاقات والـ API', icon: <Globe className="h-4 w-4" /> },
    { id: 'security', label: 'الأمان والتشفير و MFA', icon: <Lock className="h-4 w-4" /> },
    { id: 'backup', label: 'النسخ الاحتياطي والاستبقاء', icon: <Database className="h-4 w-4" /> },
    { id: 'password', label: 'أمان الحساب الشخصي', icon: <KeyRound className="h-4 w-4" /> },
  ];

  return (
    <div className="space-y-6">
      <PageHeader
        title="إعدادات المنصة المركزية"
        description="إدارة الهوية القانونية، بوابات الدفع، خوادم الاتصالات، سياسات الأمان والتشفير من بيئة آمنة."
        icon={<Settings className="h-5 w-5 text-indigo-600" />}
        actions={
          <div className="flex items-center gap-2">
            <Button variant="ghost" size="sm" leadingIcon={<RefreshCw className="h-3.5 w-3.5" />} onClick={load}>
              تحديث
            </Button>
            {activeTab !== 'password' && (
              <Button
                variant="primary"
                size="sm"
                leadingIcon={<Save className="h-3.5 w-3.5" />}
                onClick={saveSettings}
                disabled={saving || !canManageSettings}
              >
                {saving ? 'جارٍ الحفظ...' : 'حفظ التغييرات'}
              </Button>
            )}
          </div>
        }
      />

      {error && (
        <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">
          {error}
        </div>
      )}

      {/* Navigation Tabs Bar */}
      <div className="flex overflow-x-auto border-b border-slate-200 bg-white px-2 pt-2 rounded-t-xl gap-1">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id)}
            className={`flex items-center gap-2 border-b-2 px-4 py-3 text-xs font-semibold whitespace-nowrap transition-colors ${
              activeTab === tab.id
                ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
                : 'border-transparent text-slate-600 hover:border-slate-300 hover:text-slate-900'
            }`}
          >
            {tab.icon}
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Contents Card */}
      <div className="rounded-b-xl rounded-tr-xl border border-slate-200 bg-white p-6 shadow-sm">
        {/* 1. Identity & General */}
        {activeTab === 'identity' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">هوية المنصة والإعدادات الإقليمية</h3>
              <p className="text-xs text-slate-500">اسم النظام الرسمي، اللغات، والعملات الافتراضية.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="اسم المنصة">
                <input
                  type="text"
                  value={settings.platformName}
                  onChange={(e) => setSettings({ ...settings, platformName: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="المنطقة الزمنية (Timezone)">
                <input
                  type="text"
                  value={settings.timezone || 'Africa/Cairo'}
                  onChange={(e) => setSettings({ ...settings, timezone: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="البريد الإلكتروني للدعم">
                <input
                  type="email"
                  value={settings.supportEmail}
                  onChange={(e) => setSettings({ ...settings, supportEmail: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="هاتف الدعم الفني">
                <input
                  type="tel"
                  value={settings.supportPhone}
                  onChange={(e) => setSettings({ ...settings, supportPhone: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="العملة الافتراضية">
                <input
                  type="text"
                  value={settings.defaultCurrency}
                  onChange={(e) => setSettings({ ...settings, defaultCurrency: e.target.value.toUpperCase() })}
                  className={inputClass}
                  placeholder="EGP, SAR, USD"
                />
              </Field>
              <Field label="اللغة الافتراضية للواجهة">
                <select
                  value={settings.defaultLocale || 'ar'}
                  onChange={(e) => setSettings({ ...settings, defaultLocale: e.target.value })}
                  className={inputClass}
                >
                  <option value="ar">العربية (Arabic)</option>
                  <option value="en">الإنجليزية (English)</option>
                </select>
              </Field>
            </div>
          </div>
        )}

        {/* 2. Legal & Tax */}
        {activeTab === 'legal' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">البيانات القانونية والضريبية للمنصة</h3>
              <p className="text-xs text-slate-500">تستخدم هذه البيانات في العقود، الفواتير الرسمية، والتراخيص الموثقة.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="الاسم القانوني المسجل للشركة">
                <input
                  type="text"
                  value={settings.companyLegalName || ''}
                  onChange={(e) => setSettings({ ...settings, companyLegalName: e.target.value })}
                  className={inputClass}
                  placeholder="مثال: شركة تقنية المعلومات والحلول الرقمية ذ.م.م"
                />
              </Field>
              <Field label="الممثل القانوني / المفوض بالتوقيع">
                <input
                  type="text"
                  value={settings.legalRepresentative || ''}
                  onChange={(e) => setSettings({ ...settings, legalRepresentative: e.target.value })}
                  className={inputClass}
                  placeholder="اسم المفوض الرسمي"
                />
              </Field>
              <Field label="رقم السجل التجاري (CRN)">
                <input
                  type="text"
                  value={settings.commercialRegistry || ''}
                  onChange={(e) => setSettings({ ...settings, commercialRegistry: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="الرقم التعريفي الضريبي (VAT ID)">
                <input
                  type="text"
                  value={settings.taxNumber || ''}
                  onChange={(e) => setSettings({ ...settings, taxNumber: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <div className="md:col-span-2">
                <Field label="العنوان والمقر القانوني الرسمي">
                  <textarea
                    rows={2}
                    value={settings.officialAddress || ''}
                    onChange={(e) => setSettings({ ...settings, officialAddress: e.target.value })}
                    className={inputClass}
                    placeholder="العنوان الكامل للمقر الرئيسي المسجل"
                  />
                </Field>
              </div>
            </div>
          </div>
        )}

        {/* 3. Communications (Email & SMS) */}
        {activeTab === 'communications' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">خوادم إرسال البريد الإلكتروني والرسائل القصيرة (SMS)</h3>
              <p className="text-xs text-slate-500">
                إرسال بيانات التفعيل، الفواتير، وتنبيهات الأمان. يتم حجب كلمات المرور والأسرار الحساسة تلقائياً.
              </p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Field label="خادم البريد (SMTP Host)">
                <input
                  type="text"
                  value={settings.smtpHost || ''}
                  onChange={(e) => setSettings({ ...settings, smtpHost: e.target.value })}
                  className={inputClass}
                  placeholder="smtp.sendgrid.net"
                />
              </Field>
              <Field label="منفذ الخادم (SMTP Port)">
                <input
                  type="number"
                  value={settings.smtpPort || 587}
                  onChange={(e) => setSettings({ ...settings, smtpPort: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="نوع التشفير">
                <select
                  value={settings.smtpEncryption || 'TLS'}
                  onChange={(e) => setSettings({ ...settings, smtpEncryption: e.target.value as any })}
                  className={inputClass}
                >
                  <option value="TLS">STARTTLS (587)</option>
                  <option value="SSL">SSL / TLS (465)</option>
                  <option value="NONE">بدون تشفير</option>
                </select>
              </Field>
              <Field label="اسم مستخدم SMTP">
                <input
                  type="text"
                  value={settings.smtpUser || ''}
                  onChange={(e) => setSettings({ ...settings, smtpUser: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="كلمة مرور SMTP (محمية)">
                <input
                  type="password"
                  value={settings.smtpPassword || ''}
                  onChange={(e) => setSettings({ ...settings, smtpPassword: e.target.value })}
                  className={inputClass}
                  placeholder="اتركها فارغة للإبقاء على الحالية"
                />
              </Field>
              <Field label="عنوان البريد الصادر (From Email)">
                <input
                  type="email"
                  value={settings.smtpFromEmail || ''}
                  onChange={(e) => setSettings({ ...settings, smtpFromEmail: e.target.value })}
                  className={inputClass}
                  placeholder="no-reply@ceramisys.app"
                />
              </Field>
            </div>

            <div className="pt-4 border-t border-slate-100">
              <h4 className="text-xs font-bold text-slate-800 mb-3">بوابة الرسائل النصية القصيرة (SMS Gateway)</h4>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Field label="مزود خدمة SMS">
                  <select
                    value={settings.smsProvider || 'TWILIO'}
                    onChange={(e) => setSettings({ ...settings, smsProvider: e.target.value })}
                    className={inputClass}
                  >
                    <option value="TWILIO">Twilio SMS</option>
                    <option value="UNIFONIC">Unifonic</option>
                    <option value="VICTORY_LINK">Victory Link</option>
                    <option value="CUSTOM">مخصص (Webhook API)</option>
                  </select>
                </Field>
                <Field label="اسم المرسل المعتمد (Sender ID)">
                  <input
                    type="text"
                    value={settings.smsSenderId || ''}
                    onChange={(e) => setSettings({ ...settings, smsSenderId: e.target.value })}
                    className={inputClass}
                    placeholder="CERAMISYS"
                  />
                </Field>
                <Field label="مفتاح API الخاص بـ SMS (محمي)">
                  <input
                    type="password"
                    value={settings.smsApiKey || ''}
                    onChange={(e) => setSettings({ ...settings, smsApiKey: e.target.value })}
                    className={inputClass}
                    placeholder="اتركه فارغاً للإبقاء على الحالي"
                  />
                </Field>
              </div>
            </div>
          </div>
        )}

        {/* 4. Payments & Billing */}
        {activeTab === 'payments' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">بوابات الدفع الإلكتروني وسياسات الفوترة</h3>
              <p className="text-xs text-slate-500">إعداد التحصيل الآلي لاشتراكات وتجديدات تراخيص العملاء.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Field label="بوابة الدفع النشطة">
                <select
                  value={settings.paymentGateway || 'MANUAL'}
                  onChange={(e) => setSettings({ ...settings, paymentGateway: e.target.value as any })}
                  className={inputClass}
                >
                  <option value="PAYMOB">Paymob (بطاقات ومحافظ)</option>
                  <option value="FAWRY">Fawry Pay</option>
                  <option value="STRIPE">Stripe Global</option>
                  <option value="MOYASAR">Moyasar (مدى وفيزا)</option>
                  <option value="MANUAL">تحويل بنكي ودفع يدوي فقط</option>
                </select>
              </Field>
              <Field label="بيئة التشغيل (Payment Mode)">
                <select
                  value={settings.paymentMode || 'TEST'}
                  onChange={(e) => setSettings({ ...settings, paymentMode: e.target.value as any })}
                  className={inputClass}
                >
                  <option value="TEST">بيئة تجريبية (Sandbox / Test)</option>
                  <option value="LIVE">بيئة إنتاجية حية (Live Production)</option>
                </select>
              </Field>
              <Field label="معرف التاجر (Merchant ID)">
                <input
                  type="text"
                  value={settings.paymentMerchantId || ''}
                  onChange={(e) => setSettings({ ...settings, paymentMerchantId: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="المفتاح السري للبوابة (API Secret)">
                <input
                  type="password"
                  value={settings.paymentApiKey || ''}
                  onChange={(e) => setSettings({ ...settings, paymentApiKey: e.target.value })}
                  className={inputClass}
                  placeholder="اتركه فارغاً للإبقاء على الحالي"
                />
              </Field>
              <Field label="نسبة ضريبة القيمة المضافة الافتراضية (%)">
                <input
                  type="number"
                  value={settings.defaultTaxRate || 14}
                  onChange={(e) => setSettings({ ...settings, defaultTaxRate: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="بادئة الفاتورة (Invoice Prefix)">
                <input
                  type="text"
                  value={settings.invoicePrefix}
                  onChange={(e) => setSettings({ ...settings, invoicePrefix: e.target.value })}
                  className={inputClass}
                />
              </Field>
            </div>

            <div className="pt-4 border-t border-slate-100 grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="مدة التجربة المجانية الافتراضية (بالأيام)">
                <input
                  type="number"
                  value={settings.defaultTrialDays}
                  onChange={(e) => setSettings({ ...settings, defaultTrialDays: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="فترة السماح بعد انتهاء الترخيص (Grace Period - أيام)">
                <input
                  type="number"
                  value={settings.licenseGracePeriodDays || 7}
                  onChange={(e) => setSettings({ ...settings, licenseGracePeriodDays: e.target.value })}
                  className={inputClass}
                />
              </Field>
            </div>
          </div>
        )}

        {/* 5. Network & APIs */}
        {activeTab === 'network' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">النطاقات والشهادات وعناوين الـ API</h3>
              <p className="text-xs text-slate-500">إدارة نطاقات المنصة وعناوين خوادم الترخيص والمزامنة السحابية.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="النطاق الرسمي للمنصة (Platform Domain)">
                <input
                  type="text"
                  value={settings.platformDomain || ''}
                  onChange={(e) => setSettings({ ...settings, platformDomain: e.target.value })}
                  className={inputClass}
                  placeholder="app.ceramisys.com"
                />
              </Field>
              <Field label="عنوان خادم الـ API المركزي (Central API Endpoint)">
                <input
                  type="url"
                  value={settings.centralApiEndpoint || ''}
                  onChange={(e) => setSettings({ ...settings, centralApiEndpoint: e.target.value })}
                  className={inputClass}
                  placeholder="https://api.ceramisys.app/v1"
                />
              </Field>
              <Field label="عنوان خادم المزامنة الحية (WebSockets / Sync Endpoint)">
                <input
                  type="text"
                  value={settings.syncServerEndpoint || ''}
                  onChange={(e) => setSettings({ ...settings, syncServerEndpoint: e.target.value })}
                  className={inputClass}
                  placeholder="wss://sync.ceramisys.app"
                />
              </Field>
              <div className="flex items-center gap-3 pt-6">
                <input
                  type="checkbox"
                  id="enforceHttps"
                  checked={settings.enforceHttps !== 'false'}
                  onChange={(e) => setSettings({ ...settings, enforceHttps: e.target.checked ? 'true' : 'false' })}
                  className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                />
                <label htmlFor="enforceHttps" className="text-xs font-semibold text-slate-700 cursor-pointer">
                  إلزام الاتصال الآمن (Enforce HTTPS & HSTS) لجميع العملاء والأجهزة
                </label>
              </div>
            </div>
          </div>
        )}

        {/* 6. Security, MFA & Encryption */}
        {activeTab === 'security' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">أمان المنصة، سياسة كلمات المرور والمصادقة المزدوجة</h3>
              <p className="text-xs text-slate-500">حماية الجلسات وإدارة مفاتيح التشفير من البيئة الآمنة.</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Field label="مهلة خمول الجلسة (Session Timeout بالدقائق)">
                <input
                  type="number"
                  value={settings.sessionTimeoutMinutes || 30}
                  onChange={(e) => setSettings({ ...settings, sessionTimeoutMinutes: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="أقصى عدد محاولات دخول فاشلة قبل الحظر">
                <input
                  type="number"
                  value={settings.maxFailedLogins || 5}
                  onChange={(e) => setSettings({ ...settings, maxFailedLogins: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="الحد الأدنى لطول كلمة المرور">
                <input
                  type="number"
                  value={settings.passwordMinLength || 10}
                  onChange={(e) => setSettings({ ...settings, passwordMinLength: e.target.value })}
                  className={inputClass}
                />
              </Field>
            </div>

            <div className="space-y-3 pt-2">
              <div className="flex items-center gap-3">
                <input
                  type="checkbox"
                  id="enforceMfa"
                  checked={settings.enforceMfa === 'true'}
                  onChange={(e) => setSettings({ ...settings, enforceMfa: e.target.checked ? 'true' : 'false' })}
                  className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                />
                <label htmlFor="enforceMfa" className="text-xs font-semibold text-slate-700 cursor-pointer">
                  إلزام المصادقة متعددة العوامل (Enforce 2FA / TOTP) على كافة مسؤولي المنصة
                </label>
              </div>

              <div className="flex items-center gap-3">
                <input
                  type="checkbox"
                  id="passwordRequireComplex"
                  checked={settings.passwordRequireComplex !== 'false'}
                  onChange={(e) => setSettings({ ...settings, passwordRequireComplex: e.target.checked ? 'true' : 'false' })}
                  className="h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                />
                <label htmlFor="passwordRequireComplex" className="text-xs font-semibold text-slate-700 cursor-pointer">
                  اشتراط تعقيد كلمة المرور (أحرف كبيرة وصغيرة، أرقام، ورموز خاصة)
                </label>
              </div>
            </div>

            {/* Key Management Section */}
            <div className="p-4 rounded-xl border border-indigo-200 bg-indigo-50/40 space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="text-xs font-bold text-indigo-900 flex items-center gap-1.5">
                    <ShieldCheck className="h-4 w-4 text-indigo-600" /> مفاتيح التشفير المركزية (Server-Side Encryption)
                  </h4>
                  <p className="text-[11px] text-slate-600 mt-0.5">
                    المفاتيح الخاصة محفوظة داخل بيئة الخادم المشفرة (KMS / Environment) ولا تخزن داخل القاعدة المحلية.
                  </p>
                </div>
                <Button
                  variant="secondary"
                  size="sm"
                  leadingIcon={<RotateCw className={`h-3.5 w-3.5 ${rotatingKey ? 'animate-spin' : ''}`} />}
                  onClick={handleRotateEncryptionKeys}
                  disabled={rotatingKey || !canManageSettings}
                >
                  تدوير المفاتيح الآن
                </Button>
              </div>

              <div className="grid grid-cols-2 text-xs pt-2 border-t border-indigo-100 text-slate-600">
                <div>
                  مزود التشفير: <strong className="text-slate-800">{settings.kmsProvider || 'Server KMS'}</strong>
                </div>
                <div>
                  تاريخ آخر تدوير:{' '}
                  <strong className="text-slate-800 font-mono">
                    {formatDateTime(settings.lastEncryptionRotation || '2026-01-01')}
                  </strong>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* 7. Backup & Retention */}
        {activeTab === 'backup' && (
          <div className="space-y-6">
            <div>
              <h3 className="text-sm font-bold text-slate-900">سياسة النسخ الاحتياطي والاحتفاظ بالبيانات</h3>
              <p className="text-xs text-slate-500">جدولة إنشاء النسخ الاحتياطية المشفرة وتحديد مدة الاستبقاء.</p>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <Field label="دورية النسخ الاحتياطي التلقائي">
                <select
                  value={settings.backupFrequency || 'DAILY'}
                  onChange={(e) => setSettings({ ...settings, backupFrequency: e.target.value as any })}
                  className={inputClass}
                >
                  <option value="DAILY">يومياً (منتصف الليل)</option>
                  <option value="TWICE_DAILY">مرتين يومياً (كل 12 ساعة)</option>
                  <option value="WEEKLY">أسبوعياً</option>
                </select>
              </Field>
              <Field label="مدة الاحتفاظ بالنسخ (Retention بالـ أيام)">
                <input
                  type="number"
                  value={settings.backupRetentionDays || 90}
                  onChange={(e) => setSettings({ ...settings, backupRetentionDays: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="وجهة التخزين الآمن">
                <select
                  value={settings.backupStorageTarget || 'CLOUD_ENCRYPTED'}
                  onChange={(e) => setSettings({ ...settings, backupStorageTarget: e.target.value as any })}
                  className={inputClass}
                >
                  <option value="CLOUD_ENCRYPTED">سحابة مشفرة بتوقيع AES-256</option>
                  <option value="LOCAL_SECURE">مخزن محلي آمن ومعزول</option>
                </select>
              </Field>
            </div>
          </div>
        )}

        {/* 8. Personal Password Tab */}
        {activeTab === 'password' && (
          <div className="space-y-6 max-w-md">
            <div>
              <h3 className="text-sm font-bold text-slate-900">تغيير كلمة مرور حسابك الحالي</h3>
              <p className="text-xs text-slate-500">حسابك الحالي: {currentUser.fullName} ({currentUser.username})</p>
            </div>

            {passwordError && (
              <div role="alert" className="rounded-lg border border-rose-200 bg-rose-50 px-4 py-2.5 text-xs font-semibold text-rose-700">
                {passwordError}
              </div>
            )}

            <div className="space-y-3">
              <Field label="كلمة المرور الحالية">
                <input
                  type="password"
                  value={passwordForm.current}
                  onChange={(e) => setPasswordForm({ ...passwordForm, current: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="كلمة المرور الجديدة">
                <input
                  type="password"
                  value={passwordForm.next}
                  onChange={(e) => setPasswordForm({ ...passwordForm, next: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Field label="تأكيد كلمة المرور الجديدة">
                <input
                  type="password"
                  value={passwordForm.confirm}
                  onChange={(e) => setPasswordForm({ ...passwordForm, confirm: e.target.value })}
                  className={inputClass}
                />
              </Field>
              <Button
                variant="primary"
                size="sm"
                onClick={changePassword}
                disabled={changingPassword || !passwordForm.current || !passwordForm.next}
                leadingIcon={<KeyRound className="h-3.5 w-3.5" />}
              >
                {changingPassword ? 'جارٍ التغيير...' : 'تحديث كلمة المرور'}
              </Button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default PlatformSettingsPage;

import React, { useState, useEffect, useCallback } from 'react';
import {
  CalendarClock,
  Layers3,
  Search,
  CheckCircle2,
  XCircle,
  AlertTriangle,
  RotateCw,
  Ban,
  Download,
  Building2,
  ArrowUpRight,
  RefreshCw,
  TrendingUp,
} from 'lucide-react';
import { platformAdminService } from '../../services/domains/platform/PlatformAdminService';
import { canPlatform } from '../../hooks/platform/usePlatformPermission';
import type {
  PlatformSubscription,
  PlatformPlan,
  PlatformTenant,
} from '../../services/domains/platform/platformTypes';
import { PageHeader } from '../../components/ui/PageHeader';
import { Button } from '../../components/ui/Button';
import { Modal } from '../../components/ui/Modal';
import {
  EmptyState,
  StatusBadge,
  formatDate,
  formatDateTime,
  formatMoney,
  inputClass,
  downloadCsv,
} from './components/PlatformUI';

const CYCLE_LABELS: Record<string, string> = {
  MONTHLY: 'شهري',
  QUARTERLY: 'ربع سنوي',
  YEARLY: 'سنوي',
  LIFETIME: 'مدى الحياة',
};

export const PlatformSubscriptionsPage: React.FC = () => {
  const [subscriptions, setSubscriptions] = useState<PlatformSubscription[]>([]);
  const canManageSubscriptions = canPlatform('subscriptions');
  const [plans, setPlans] = useState<PlatformPlan[]>([]);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [planFilter, setPlanFilter] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  // Renew / Change Plan Modal
  const [activeSub, setActiveSub] = useState<PlatformSubscription | null>(null);
  const [actionType, setActionType] = useState<'RENEW' | 'CHANGE_PLAN'>('RENEW');
  const [renewMonths, setRenewMonths] = useState(12);
  const [newPlanId, setNewPlanId] = useState('');

  const loadData = useCallback(() => {
    setLoading(true);
    try {
      const subs = platformAdminService.listSubscriptions({
        status: statusFilter,
        planId: planFilter,
        search,
      });
      const plns = platformAdminService.listPlans();
      setSubscriptions(subs);
      setPlans(plns);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'تعذر تحميل الاشتراكات.');
    } finally {
      setLoading(false);
    }
  }, [search, statusFilter, planFilter]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleRenew = (sub: PlatformSubscription) => {
    setActiveSub(sub);
    setActionType('RENEW');
    setRenewMonths(12);
  };

  const handleChangePlan = (sub: PlatformSubscription) => {
    setActiveSub(sub);
    setActionType('CHANGE_PLAN');
    setNewPlanId(sub.planId);
    setRenewMonths(12);
  };

  const handleExecuteModal = () => {
    if (!activeSub) return;
    if (!canManageSubscriptions) { alert('لا تملك صلاحية إدارة الاشتراكات.'); return; }
    try {
      if (actionType === 'RENEW') {
        platformAdminService.renewTenantSubscription(activeSub.tenantId, renewMonths);
        alert(`تم تجديد الاشتراك بنجاح لمدة ${renewMonths} شهر.`);
      } else {
        if (!newPlanId) {
          alert('يرجى اختيار الباقة الجديدة.');
          return;
        }
        platformAdminService.changeTenantPlan(activeSub.tenantId, newPlanId, {
          months: renewMonths,
          seats: activeSub.seats,
        });
        alert('تم نقل العميل إلى الخطة الجديدة بنجاح.');
      }
      setActiveSub(null);
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'فشلت العملية.');
    }
  };

  const handleCancelSub = (sub: PlatformSubscription) => {
    if (!canManageSubscriptions) { alert('لا تملك صلاحية إدارة الاشتراكات.'); return; }
    if (!confirm(`هل أنت متأكد من إلغاء اشتراك "${sub.tenantName || sub.tenantId}"؟ سيتم إبطال التراخيص والحساب المرتبط.`)) return;
    try {
      platformAdminService.cancelTenantSubscription(sub.tenantId, 'إلغاء يدوي من لوحة إدارة الاشتراكات المركزية');
      loadData();
    } catch (err) {
      alert(err instanceof Error ? err.message : 'تعذر إلغاء الاشتراك.');
    }
  };

  const exportSubscriptions = () => {
    if (!canManageSubscriptions) { alert('لا تملك صلاحية إدارة الاشتراكات.'); return; }
    downloadCsv('platform-subscriptions.csv', [
      ['رقم الاشتراك', 'العميل', 'الباقة', 'الحالة', 'تاريخ البدء', 'تاريخ الانتهاء', 'القيمة', 'دورة الفوترة', 'التجديد التلقائي'],
      ...subscriptions.map((s) => [
        s.id,
        s.tenantName || s.tenantId,
        s.planName || s.planId,
        s.status,
        s.startDate,
        s.endDate || '—',
        s.price,
        CYCLE_LABELS[s.billingCycle] || s.billingCycle,
        s.autoRenew ? 'نعم' : 'لا',
      ]),
    ]);
  };

  return (
    <div className="space-y-4 text-right">
      <PageHeader
        title="إدارة الاشتراكات المركزية (Subscriptions Management)"
        description="واجهة مركزية مستقلة لعقود الاشتراك، التجديدات، الانتقال بين الباقات، والإلغاء الجماعي."
        icon={<CalendarClock className="h-5 w-5" />}
        actions={
          <div className="flex gap-2">
            {canManageSubscriptions && (
              <Button
                size="sm"
                variant="secondary"
                onClick={exportSubscriptions}
                leadingIcon={<Download className="h-4 w-4" />}
              >
                تصدير CSV
              </Button>
            )}
            <Button
              size="sm"
              onClick={loadData}
              leadingIcon={<RefreshCw className="h-4 w-4" />}
            >
              تحديث البيانات
            </Button>
          </div>
        }
      />

      {/* Metrics Row */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="p-3 bg-slate-900/60 border border-slate-800 rounded-xl">
          <p className="text-[11px] font-semibold text-slate-400">إجمالي الاشتراكات</p>
          <p className="text-xl font-black text-slate-100 mt-1">{subscriptions.length}</p>
        </div>
        <div className="p-3 bg-emerald-950/20 border border-emerald-500/20 rounded-xl">
          <p className="text-[11px] font-semibold text-emerald-400">الاشتراكات النشطة</p>
          <p className="text-xl font-black text-emerald-300 mt-1">
            {subscriptions.filter((s) => s.status === 'ACTIVE').length}
          </p>
        </div>
        <div className="p-3 bg-amber-950/20 border border-amber-500/20 rounded-xl">
          <p className="text-[11px] font-semibold text-amber-400">الفترة التجريبية (Trial)</p>
          <p className="text-xl font-black text-amber-300 mt-1">
            {subscriptions.filter((s) => s.status === 'TRIAL').length}
          </p>
        </div>
        <div className="p-3 bg-rose-950/20 border border-rose-500/20 rounded-xl">
          <p className="text-[11px] font-semibold text-rose-400">ملغاة أو منتهية</p>
          <p className="text-xl font-black text-rose-300 mt-1">
            {subscriptions.filter((s) => s.status === 'CANCELLED' || s.status === 'EXPIRED').length}
          </p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-2 rounded-xl border border-slate-800 bg-slate-900/60 p-3 shadow-sm">
        <div className="relative min-w-[240px] flex-1">
          <Search className="pointer-events-none absolute right-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-500" />
          <input
            type="text"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="البحث باسم العميل أو كود المستأجر..."
            className={`${inputClass} pr-9`}
          />
        </div>

        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          className={`${inputClass} max-w-[170px]`}
        >
          <option value="">جميع الحالات</option>
          <option value="ACTIVE">نشط (Active)</option>
          <option value="TRIAL">تجريبي (Trial)</option>
          <option value="EXPIRED">منتهي (Expired)</option>
          <option value="CANCELLED">ملغي (Cancelled)</option>
          <option value="PAST_DUE">متأخر الدفع (Past Due)</option>
        </select>

        <select
          value={planFilter}
          onChange={(e) => setPlanFilter(e.target.value)}
          className={`${inputClass} max-w-[190px]`}
        >
          <option value="">جميع الباقات</option>
          {plans.map((p) => (
            <option key={p.id} value={p.id}>
              {p.name}
            </option>
          ))}
        </select>
      </div>

      {error && (
        <div className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-lg text-xs font-bold text-rose-300">
          {error}
        </div>
      )}

      {/* Table */}
      <div className="overflow-hidden rounded-xl border border-slate-800 bg-slate-900/70 shadow-sm">
        {loading ? (
          <div className="py-16 text-center text-sm font-semibold text-slate-500">جارٍ تحميل الاشتراكات...</div>
        ) : subscriptions.length === 0 ? (
          <EmptyState
            icon={<CalendarClock className="h-6 w-6 text-slate-500" />}
            title="لا توجد اشتراكات مطابقة"
            description="غيّر عوامل التصفية أو أضف اشتراكات جديدة للعملاء."
          />
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full min-w-[950px] text-right text-xs">
              <thead className="border-b border-slate-800 bg-slate-950/50 text-[11px] font-bold text-slate-400">
                <tr>
                  <th className="px-4 py-3">العميل / المستأجر</th>
                  <th className="px-4 py-3">الباقة</th>
                  <th className="px-4 py-3">الحالة</th>
                  <th className="px-4 py-3">القيمة والفوترة</th>
                  <th className="px-4 py-3">البداية</th>
                  <th className="px-4 py-3">نهاية الصلاحية</th>
                  <th className="px-4 py-3">التجديد التلقائي</th>
                  <th className="px-4 py-3 text-center">إجراءات</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-800/80">
                {subscriptions.map((sub) => (
                  <tr key={sub.id} className="hover:bg-slate-800/30 transition-colors">
                    <td className="px-4 py-3">
                      <div className="font-bold text-slate-100">{sub.tenantName || 'عميل غير مسمى'}</div>
                      <div className="text-[10px] font-mono text-slate-500">{sub.tenantId}</div>
                    </td>

                    <td className="px-4 py-3 font-semibold text-slate-200">
                      {sub.planName || 'باقة محذوفة'}
                    </td>

                    <td className="px-4 py-3">
                      <span
                        className={`font-bold inline-flex items-center gap-1 ${
                          sub.status === 'ACTIVE'
                            ? 'text-emerald-400'
                            : sub.status === 'TRIAL'
                            ? 'text-sky-400'
                            : 'text-rose-400'
                        }`}
                      >
                        {sub.status === 'ACTIVE' ? 'نشط' : sub.status === 'TRIAL' ? 'تجريبي' : sub.status}
                      </span>
                    </td>

                    <td className="px-4 py-3">
                      <div className="font-bold text-slate-200">{formatMoney(sub.price)}</div>
                      <div className="text-[10px] text-slate-500">{CYCLE_LABELS[sub.billingCycle] || sub.billingCycle}</div>
                    </td>

                    <td className="px-4 py-3 text-slate-400">{formatDate(sub.startDate)}</td>

                    <td className="px-4 py-3">
                      <span
                        className={`font-semibold ${
                          sub.endDate && new Date(sub.endDate) < new Date() ? 'text-rose-400 font-bold' : 'text-slate-300'
                        }`}
                      >
                        {sub.endDate ? formatDate(sub.endDate) : 'مفتوح (مدى الحياة)'}
                      </span>
                    </td>

                    <td className="px-4 py-3">
                      <span className={sub.autoRenew ? 'text-emerald-400' : 'text-slate-500'}>
                        {sub.autoRenew ? 'مفعل' : 'معطل'}
                      </span>
                    </td>

                    <td className="px-4 py-3 text-center">
                      <div className="flex items-center justify-center gap-2">
                        {canManageSubscriptions && (
                          <>
                            <button
                              onClick={() => handleRenew(sub)}
                              className="text-emerald-400 hover:text-emerald-300 text-xs flex items-center gap-1"
                              title="تجديد مدة الاشتراك"
                            >
                              <RotateCw className="h-3 w-3" />
                              تجديد
                            </button>

                            <button
                              onClick={() => handleChangePlan(sub)}
                              className="text-sky-400 hover:text-sky-300 text-xs flex items-center gap-1"
                              title="ترقية أو تخفيض الباقة"
                            >
                              <ArrowUpRight className="h-3 w-3" />
                              تغيير الباقة
                            </button>

                            {sub.status !== 'CANCELLED' && (
                              <button
                                onClick={() => handleCancelSub(sub)}
                                className="text-rose-400 hover:text-rose-300 text-xs"
                                title="إلغاء الاشتراك فوراً"
                              >
                                إلغاء
                              </button>
                            )}
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Renew / Change Plan Modal */}
      <Modal
        open={Boolean(activeSub)}
        onClose={() => setActiveSub(null)}
        title={
          actionType === 'RENEW'
            ? `تجديد اشتراك: ${activeSub?.tenantName || activeSub?.tenantId}`
            : `تغيير باقة: ${activeSub?.tenantName || activeSub?.tenantId}`
        }
      >
        <div className="space-y-3.5 text-right">
          {actionType === 'CHANGE_PLAN' && (
            <div>
              <label className="block text-xs font-semibold text-slate-300 mb-1">اختر الباقة الجديدة *</label>
              <select
                value={newPlanId}
                onChange={(e) => setNewPlanId(e.target.value)}
                className={inputClass}
              >
                {plans.map((p) => (
                  <option key={p.id} value={p.id}>
                    {p.name} — {formatMoney(p.price)}
                  </option>
                ))}
              </select>
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-slate-300 mb-1">
              {actionType === 'RENEW' ? 'عدد أشهر التجديد الإضافية' : 'فترة الاشتراك بالباقة الجديدة (بالأشهر)'}
            </label>
            <select
              value={renewMonths}
              onChange={(e) => setRenewMonths(Number(e.target.value))}
              className={inputClass}
            >
              <option value={1}>شهر واحد</option>
              <option value={3}>3 أشهر (ربع سنوي)</option>
              <option value={6}>6 أشهر (نصف سنوي)</option>
              <option value={12}>12 شهر (سنة كاملة)</option>
              <option value={24}>24 شهر (سنتين)</option>
            </select>
          </div>

          <div className="flex justify-end gap-2 pt-3 border-t border-slate-800">
            <Button variant="secondary" size="sm" onClick={() => setActiveSub(null)}>
              إلغاء
            </Button>
            <Button size="sm" onClick={handleExecuteModal} disabled={!canManageSubscriptions}>
              تأكيد العملية
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
};

