      );
    } else {
      this.db.run(
        'INSERT INTO platform_settings (key, value, updated_at) VALUES (?, ?, ?)',
        ['platform.dataSource', normalized, now]
      );
    }
    this.audit('تغيير مصدر بيانات المنصة', 'PLATFORM_SETTING', 'platform.dataSource', { value: normalized });
