    PlatformStaffService.requirePlatformAccess('staff', 'platform.staff.logins');

    const where: string[] = [];
    const params: (string | number)[] = [];

    if (failedOnly) where.push('success = 0');
    if (staffId) {
      where.push('staff_id = ?');
      params.push(staffId);
