        toNumber(plan.offlineGracePeriodDays, 14), 'FULL', 'تجريبي',
      ]
    );

    // Update tenant
    this.db.run(
      `UPDATE platform_tenants SET plan_id = ?, subscription_started_at = ?, subscription_expires_at = ?,
         seats_limit = ?, branches_limit = ?, devices_limit = ?, updated_at = ?
       WHERE id = ?`,
