export const platformTenantService = new PlatformTenantService();

import { DatabaseManager } from '../../../database/repositories/databaseManager';
import { provisioningQueueService, PROVISIONING_MAX_ATTEMPTS, type ProvisioningJob } from './ProvisioningQueueService';
import { identityLinkService } from './IdentityLinkService';
import { centralAuditService } from './CentralAuditService';

/**
 * Executes queued tenant-identity provisioning jobs.
 *
 * The queue is the contract between the platform console and the tenant's
 * identity system. A job only reaches PROVISIONED — and the directory record
 * only reaches PROVISIONED with a linked identity — when the configured
 * endpoint confirms creation. Without a configured channel, jobs stay PENDING
 * with an explicit `last_error`; nothing ever reports PROVISIONED on a guess.
 *
 * Configuration (platform_settings):
 *   platform.provisioningPath — central-server-relative path the tenant ERP
 *   exposes for identity provisioning, e.g. `/api/v1/tenants/users`. The path
 *   must be allowlisted in electron/centralRoutes.generated.js (the bridge
 *   will refuse anything else). When unset, provisioning is deferred.
 *
 * Retry policy: a failing channel marks the job RETRYING with attempts+1 and a
 * backoff delay; jobs whose attempts reach the max are terminal FAILED.
 * Jobs with attempts >= MAX_ATTEMPTS are no longer picked up. Deferrals
 * (no bridge, no channel configured) never burn an attempt.
 */

export type ProvisioningDrainResult = {
  picked: number;
  succeeded: number;
  failed: number;
  deferred: number;
  retrying: number;
};

const CHANNEL_SETTING = 'platform.provisioningPath';

function nowIso(): string {
  return new Date().toISOString();
}

export class ProvisioningExecutorService {
  private db = DatabaseManager.getInstance();
  private draining = false;

  /** Fire-and-forget drain; safe to call from request paths. */
  public requestDrain(): void {
    if (this.draining) return;
    this.draining = true;
    void this.processPending(20)
      .catch(() => undefined)
      .finally(() => {
        this.draining = false;
      });
  }

  public async processPending(limit = 20): Promise<ProvisioningDrainResult> {
    const now = new Date().toISOString();
    // Expiry sweep: outstanding invites/attempts whose window elapsed are
    // cancelled rather than retried blindly.
    for (const expired of provisioningQueueService.listExpired()) {
      provisioningQueueService.markCancelled(expired.id, 'EXPIRED');
    }
    const jobs = provisioningQueueService
      .listPending(limit)
      .filter((job) => (job.status === 'PENDING' || job.status === 'RETRYING') && job.attempts < PROVISIONING_MAX_ATTEMPTS);

    const result: ProvisioningDrainResult = { picked: jobs.length, succeeded: 0, failed: 0, deferred: 0, retrying: 0 };
    for (const job of jobs) {
      const outcome = await this.processJob(job);
      if (outcome === 'done') result.succeeded += 1;
      else if (outcome === 'failed') result.failed += 1;
      else if (outcome === 'retrying') result.retrying += 1;
      else result.deferred += 1;
    }
    return result;
  }

  private setting(key: string, fallback: string): string {
    try {
      const row = this.db.query<{ value: string }>(
        'SELECT value FROM platform_settings WHERE key = ? LIMIT 1',
        [key],
      )[0];
      return row?.value != null ? String(row.value) : fallback;
    } catch {
      return fallback;
    }
  }

  private bridge(): { request: (req: Record<string, unknown>) => Promise<any> } | null {
    const central = typeof globalThis !== 'undefined' ? (globalThis as any)?.window?.ceramisys?.central : null;
    return central && typeof central.request === 'function' ? central : null;
  }

  private audit(tenantId: string, tenantUserId: string, action: string, details?: unknown, severity = 'NOTICE'): void {
    try {
      centralAuditService.log(
        { id: null, fullName: 'Platform Provisioning Executor', role: 'SYSTEM' },
        {
          action,
          entityType: 'TENANT_USER',
          entityId: tenantUserId,
          tenantId,
          actorType: 'SYSTEM',
          severity: severity as any,
          details,
        } as any,
      );
    } catch {
      // Audit must never break provisioning bookkeeping.
    }
  }

  private defer(job: ProvisioningJob, reason: string): void {
    // Deferring is not a failure of the tenant channel's health — it means no
    // channel exists yet. Keep the job PENDING, record why, burn no attempt.
    try {
      const row = this.db.query<any>(
        'SELECT last_error FROM provisioning_queue WHERE id = ? LIMIT 1',
        [job.id],
      )[0];
      const currentError = String(row?.lastError ?? row?.last_error ?? '') || '';
      if (currentError !== reason) {
        this.db.run(`UPDATE provisioning_queue SET status = 'PENDING', last_error = ?, updated_at = ? WHERE id = ?`, [reason, nowIso(), job.id]);
        try {
          this.db.run(
            `UPDATE platform_tenant_users SET last_error = ?, updated_at = ? WHERE id = ?`,
            [reason, nowIso(), job.tenantUserId],
          );
        } catch {
          // best effort
        }
        this.audit(job.tenantId, job.tenantUserId, 'TENANT_USER_PROVISION_DEFERRED', { reason, jobId: job.id });
      }
    } catch {
      // best effort
    }
  }

  private async processJob(job: ProvisioningJob): Promise<'done' | 'failed' | 'deferred' | 'retrying'> {
    const bridge = this.bridge();
    const provisioningPath = this.setting(CHANNEL_SETTING, '').trim();
    if (!bridge) {
      this.defer(job, 'CENTRAL_BRIDGE_UNAVAILABLE');
      return 'deferred';
    }
    if (!provisioningPath) {
      this.defer(job, 'TENANT_IDENTITY_CHANNEL_NOT_CONFIGURED');
      return 'deferred';
    }

    // Move the job into PROCESSING so observers see the in-flight state.
    provisioningQueueService.markProcessing(job.id);

    const tenantUser = this.db.query<any>(
      'SELECT * FROM platform_tenant_users WHERE id = ? LIMIT 1',
      [job.tenantUserId],
    )[0];
    if (!tenantUser) {
      if (this.markFailed(job, 'TENANT_USER_NOT_FOUND', true) === 'FAILED') {
        return 'failed';
      }
      return 'retrying';
    }

    try {
      const response = await bridge.request({
        path: provisioningPath,
        method: 'POST',
        headers: { 'Idempotency-Key': job.id },
        body: {
          tenantId: job.tenantId,
          tenantUserId: job.tenantUserId,
          username: tenantUser.username ?? null,
          fullName: tenantUser.fullName ?? tenantUser.full_name ?? null,
          email: tenantUser.email ?? null,
          phone: tenantUser.phone ?? null,
          role: tenantUser.role ?? null,
          scope: tenantUser.scope ?? null,
          mode: tenantUser.provisioningMode ?? tenantUser.provisioning_mode ?? null,
          inviteExpiresAt: tenantUser.inviteExpiresAt ?? tenantUser.invite_expires_at ?? null,
          idempotencyKey: job.id,
          event: job.event,
        },
      });

      if (!response || response.ok === false) {
        throw new Error(String(response?.error || 'Provisioning endpoint rejected the request'));
      }

      const identityUserId =
        response?.data?.identityUserId ?? response?.identityUserId ?? response?.data?.identity_user_id ?? null;

      const now = nowIso();
      this.db.run(
        `UPDATE platform_tenant_users
            SET provisioning_status = 'PROVISIONED',
                identity_user_id = COALESCE(?, identity_user_id),
                provisioned_at = ?,
                last_error = NULL,
                updated_at = ?
          WHERE id = ?`,
        [identityUserId, now, now, job.tenantUserId],
      );
      provisioningQueueService.markDone(job.id);

      if (!identityLinkService.findByTenantUser(job.tenantUserId)) {
        identityLinkService.link({ tenantUserId: job.tenantUserId, linkType: 'TENANT_USER' });
      }
      this.audit(job.tenantId, job.tenantUserId, 'TENANT_USER_PROVISIONED', {
        jobId: job.id,
        identityUserId,
        mode: tenantUser.provisioningMode ?? tenantUser.provisioning_mode ?? null,
      });
      return 'done';
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      const next = this.markFailed(job, message);
      // RETRYING keeps the job queued with backoff; FAILED is terminal.
      return next === 'FAILED' ? 'failed' : 'retrying';
    }
  }

  private markFailed(job: ProvisioningJob, message: string, terminal = false): 'FAILED' | 'RETRYING' {
    // Queue signature takes `retry` (true = may retry later, terminal at cap);
    // executor's `terminal` is the inverse — map it or every failure goes terminal.
    const next = provisioningQueueService.markFailed(job.id, message, !terminal);
    if (next === 'FAILED') {
      try {
        this.db.run(
          `UPDATE platform_tenant_users
              SET provisioning_status = 'FAILED', last_error = ?, updated_at = ?
            WHERE id = ?`,
          [message.slice(0, 500), nowIso(), job.tenantUserId],
        );
      } catch {
        // best effort
      }
    }
    this.audit(job.tenantId, job.tenantUserId, 'TENANT_USER_PROVISION_FAILED', { jobId: job.id, message }, 'WARNING');
    return next;
  }
}

export const provisioningExecutorService = new ProvisioningExecutorService();

import { DatabaseManager } from '../../../database/repositories/databaseManager';
import { v4 as uuidv4 } from 'uuid';

/**
 * Provisioning job lifecycle.
 *
 * Canonical transitions (no skipping allowed):
 *   PENDING ──enqueue──▶ PENDING            (first submission; idempotency-keyed)
 *   PENDING ──PROCESS──▶ PROCESSING         (executor picked the job up)
 *   PROCESSING ──success──▶ PROVISIONED     (tenant identity system confirmed)
 *   PROCESSING ──fail──▶ RETRYING|FAILED   (transient → RETRYING, attempts<5)
 *   PENDING/RETRYING ──retry-scheduled──▶ RETRYING
 *   any active ──cancel──▶ CANCELLED        (manual/super admin stop)
 *   PENDING/RETRYING ──expire──▶ CANCELLED  (invite/expiry window elapsed)
 *
 * Retry policy: a failing channel marks the job RETRYING with attempts+1 and a
 * backoff delay; jobs whose attempts reach MAX_ATTEMPTS land in FAILED
 * (terminal). Deferrals (no bridge / channel not configured) keep the job
 * PENDING and record a reason without burning an attempt.
 */
export const PROVISIONING_JOB_STATUSES = [
  'PENDING',
  'PROCESSING',
  'PROVISIONED',
  'FAILED',
  'RETRYING',
  'CANCELLED',
] as const;

export type ProvisioningJobStatus = (typeof PROVISIONING_JOB_STATUSES)[number];

export interface ProvisioningJob {
  id: string;
  tenantId: string;
  tenantUserId: string;
  event: string;
  payload: string;
  status: ProvisioningJobStatus;
  attempts: number;
  lastError: string | null;
  idempotencyKey: string | null;
  expiresAt: string | null;
  createdAt: string;
  updatedAt: string;
}

export const PROVISIONING_MAX_ATTEMPTS = 5;
const RETRY_BACKOFF_MS = 30_000;

function nowIso(): string {
  return new Date().toISOString();
}

export class ProvisioningQueueService {
  private db = DatabaseManager.getInstance();

  ensureSchema(): void {
    this.db.run(`CREATE TABLE IF NOT EXISTS provisioning_queue (
      id TEXT PRIMARY KEY,
      tenant_id TEXT NOT NULL,
      tenant_user_id TEXT NOT NULL,
      event TEXT NOT NULL,
      payload TEXT NOT NULL,
      status TEXT NOT NULL DEFAULT 'PENDING',
      attempts INTEGER NOT NULL DEFAULT 0,
      last_error TEXT,
      idempotency_key TEXT,
      expires_at TEXT,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    )`);
    // Transitional migrations for databases created by older builds of this
    // feature (no destructive changes; only additive columns).
    try {
      this.db.run(`ALTER TABLE provisioning_queue ADD COLUMN idempotency_key TEXT`);
    } catch {
      /* already present */
    }
    try {
      this.db.run(`ALTER TABLE provisioning_queue ADD COLUMN expires_at TEXT`);
    } catch {
      /* already present */
    }
  }

  enqueue(
    tenantId: string,
    tenantUserId: string,
    event: string,
    payload: Record<string, unknown>,
    expiresAt?: string | null,
  ): ProvisioningJob {
    this.ensureSchema();
    const id = `prvq_${uuidv4().replace(/-/g, '').slice(0, 12)}`;
    const now = nowIso();
    const payloadStr = JSON.stringify(payload);
    const key = `${event}:${tenantId}:${tenantUserId}`;
    // Idempotent enqueue: a retry of the same logical request never starts a
    // second job while the previous one is still active.
    const existing = this.db.query<any>(
      `SELECT * FROM provisioning_queue WHERE idempotency_key = ? AND status IN ('PENDING','PROCESSING','RETRYING') LIMIT 1`,
      [key],
    )[0];
    if (existing) {
      return this.map({ ...existing, status: (existing.status as ProvisioningJobStatus) ?? 'PENDING', attempts: Number(existing.attempts || 0), lastError: existing.last_error ?? existing.lastError ?? null });
    }
    this.db.run(
      `INSERT INTO provisioning_queue (id, tenant_id, tenant_user_id, event, payload, status, attempts, last_error, idempotency_key, expires_at, created_at, updated_at)
       VALUES (?, ?, ?, ?, ?, 'PENDING', 0, NULL, ?, ?, ?, ?)`,
      [id, tenantId, tenantUserId, event, payloadStr, key, expiresAt ?? null, now, now],
    );
    return {
      id,
      tenantId,
      tenantUserId,
      event,
      payload: payloadStr,
      status: 'PENDING',
      attempts: 0,
      lastError: null,
      idempotencyKey: key,
      expiresAt: expiresAt ?? null,
      createdAt: now,
      updatedAt: now,
    };
  }

  /** Jobs eligible for execution: active, not expired, within retry budget. */
  listPending(limit = 50): ProvisioningJob[] {
    this.ensureSchema();
    const rows = this.db.query<any>(
      `SELECT * FROM provisioning_queue
       WHERE status IN ('PENDING','RETRYING')
         AND (? IS NULL OR expires_at IS NULL OR expires_at > ?)
       ORDER BY created_at ASC
       LIMIT ?`,
      [nowIso(), nowIso(), limit],
    );
    return rows.map(this.map);
  }

  /** Jobs that are considered expired (invite window elapsed) → CANCELLED. */
  listExpired(): ProvisioningJob[] {
    this.ensureSchema();
    const now = nowIso();
    const rows = this.db.query<any>(
      `SELECT * FROM provisioning_queue
       WHERE status IN ('PENDING','RETRYING') AND expires_at IS NOT NULL AND expires_at <= ?
       ORDER BY created_at ASC`,
      [now],
    );
    return rows.map(this.map);
  }

  markProcessing(id: string): void {
    this.ensureSchema();
    this.db.run(`UPDATE provisioning_queue SET status='PROCESSING', updated_at=? WHERE id=?`, [nowIso(), id]);
  }

  markDone(id: string, status: 'PROVISIONED' | 'DONE' = 'PROVISIONED'): void {
    this.ensureSchema();
    // Legacy callers may still pass the old terminal status name; both map to
    // the canonical PROVISIONED outcome.
    const next: ProvisioningJobStatus = status === 'DONE' ? 'PROVISIONED' : status;
    this.db.run(`UPDATE provisioning_queue SET status=?, updated_at=? WHERE id=?`, [next, nowIso(), id]);
  }

  markFailed(id: string, error: string, retry = true): 'FAILED' | 'RETRYING' {
    this.ensureSchema();
    const row = this.db.query<any>('SELECT attempts FROM provisioning_queue WHERE id = ? LIMIT 1', [id])[0];
    const attempts = Number(row?.attempts || 0) + 1;
    const terminal = attempts >= PROVISIONING_MAX_ATTEMPTS;
    const status: ProvisioningJobStatus = !retry || terminal ? 'FAILED' : 'RETRYING';
    const lastError = error.slice(0, 500);
    this.db.run(
      `UPDATE provisioning_queue SET status=?, attempts=?, last_error=?, updated_at=? WHERE id=?`,
      [status, attempts, lastError, nowIso(), id],
    );
    return status;
  }

  markRetrying(id: string, error: string): 'FAILED' | 'RETRYING' {
    this.ensureSchema();
    const row = this.db.query<any>('SELECT attempts FROM provisioning_queue WHERE id = ? LIMIT 1', [id])[0];
    const attempts = Number(row?.attempts || 0) + 1;
    const status: ProvisioningJobStatus = attempts >= PROVISIONING_MAX_ATTEMPTS ? 'FAILED' : 'RETRYING';
    this.db.run(
      `UPDATE provisioning_queue SET status=?, attempts=?, last_error=?, updated_at=? WHERE id=?`,
      [status, attempts, error.slice(0, 500), nowIso(), id],
    );
    return status;
  }

  markCancelled(id: string, reason = 'CANCELLED'): void {
    this.ensureSchema();
    this.db.run(
      `UPDATE provisioning_queue SET status='CANCELLED', last_error=?, updated_at=? WHERE id=?`,
      [reason, nowIso(), id],
    );
  }

  private map(row: any): ProvisioningJob {
    // DatabaseManager normalizes snake_case columns to camelCase on read;
    // accept both shapes so direct rows also map correctly.
    const tenantId = row.tenantId ?? row.tenant_id;
    const tenantUserId = row.tenantUserId ?? row.tenant_user_id;
    const lastError = row.lastError ?? row.last_error ?? null;
    const idempotencyKey = row.idempotencyKey ?? row.idempotency_key ?? null;
    const expiresAt = row.expiresAt ?? row.expires_at ?? null;
    const rawStatus = String(row.status ?? 'PENDING');
    const status = (PROVISIONING_JOB_STATUSES as readonly string[]).includes(rawStatus)
      ? (rawStatus as ProvisioningJobStatus)
      : 'PENDING';
    return {
      id: String(row.id),
      tenantId: String(tenantId),
      tenantUserId: String(tenantUserId),
      event: String(row.event),
      payload: String(row.payload),
      status,
      attempts: Number(row.attempts || 0),
      lastError: lastError == null ? null : String(lastError),
      idempotencyKey: idempotencyKey == null ? null : String(idempotencyKey),
      expiresAt: expiresAt == null ? null : String(expiresAt),
      createdAt: String(row.createdAt ?? row.created_at),
      updatedAt: String(row.updatedAt ?? row.updated_at),
    };
  }
}

