  assert.equal(ledgerCredit('SALES_RETURN', saleReturn.id, '1101'), 1200, 'cash refund credited');
  assert.equal(ledgerCredit('SALES_RETURN', saleReturn.id, '1103'), 0, 'no AR reduction on a paid invoice');
});

