// ── Cross-check: the new audit service agrees with the flows above ──────────
test('e2e stock balance audit reports clean pairs after real operations', async () => {
  const { StockBalanceAuditService } = await import('../src/services/domains/inventory/StockBalanceAuditService.ts');
  const report = new StockBalanceAuditService().runAudit({ warehouseId: 'wh_main' });
  const drifted = report.rows.filter((r) => r.status === 'DISCREPANCY');
  // Products touched by sales/purchases above keep warehouse_stock consistent
  // with the movement ledger; any discrepancy must be a seeded-only artifact.
  for (const row of drifted.filter((r) => String(r.productId).includes('prod_e2e'))) {
    const stockCheck = row.checks.find((c) => c.key === 'STOCK_VS_LEDGER');
    assert.fail(`E2E product ${row.productId} drifted: book=${stockCheck?.book} ledger=${stockCheck?.ledger}`);
  }
});

import '../integration.setup.ts';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createCipheriv, createDecipheriv, randomBytes, scrypt } from 'node:crypto';
import { DatabaseManager } from '../../src/database/repositories/databaseManager.ts';
import fs from 'fs';
import os from 'os';
import path from 'path';

const MAGIC = Buffer.from('CERAMISYS-DB\0v1\0', 'utf8');

function encryptDbBytes(plaintext: Buffer, key: Buffer): Buffer {
  const iv = randomBytes(12);
  const cipher = createCipheriv('aes-256-gcm', key, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();
  return Buffer.concat([MAGIC, iv, tag, ciphertext]);
}

function decryptDbBytes(encrypted: Buffer, key: Buffer): Buffer {
  const data = Buffer.from(encrypted);
  if (!data.subarray(0, MAGIC.length).equals(MAGIC)) return data;
  const iv = data.subarray(MAGIC.length, MAGIC.length + 12);
  const tag = data.subarray(MAGIC.length + 12, MAGIC.length + 28);
  const ciphertext = data.subarray(MAGIC.length + 28);
  const decipher = createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}

const RECOVERY_FORMAT = 'CERAMISYS-RECOVERY-KEY';
const RECOVERY_SCRYPT = { N: 1 << 15, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };

function deriveRecoveryKey(password: string, salt: Buffer, keyLength: number): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    scrypt(password, salt, keyLength, RECOVERY_SCRYPT, (err, key) => err ? reject(err) : resolve(key as Buffer));
  });
}

async function encryptRecoveryKey(key: Buffer, password: string): Promise<Buffer> {
  if (key.length !== 32) throw new Error('Invalid key length');
  if (typeof password !== 'string' || password.length < 12 || password.length > 255) {
    throw new Error('Recovery password must be 12-255 characters');
  }
  const salt = randomBytes(16);
  const iv = randomBytes(12);
  const wrappingKey = await deriveRecoveryKey(password, salt, 32);
  const cipher = createCipheriv('aes-256-gcm', wrappingKey, iv);
  const ciphertext = Buffer.concat([cipher.update(key), cipher.final()]);
  const payload = { format: RECOVERY_FORMAT, version: 1, kdf: 'scrypt',
    salt: salt.toString('base64'), iv: iv.toString('base64'),
    tag: cipher.getAuthTag().toString('base64'), ciphertext: ciphertext.toString('base64') };
  return Buffer.from(JSON.stringify(payload), 'utf8');
}

async function decryptRecoveryKey(bytes: Buffer, password: string): Promise<Buffer> {
  const payloadBytes = Buffer.from(bytes);
  if (payloadBytes.length === 0 || payloadBytes.length > 16 * 1024) throw new Error('Invalid recovery file size');
  if (typeof password !== 'string' || password.length < 12 || password.length > 255) {
    throw new Error('Invalid recovery password');
  }
  let payload: any;
  try { payload = JSON.parse(payloadBytes.toString('utf8')); } catch { throw new Error('Corrupt recovery file'); }
  if (!payload || payload.format !== RECOVERY_FORMAT || payload.version !== 1 || payload.kdf !== 'scrypt') {
    throw new Error('Unsupported recovery file format');
  }
  const decodeField = (value: string, expectedLength: number, label: string): Buffer => {
    if (typeof value !== 'string' || !/^[A-Za-z0-9+/]+={0,2}$/.test(value)) throw new Error(`Invalid ${label}`);
    const decoded = Buffer.from(value, 'base64');
    if (decoded.length !== expectedLength) throw new Error(`Invalid ${label} length`);
    return decoded;
  };
  const salt = decodeField(payload.salt, 16, 'salt');
  const iv = decodeField(payload.iv, 12, 'iv');
  const tag = decodeField(payload.tag, 16, 'tag');
  const ciphertext = decodeField(payload.ciphertext, 32, 'ciphertext');
  const wrappingKey = await deriveRecoveryKey(password, salt, 32);
  const decipher = createDecipheriv('aes-256-gcm', wrappingKey, iv);
  decipher.setAuthTag(tag);
  const key = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  if (key.length !== 32) throw new Error('Invalid recovered key');
  return key;
}


test('backup encryption: database bytes are encrypted with AES-256-GCM and not readable as plaintext', async () => {
  const db = DatabaseManager.getInstance();
  await db.initialize();
  const key = randomBytes(32);

  const plaintext = Buffer.from('SQLite format 3\0' + JSON.stringify({ sensitive: 'financial data' }), 'utf8');
  const encrypted = encryptDbBytes(plaintext, key);

  assert.ok(!encrypted.subarray(0, 15).equals(Buffer.from('SQLite format 3\0', 'binary')), 'encrypted backup must not expose SQLite header');
  assert.ok(!encrypted.toString('utf8').includes('financial data'), 'encrypted backup must not contain plaintext data');

  const decrypted = decryptDbBytes(encrypted, key);
  assert.ok(decrypted.toString('utf8').includes('financial data'), 'decryption must restore original data');
});

test('backup encryption: wrong key must fail closed (GCM auth tag verification)', async () => {
  const keyA = randomBytes(32);
  const keyB = randomBytes(32);
  const plaintext = Buffer.from('secret data', 'utf8');
  const encrypted = encryptDbBytes(plaintext, keyA);

  assert.throws(() => decryptDbBytes(encrypted, keyB), /تعذر|فشل|auth|tag|decrypt/,
    'decryption with wrong key must fail closed');
});

test('recovery key: encrypt and decrypt database key with strong password (scrypt)', async () => {
  const dbKey = randomBytes(32);
  const password = 'C3ramisys_R3c0very_2026!';
  const encrypted = await encryptRecoveryKey(dbKey, password);
  const recovered = await decryptRecoveryKey(encrypted, password);
  assert.ok(recovered.equals(dbKey), 'recovery key must round-trip the original database key');
});

test('recovery key: wrong recovery password must fail', async () => {
  const dbKey = randomBytes(32);
  const encrypted = await encryptRecoveryKey(dbKey, 'CorrectP@ssword2026!');
  await assert.rejects(() => decryptRecoveryKey(encrypted, 'WrongP@ssword2026!'),
    /تعذر|فشل|Invalid|corrupt/,
    'wrong recovery password must fail');
});

test('restore on different device: database key is bound to device safeStorage, recovery key needed', async () => {
  const dbKey = randomBytes(32);
  const recoveryPassword = 'DeviceTransfer_R3c0very_2026!';
  const encryptedRecovery = await encryptRecoveryKey(dbKey, recoveryPassword);

  const recoveredKey = await decryptRecoveryKey(encryptedRecovery, recoveryPassword);
  assert.ok(recoveredKey.equals(dbKey), 'different device can restore using recovery key + password');

  await assert.rejects(() => decryptRecoveryKey(encryptedRecovery, ''),
    /متنوعة|12|255|Invalid/,
    'empty recovery password must be rejected');
});

test('encrypted backup file integrity: decrypted backup preserves byte length and header', async () => {
  const db = DatabaseManager.getInstance();
  await db.initialize();
  const key = randomBytes(32);

  const testData = Buffer.from('SQLite format 3\0' + Buffer.alloc(4096), 'utf8');
  const encrypted = encryptDbBytes(testData, key);
  const decrypted = decryptDbBytes(encrypted, key);

  assert.equal(decrypted.length, testData.length, 'decrypted backup must preserve byte length');
  assert.ok(decrypted.subarray(0, 15).equals(Buffer.from('SQLite format 3\0', 'binary')),
    'decrypted backup must restore SQLite header');
});

import '../integration.setup.ts';
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { DatabaseManager } from '../../src/database/repositories/databaseManager.ts';
import { AuthService } from '../../src/services/domains/auth/AuthService.ts';
import { PermissionService } from '../../src/services/domains/auth/PermissionService.ts';
import { BranchAccessService } from '../../src/services/domains/auth/BranchAccessService.ts';
import { SalesService } from '../../src/services/domains/sales/SalesService.ts';
import { CustomerService } from '../../src/services/domains/customers/CustomerService.ts';
import type { User } from '../../src/types/auth/identity.ts';

const TS = String(Date.now());
const branchA = 'br_cross_a_' + TS;
const branchB = 'br_cross_b_' + TS;

const userA: User = {
  id: 'usr_cross_a_' + TS, username: 'cross-user-a-' + TS, fullName: 'Cross User A',
  role: 'SALES', isActive: true, createdAt: '', updatedAt: '',
};
const userB: User = {
  id: 'usr_cross_b_' + TS, username: 'cross-user-b-' + TS, fullName: 'Cross User B',
  role: 'SALES', isActive: true, createdAt: '', updatedAt: '',
};

function asUser(user: User): void {
  AuthService.setCurrentUser(user);
  PermissionService.invalidate(user);
}

async function boot(db: DatabaseManager): Promise<void> {
  await db.initialize();
  PermissionService.seed();

  db.run(`INSERT OR IGNORE INTO branches (id, code, name, is_main, is_active, company_id)
   VALUES ('${branchA}','BR-A-${TS}','Branch A ${TS}',1,1,'cmp_main'),
          ('${branchB}','BR-B-${TS}','Branch B ${TS}',0,1,'cmp_main')`);
  db.run(`INSERT OR IGNORE INTO warehouses (id, name, code, branch_id, is_active, company_id)
   VALUES ('wh_a_${TS}','Warehouse A','WA-${TS}','${branchA}',1,'cmp_main'),
          ('wh_b_${TS}','Warehouse B','WB-${TS}','${branchB}',1,'cmp_main')`);
  db.run(`INSERT OR IGNORE INTO users (id, username, password_hash, full_name, role, is_active, branch_scope)
   VALUES ('${userA.id}','${userA.username}','test','${userA.fullName}','${userA.role}',1,'ASSIGNED')`);
  db.run(`INSERT OR IGNORE INTO users_branches (user_id, branch_id) VALUES ('${userA.id}','${branchA}')`);
  db.run(`INSERT OR IGNORE INTO users (id, username, password_hash, full_name, role, is_active, branch_scope)
   VALUES ('${userB.id}','${userB.username}','test','${userB.fullName}','${userB.role}',1,'ASSIGNED')`);
  db.run(`INSERT OR IGNORE INTO users_branches (user_id, branch_id) VALUES ('${userB.id}','${branchB}')`);
  for (const user of [userA, userB]) {
    for (const p of ['sales.view','sales.create','sales.delete','purchases.view','purchases.create',
      'inventory.view','customers.view','suppliers.view','products.view','finance.view','reports.view']) {
      db.run(`INSERT OR IGNORE INTO user_permissions (user_id, permission_code, effect) VALUES ('${user.id}','${p}','GRANT')`);
    }
  }
}

function seedCustomer(db: DatabaseManager, id: string, branchId: string): void {
  db.run(`INSERT OR IGNORE INTO customers (id, code, name, phone, branch_id, company_id, current_balance, total_purchases)
   VALUES ('${id}','CUST-${id}','عميل اختبار ${branchId}','01000000000','${branchId}','cmp_main',0,0)`);
}

test('cross-branch: user B cannot see user A customers', async () => {
  const db = DatabaseManager.getInstance();
  await boot(db);
  seedCustomer(db, 'cust_a_' + TS, branchA);
  seedCustomer(db, 'cust_b_' + TS, branchB);

  const allCustomers = db.query<{ id: string; branch_id: string }>('SELECT id, branch_id FROM customers WHERE id LIKE ?', ['cust_%_' + TS]);
  assert.ok(allCustomers.length >= 2, 'both customers are stored');

  // مستخدم B يمتلك نطاق فرع B فقط
  asUser(userB);
  const access = new BranchAccessService();
  const accessibleB = access.getAccessibleBranchIds(userB);
  assert.ok(accessibleB.includes(branchB), 'user B should access branch B');
  assert.ok(!accessibleB.includes(branchA), 'user B must not access branch A via branch scope');

  // استعلام scoped يجب أن يعيد فقط عملاء فرع B
  const branchBCustomers = db.query<{ id: string }>(
    `SELECT id FROM customers WHERE branch_id = ? AND id LIKE ?`, [branchB, 'cust_%_' + TS]
  );
  assert.ok(branchBCustomers.length >= 1, 'branch B customers visible');
  assert.ok(!branchBCustomers.some((c) => c.id === 'cust_a_' + TS), 'branch A customers hidden from branch B scope');
});

test('cross-branch: branch SQL scope rejects foreign branch warehouse', async () => {
  const db = DatabaseManager.getInstance();
  await boot(db);
  asUser(userA);
  const access = new BranchAccessService();
  const accessible = access.getAccessibleBranchIds(userA);
  assert.ok(accessible.includes(branchA), 'user A should access branch A');
  assert.ok(!accessible.includes(branchB), 'user A must not access branch B');

  const scope = access.sqlScope('w.branch_id', undefined, userA);
  // النطاق يجب أن يحتوي على معرف الفرع A
  assert.ok(scope.params.includes(branchA), 'scope params must include branch A');
  assert.ok(!scope.params.includes(branchB), 'scope params must not include branch B');
});

test('cross-branch: admin with ALL scope can see all branches', async () => {
  const db = DatabaseManager.getInstance();
  await boot(db);
  const admin: User = { id: 'usr_cross_admin_' + TS, username: 'cross-admin-' + TS, fullName: 'Cross Admin',
    role: 'ADMIN', isActive: true, createdAt: '', updatedAt: '' };
  db.run(`INSERT INTO users (id, username, password_hash, full_name, role, is_active, branch_scope)
   VALUES ('${admin.id}','${admin.username}','test','${admin.fullName}','${admin.role}',1,'ALL')`);
  asUser(admin);
  const access = new BranchAccessService();
  assert.equal(access.getAccessibleBranchIds(admin), null, 'ADMIN with ALL scope returns null (unrestricted)');
});

